INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '127d1098-f307-5ec2-aade-6d67ce9ae0ae', id, 'hajj-madinah-visit', '{"bn": "মদিনা জিয়ারত ও তার আদব", "en": "Visiting Madinah and its etiquette"}', '{"bn": "মসজিদে নববী, রওজা মুবারকে সালাম, রিয়াজুল জান্নাহ, কুবা ও বাকি কবরস্থান জিয়ারতের নিয়ম।", "en": "Masjid an-Nabawi, greeting the Prophet at his grave, the Rawdah, Quba and the Baqi'' cemetery."}', 'basic', '[{"type": "text", "text": {"bn": "মদিনা জিয়ারত হজের অংশ নয়, হজের আগে বা পরে করা একটি বরকতময় সুন্নত আমল। সফরের নিয়ত হবে মসজিদে নববীতে নামাজ পড়া; সেখানে পৌঁছে নবী (সা.)-এর রওজায় সালাম দেবেন।", "en": "Visiting Madinah is not part of hajj; it is a blessed sunnah done before or after hajj. The intention of travel is to pray in the Prophet''s Masjid; once there, you greet the Prophet at his grave."}}, {"type": "list", "items": [{"bn": "তিনটি মসজিদ ছাড়া অন্য কোনো স্থানের উদ্দেশ্যে (ইবাদতের নিয়তে) বিশেষ সফর করা যায় না: মসজিদুল হারাম, মসজিদে নববী ও মসজিদুল আকসা।", "en": "Special journeys for worship are made only to three masjids: Al-Masjid al-Haram, the Prophet''s Masjid and Al-Masjid al-Aqsa."}, {"bn": "মসজিদে নববীতে এক নামাজ মসজিদুল হারাম ছাড়া অন্য মসজিদের এক হাজার নামাজের চেয়ে উত্তম।", "en": "One prayer in the Prophet''s Masjid is better than a thousand elsewhere, except Al-Masjid al-Haram."}, {"bn": "নবী (সা.)-এর ঘর ও মিম্বারের মাঝের অংশ জান্নাতের বাগানগুলোর একটি (রিয়াজুল জান্নাহ)।", "en": "The area between the Prophet''s house and his pulpit is one of the gardens of Paradise (the Rawdah)."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১১৮৯; সহিহ বুখারি ১১৯০; সহিহ বুখারি ১১৯৬", "en": "Sahih al-Bukhari 1189; Sahih al-Bukhari 1190; Sahih al-Bukhari 1196"}}, {"type": "note", "tone": "info", "text": {"bn": "''মসজিদে নববীতে একটানা চল্লিশ ওয়াক্ত নামাজ'' সম্পর্কিত হাদিসটির সনদ দুর্বল; এটি জরুরি মনে করে সফরসূচি বানানোর দরকার নেই, তবে যত বেশি জামাতে নামাজ পড়তে পারেন ততই ভালো।", "en": "The hadith about praying forty consecutive prayers in the Prophet''s Masjid has a weak chain; there is no need to plan the trip around it, though praying as many congregational prayers there as you can is good."}}, {"type": "step", "title": {"bn": "মসজিদে প্রবেশ", "en": "Entering the masjid"}, "text": {"bn": "ডান পা দিয়ে প্রবেশ করে দোয়া পড়ুন, তারপর সম্ভব হলে রিয়াজুল জান্নাহয়, নইলে যেকোনো স্থানে দুই রাকাত তাহিয়্যাতুল মসজিদ পড়ুন।", "en": "Enter with the right foot and say the dua, then pray two rakats of greeting in the Rawdah if possible, otherwise anywhere."}}, {"type": "arabic", "label": {"bn": "মসজিদে প্রবেশের দোয়া", "en": "Dua on entering the masjid"}, "ar": "اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ", "pron": {"bn": "আল্লাহুম্মাফতাহ লী আবওয়াবা রাহমাতিক", "en": "Allahummaftah li abwaba rahmatik"}, "meaning": {"bn": "হে আল্লাহ! আমার জন্য তোমার রহমতের দরজাগুলো খুলে দাও।", "en": "O Allah, open for me the doors of Your mercy."}, "ref": {"bn": "সহিহ মুসলিম ৭১৩", "en": "Sahih Muslim 713"}}, {"type": "step", "title": {"bn": "রওজায় সালাম", "en": "Greeting at the grave"}, "text": {"bn": "ধীরে, আদবের সাথে রওজার সামনে গিয়ে নিচু স্বরে নবী (সা.)-কে সালাম দিন, তারপর একটু ডানে সরে আবু বকর (রা.)-কে এবং আরেকটু ডানে উমর (রা.)-কে সালাম দিন।", "en": "Approach the grave slowly and respectfully and greet the Prophet in a low voice, then move a little to the right to greet Abu Bakr, and a little further to greet Umar."}}, {"type": "arabic", "label": {"bn": "রওজায় সালাম (ইবনে উমর রা.-এর আমল থেকে)", "en": "Greeting at the grave (from Ibn Umar''s practice)"}, "ar": "السَّلَامُ عَلَيْكَ يَا رَسُولَ اللَّهِ، السَّلَامُ عَلَيْكَ يَا أَبَا بَكْرٍ، السَّلَامُ عَلَيْكَ يَا عُمَرُ", "pron": {"bn": "আসসালামু আলাইকা ইয়া রাসূলাল্লাহ, আসসালামু আলাইকা ইয়া আবা বাকর, আসসালামু আলাইকা ইয়া উমার", "en": "As-salamu ''alayka ya rasulallah, as-salamu ''alayka ya aba bakr, as-salamu ''alayka ya ''umar"}, "meaning": {"bn": "হে আল্লাহর রাসুল, আপনার ওপর শান্তি বর্ষিত হোক। হে আবু বকর, আপনার ওপর শান্তি। হে উমর, আপনার ওপর শান্তি।", "en": "Peace be upon you, O Messenger of Allah. Peace be upon you, O Abu Bakr. Peace be upon you, O Umar."}, "ref": {"bn": "মুয়াত্তা মালিক (ইবনে উমর রা.-এর আমল)", "en": "Muwatta Malik (practice of Ibn Umar)"}, "check": true}, {"type": "note", "tone": "warn", "text": {"bn": "আদব: কণ্ঠস্বর নিচু রাখুন (সূরা হুজুরাত ৪৯:২)। নিজের জন্য দোয়া করার সময় কবরের দিকে নয়, কিবলামুখী হোন। জালি বা দেয়াল স্পর্শ, চুম্বন, কবরের দিকে সিজদা বা তাওয়াফ করবেন না; নবী (সা.)-এর কাছে নয়, আল্লাহর কাছে চাইবেন। ভিড়ে ধাক্কাধাক্কি করবেন না।", "en": "Etiquette: keep your voice low (Al-Hujurat 49:2). When making dua for yourself, face the qiblah, not the grave. Do not touch or kiss the grille or walls, prostrate or circle towards the grave; ask Allah, not the Prophet. Do not push in the crowd."}}, {"type": "step", "title": {"bn": "দরুদ", "en": "Salawat"}, "text": {"bn": "মদিনায় অবস্থানকালে বেশি বেশি দরুদ পড়ুন; নামাজের দরুদে ইবরাহিম সর্বোত্তম।", "en": "While in Madinah send abundant blessings on the Prophet; the Ibrahimi salawat of the prayer is best."}}, {"type": "step", "title": {"bn": "মসজিদে কুবা", "en": "Masjid Quba"}, "text": {"bn": "ঘর থেকে ওজু করে মসজিদে কুবায় গিয়ে দুই রাকাত নামাজ পড়া সুন্নত; নবী (সা.) প্রতি শনিবার কুবায় যেতেন। কুবায় নামাজ একটি উমরাহর সমান সওয়াবের কথা হাদিসে এসেছে।", "en": "It is sunnah to make wudu at home, go to Masjid Quba and pray two rakats; the Prophet went to Quba every Saturday. A hadith says a prayer in Quba is like the reward of an umrah."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১১৯৩", "en": "Sahih al-Bukhari 1193"}}, {"type": "ref", "text": {"bn": "সুনান ইবনে মাজাহ; জামে তিরমিজি (কুবায় নামাজ উমরাহর সমতুল্য)", "en": "Sunan Ibn Majah; Jami'' at-Tirmidhi (prayer in Quba equal to an umrah)"}, "check": true}, {"type": "step", "title": {"bn": "জান্নাতুল বাকি ও উহুদ", "en": "Al-Baqi'' and Uhud"}, "text": {"bn": "জান্নাতুল বাকি কবরস্থান এবং উহুদের শহীদদের কবর জিয়ারত করে সালাম দিন ও তাদের জন্য দোয়া করুন। পুরুষরা কবর জিয়ারত করবেন; নারীদের কবর জিয়ারত নিয়ে মতভেদ আছে।", "en": "Visit the Baqi'' cemetery and the martyrs of Uhud, greet them and pray for them. Men visit graves; scholars differ on women visiting graves."}}, {"type": "arabic", "label": {"bn": "কবর জিয়ারতের দোয়া", "en": "Dua when visiting graves"}, "ar": "السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ لَلَاحِقُونَ، أَسْأَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ", "pron": {"bn": "আসসালামু আলাইকুম আহলাদ দিয়ারি মিনাল মু''মিনীনা ওয়াল মুসলিমীন, ওয়া ইন্না ইনশাআল্লাহু লালাহিকূন, আসআলুল্লাহা লানা ওয়া লাকুমুল আফিয়াহ", "en": "As-salamu ''alaykum ahlad-diyari minal-mu''minina wal-muslimin, wa inna in sha Allahu lalahiqun, as''alullaha lana wa lakumul-''afiyah"}, "meaning": {"bn": "হে এই ঘরের অধিবাসী মুমিন ও মুসলিমগণ, তোমাদের ওপর শান্তি বর্ষিত হোক। আল্লাহ চাইলে আমরাও তোমাদের সাথে মিলিত হব। আমি আল্লাহর কাছে আমাদের ও তোমাদের জন্য নিরাপত্তা চাই।", "en": "Peace be upon you, people of these dwellings, of the believers and the Muslims. We will, if Allah wills, join you. I ask Allah for well-being for us and for you."}, "ref": {"bn": "সহিহ মুসলিম ৯৭৫", "en": "Sahih Muslim 975"}}, {"type": "note", "tone": "tip", "text": {"bn": "মদিনার বাসিন্দাদের সাথে নম্র আচরণ করুন, শহরের পবিত্রতা রক্ষা করুন এবং বেশি বেশি নফল নামাজ, কুরআন তিলাওয়াত ও দোয়ায় সময় কাটান।", "en": "Be gentle with the people of Madinah, respect the sanctity of the city, and spend your time in voluntary prayer, Quran and dua."}}]', 'in_review', 90 FROM is_guide_topics WHERE slug = 'hajj' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '20c65bb3-c154-588d-a1d2-1d890a537d0b', id, 'umrah-basics', '{"bn": "উমরাহ: হুকুম, ফজিলত ও এক নজরে", "en": "Umrah: ruling, virtues and overview"}', '{"bn": "উমরাহ কী, এর হুকুম ও ফজিলত, আর পুরো উমরাহ এক নজরে।", "en": "What umrah is, its ruling and virtues, and the whole umrah at a glance."}', 'basic', '[{"type": "text", "text": {"bn": "উমরাহ মানে নির্দিষ্ট নিয়মে বায়তুল্লাহর জিয়ারত: ইহরাম, তাওয়াফ, সাফা-মারওয়ার সাঈ এবং মাথা মুণ্ডন বা চুল ছোট করা। হজের মতো নির্দিষ্ট দিন নেই; বছরের যেকোনো সময় করা যায় (হানাফি মতে ৯ থেকে ১৩ জিলহজ উমরাহ করা মাকরুহ)।", "en": "Umrah is visiting the House of Allah in a set way: ihram, tawaf, sa''i between Safa and Marwah, and shaving or shortening the hair. Unlike hajj it has no fixed days and may be done any time of the year (Hanafis dislike umrah on 9–13 Dhul Hijjah)."}}, {"type": "arabic", "ar": "وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ", "pron": {"bn": "ওয়া আতিম্মুল হাজ্জা ওয়াল উমরাতা লিল্লাহ", "en": "Wa atimmul-hajja wal-''umrata lillah"}, "meaning": {"bn": "আর আল্লাহর জন্য হজ ও উমরাহ পূর্ণ করো।", "en": "And complete the hajj and umrah for Allah."}, "ref": {"bn": "সূরা বাকারা ২:১৯৬", "en": "Al-Baqarah 2:196"}}, {"type": "differ", "title": {"bn": "উমরাহর হুকুম", "en": "Ruling on umrah"}, "views": [{"label": {"bn": "হানাফি ও মালেকি", "en": "Hanafi and Maliki"}, "text": {"bn": "জীবনে একবার উমরাহ করা সুন্নতে মুয়াক্কাদা (জোরালো সুন্নত), ফরজ নয়।", "en": "Performing umrah once in a lifetime is an emphasised sunnah, not obligatory."}, "evidence": {"bn": "জাবির (রা.)-এর হাদিস: উমরাহ ওয়াজিব কি না জিজ্ঞেস করা হলে নবী (সা.) বললেন, না, তবে উমরাহ করা উত্তম (তিরমিজি)। আয়াতে ''পূর্ণ করো'' বলা হয়েছে শুরু করার পর, শুরু করা আবশ্যক এমন নয়।", "en": "Hadith of Jabir: asked whether umrah is obligatory, the Prophet said no, but doing it is better (Tirmidhi). The verse says ''complete'' once begun, not that beginning is required."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "সামর্থ্যবানের ওপর জীবনে একবার উমরাহ করা ওয়াজিব (ফরজের মতো আবশ্যক)।", "en": "Umrah is obligatory once in a lifetime for those able."}, "evidence": {"bn": "আয়াতে হজের সাথে উমরাহকেও একই নির্দেশে রাখা হয়েছে; আয়েশা (রা.)-এর হাদিস: নারীদের জিহাদ হলো হজ ও উমরাহ (ইবনে মাজাহ)।", "en": "The verse joins umrah with hajj in one command; Aishah''s hadith: the jihad of women is hajj and umrah (Ibn Majah)."}}], "check": true}, {"type": "heading", "text": {"bn": "ফজিলত", "en": "Virtues"}}, {"type": "list", "items": [{"bn": "এক উমরাহ থেকে আরেক উমরাহ, এর মাঝের গুনাহের কাফফারা।", "en": "One umrah to the next is an expiation for what is between them."}, {"bn": "রমজানে উমরাহ একটি হজের সমান সওয়াব (তবে এটি ফরজ হজের বদলে যথেষ্ট নয়)।", "en": "An umrah in Ramadan equals a hajj in reward (though it does not replace the obligatory hajj)."}]}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৭৭৩; সহিহ বুখারি ১৭৮২; সহিহ মুসলিম ১২৫৬", "en": "Sahih al-Bukhari 1773; Sahih al-Bukhari 1782; Sahih Muslim 1256"}}, {"type": "heading", "text": {"bn": "উমরাহ এক নজরে", "en": "Umrah at a glance"}}, {"type": "table", "head": [{"bn": "ধাপ", "en": "Step"}, {"bn": "কাজ", "en": "What to do"}, {"bn": "হানাফি মতে হুকুম", "en": "Hanafi ruling"}], "rows": [[{"bn": "১", "en": "1"}, {"bn": "মিকাতে বা আগে ইহরাম: নিয়ত ও তালবিয়া", "en": "Ihram at or before the miqat: intention and talbiyah"}, {"bn": "শর্ত (ফরজ)", "en": "Condition (farz)"}], [{"bn": "২", "en": "2"}, {"bn": "মসজিদুল হারামে প্রবেশ ও কাবার তাওয়াফ, সাত চক্কর", "en": "Enter Al-Masjid al-Haram and circle the Ka''bah seven times"}, {"bn": "রুকন (ফরজ)", "en": "Pillar (farz)"}], [{"bn": "৩", "en": "3"}, {"bn": "মাকামে ইবরাহিমের পেছনে দুই রাকাত নামাজ", "en": "Two rakats behind Maqam Ibrahim"}, {"bn": "ওয়াজিব", "en": "Wajib"}], [{"bn": "৪", "en": "4"}, {"bn": "জমজমের পানি পান", "en": "Drink Zamzam"}, {"bn": "সুন্নত/মুস্তাহাব", "en": "Sunnah"}], [{"bn": "৫", "en": "5"}, {"bn": "সাফা থেকে মারওয়া, সাত চক্কর সাঈ", "en": "Sa''i: seven laps from Safa to Marwah"}, {"bn": "ওয়াজিব (অন্য তিন মাজহাবে রুকন)", "en": "Wajib (a pillar in the other three schools)"}], [{"bn": "৬", "en": "6"}, {"bn": "মাথা মুণ্ডন বা চুল ছোট করা", "en": "Shave or shorten the hair"}, {"bn": "ওয়াজিব", "en": "Wajib"}]]}, {"type": "note", "tone": "info", "text": {"bn": "ইহরাম, নিষিদ্ধ কাজ ও মিকাতের বিস্তারিত হজ বিভাগের ''ইহরাম'' ও ''মিকাত'' গাইডে আছে; উমরাহতেও একই বিধান।", "en": "Details of ihram, its prohibitions and the miqat are in the hajj section''s ihram and miqat guides; the same rules apply to umrah."}}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'umrah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '332947de-6569-5d03-9129-db5a4eaf5d48', id, 'umrah-ihram-to-masjid', '{"bn": "উমরাহ: ইহরাম থেকে মসজিদুল হারাম", "en": "Umrah: from ihram to Al-Masjid al-Haram"}', '{"bn": "ইহরামের প্রস্তুতি, নিয়ত, তালবিয়া, মক্কায় প্রবেশ এবং মসজিদুল হারামে প্রবেশের আদব।", "en": "Preparing ihram, the intention, the talbiyah, entering Makkah and entering Al-Masjid al-Haram."}', 'basic', '[{"type": "step", "title": {"bn": "প্রস্তুতি", "en": "Preparation"}, "text": {"bn": "নখ কাটা, অবাঞ্ছিত লোম পরিষ্কার, গোসল (না পারলে ওজু)। পুরুষ শরীরে সুগন্ধি লাগাতে পারেন, ইহরামের কাপড়ে নয়।", "en": "Trim nails, remove unwanted hair, take a ghusl (or wudu). Men may perfume the body, not the ihram sheets."}}, {"type": "step", "title": {"bn": "পোশাক", "en": "Clothing"}, "text": {"bn": "পুরুষ: সেলাইবিহীন দুটি সাদা চাদর ও খোলা স্যান্ডেল, মাথা খোলা। নারী: সাধারণ শালীন পোশাক, নিকাব ও হাতমোজা ছাড়া।", "en": "Men: two unstitched white sheets and open sandals, head uncovered. Women: ordinary modest clothes, without niqab or gloves."}}, {"type": "step", "title": {"bn": "দুই রাকাত (সুন্নত)", "en": "Two rakats (sunnah)"}, "text": {"bn": "মাকরুহ সময় না হলে ইহরামের আগে দুই রাকাত নামাজ পড়ুন (হানাফি মত); অন্যদের মতে কোনো ফরজ নামাজের পরে ইহরাম বাঁধা উত্তম।", "en": "If not a disliked time, pray two rakats before ihram (Hanafi view); others prefer entering ihram after an obligatory prayer."}}, {"type": "step", "title": {"bn": "নিয়ত", "en": "Intention"}, "text": {"bn": "মিকাতে পৌঁছানোর আগে মনে মনে উমরাহর নিয়ত করুন। এটি মনের ইচ্ছা; মুখে বলা জরুরি নয়।", "en": "Before reaching the miqat, intend umrah in your heart. It is an intention of the heart; saying it is not required."}}, {"type": "arabic", "label": {"bn": "মুখে বলার একটি উদাহরণ (জরুরি নয়)", "en": "An example to say aloud (not required)"}, "ar": "لَبَّيْكَ عُمْرَةً", "pron": {"bn": "লাব্বাইকা উমরাতান", "en": "Labbayka ''umratan"}, "meaning": {"bn": "আমি উমরাহর জন্য হাজির।", "en": "Here I am for umrah."}}, {"type": "note", "tone": "tip", "text": {"bn": "আরেকটি প্রচলিত উদাহরণ: ''হে আল্লাহ! আমি উমরাহর নিয়ত করছি, তুমি তা আমার জন্য সহজ করো এবং কবুল করো।'' এটি কোনো হাদিসের নির্দিষ্ট বাক্য নয়; নিজের ভাষায় মনে মনে নিয়তই যথেষ্ট।", "en": "Another common example: ''O Allah, I intend umrah; make it easy for me and accept it from me.'' This is not fixed wording from a hadith; the intention in your heart, in any language, is enough."}}, {"type": "step", "title": {"bn": "তালবিয়া", "en": "Talbiyah"}, "text": {"bn": "নিয়তের পর তালবিয়া পড়লেই ইহরাম শুরু। এরপর ইহরামের সব নিষেধ মেনে চলবেন এবং তাওয়াফ শুরু পর্যন্ত বেশি বেশি তালবিয়া পড়বেন (পুরুষ উচ্চস্বরে, নারী নিচু স্বরে)।", "en": "With the talbiyah after the intention, ihram begins. From then on observe all ihram prohibitions and repeat the talbiyah often until starting tawaf (men aloud, women quietly)."}}, {"type": "arabic", "label": {"bn": "তালবিয়া", "en": "Talbiyah"}, "ar": "لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ", "pron": {"bn": "লাব্বাইকা আল্লাহুম্মা লাব্বাইক, লাব্বাইকা লা শারীকা লাকা লাব্বাইক, ইন্নাল হামদা ওয়ান নি''মাতা লাকা ওয়াল মুলক, লা শারীকা লাক", "en": "Labbayka Allahumma labbayk, labbayka la sharika laka labbayk, innal-hamda wan-ni''mata laka wal-mulk, la sharika lak"}, "meaning": {"bn": "আমি হাজির, হে আল্লাহ! আমি হাজির। আমি হাজির, তোমার কোনো শরিক নেই, আমি হাজির। নিশ্চয়ই সব প্রশংসা, সব নিয়ামত তোমারই, আর রাজত্বও তোমার; তোমার কোনো শরিক নেই।", "en": "Here I am, O Allah, here I am. Here I am, You have no partner, here I am. Surely all praise and blessings are Yours, and the dominion; You have no partner."}, "ref": {"bn": "সহিহ বুখারি ১৫৪৯; সহিহ মুসলিম ১১৮৪", "en": "Sahih al-Bukhari 1549; Sahih Muslim 1184"}}, {"type": "step", "title": {"bn": "মক্কায় প্রবেশ", "en": "Entering Makkah"}, "text": {"bn": "সম্ভব হলে মক্কায় প্রবেশের আগে গোসল করা সুন্নত। হোটেলে মালপত্র রেখে, বিশ্রাম নিয়ে, ওজু করে মসজিদুল হারামে যান।", "en": "If possible, take a ghusl before entering Makkah (sunnah). Leave your bags at the hotel, rest, make wudu and go to Al-Masjid al-Haram."}}, {"type": "step", "title": {"bn": "মসজিদে প্রবেশ", "en": "Entering the masjid"}, "text": {"bn": "ডান পা দিয়ে প্রবেশ করে মসজিদে প্রবেশের দোয়া পড়ুন।", "en": "Enter with the right foot and say the dua for entering the masjid."}}, {"type": "arabic", "label": {"bn": "মসজিদে প্রবেশের দোয়া", "en": "Dua on entering the masjid"}, "ar": "بِسْمِ اللَّهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَىٰ رَسُولِ اللَّهِ، اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ", "pron": {"bn": "বিসমিল্লাহি, ওয়াস সালাতু ওয়াস সালামু আলা রাসূলিল্লাহ, আল্লাহুম্মাফতাহ লী আবওয়াবা রাহমাতিক", "en": "Bismillahi, was-salatu was-salamu ''ala rasulillah, Allahummaftah li abwaba rahmatik"}, "meaning": {"bn": "আল্লাহর নামে; আল্লাহর রাসুলের ওপর দরুদ ও সালাম। হে আল্লাহ! আমার জন্য তোমার রহমতের দরজাগুলো খুলে দাও।", "en": "In the name of Allah, and blessings and peace on the Messenger of Allah. O Allah, open for me the doors of Your mercy."}, "ref": {"bn": "সহিহ মুসলিম ৭১৩", "en": "Sahih Muslim 713"}}, {"type": "note", "tone": "info", "text": {"bn": "সহিহ মুসলিমে মূল অংশ ''আল্লাহুম্মাফতাহ লী আবওয়াবা রাহমাতিক''; শুরুতে বিসমিল্লাহ ও দরুদ অন্য হাদিসগ্রন্থের বর্ণনায় এসেছে।", "en": "Sahih Muslim has the core ''Allahummaftah li abwaba rahmatik''; the Bismillah and salawat at the start come in other hadith collections."}}, {"type": "note", "tone": "tip", "text": {"bn": "কাবা প্রথম দেখার সময় নির্দিষ্ট কোনো সহিহ দোয়া প্রমাণিত নেই; এ সম্পর্কে প্রচলিত বর্ণনাগুলো দুর্বল। মন থেকে যেকোনো দোয়া করুন।", "en": "No specific authentic dua is established for first seeing the Ka''bah; the popular reports are weak. Make any dua from the heart."}}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'umrah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '702aa109-0a55-561c-a694-a1ad1079b5c9', id, 'umrah-tawaf', '{"bn": "উমরাহ: তাওয়াফ, দুই রাকাত ও জমজম", "en": "Umrah: tawaf, two rakats and Zamzam"}', '{"bn": "হাজরে আসওয়াদ থেকে সাত চক্কর তাওয়াফ, রুকনে ইয়ামানি ও হাজরে আসওয়াদের মাঝের দোয়া, মাকামে ইবরাহিমে নামাজ ও জমজম।", "en": "Seven rounds of tawaf from the Black Stone, the dua between the Yemeni corner and the Black Stone, prayer at Maqam Ibrahim and Zamzam."}', 'basic', '[{"type": "step", "title": {"bn": "ওজু ও প্রস্তুতি", "en": "Wudu and preparation"}, "text": {"bn": "ওজু অবস্থায় তাওয়াফ করবেন। পুরুষরা চাদরের মাঝখান ডান বগলের নিচ দিয়ে এনে বাম কাঁধে রাখবেন, ডান কাঁধ খোলা থাকবে (ইজতিবা) — শুধু এই তাওয়াফের সময়।", "en": "Perform tawaf in wudu. Men pass the middle of the upper sheet under the right arm and over the left shoulder, leaving the right shoulder bare (idtiba'') — only during this tawaf."}}, {"type": "differ", "title": {"bn": "তাওয়াফে ওজুর হুকুম", "en": "Wudu for tawaf"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "ওজু ওয়াজিব; ওজু ছাড়া তাওয়াফ করলে তাওয়াফ হয়ে যায়, তবে দম বা সদকা দিতে হয় (অথবা ওজু করে আবার তাওয়াফ করলে মাফ)।", "en": "Wudu is wajib; a tawaf without wudu counts, but a dam or charity is due (or it is waived by repeating the tawaf with wudu)."}, "evidence": {"bn": "কুরআনে শুধু তাওয়াফের নির্দেশ এসেছে; পবিত্রতা হাদিস থেকে প্রমাণিত, তাই ওয়াজিব স্তরে।", "en": "The Quran commands tawaf alone; purity is established by hadith, hence wajib."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "ওজু তাওয়াফের শর্ত; ওজু ছাড়া তাওয়াফ সহিহ হবে না।", "en": "Wudu is a condition; tawaf without it is not valid."}, "evidence": {"bn": "হাদিস: ''বায়তুল্লাহর তাওয়াফ নামাজের মতো, তবে এতে কথা বলা বৈধ'' (তিরমিজি); নবী (সা.) তাওয়াফের আগে ওজু করেছেন।", "en": "Hadith: ''Tawaf around the House is like prayer, except that speaking is allowed'' (Tirmidhi); the Prophet made wudu before tawaf."}}]}, {"type": "step", "title": {"bn": "হাজরে আসওয়াদ থেকে শুরু", "en": "Start at the Black Stone"}, "text": {"bn": "হাজরে আসওয়াদ বরাবর (সবুজ বাতির দাগ) দাঁড়িয়ে কাবার দিকে মুখ করুন। সম্ভব হলে পাথরটি চুম্বন করুন, না হলে হাত দিয়ে স্পর্শ করে হাতে চুমু দিন, তাও না পারলে দূর থেকে ডান হাত তুলে ইশারা করুন (ইশারা করা হাতে চুমু খাবেন না) এবং বলুন:", "en": "Stand in line with the Black Stone (marked by a green light) facing the Ka''bah. Kiss the stone if possible; if not, touch it with your hand and kiss the hand; if not, raise your right hand towards it from a distance (do not kiss the hand after pointing) and say:"}}, {"type": "arabic", "label": {"bn": "হাজরে আসওয়াদের সামনে", "en": "At the Black Stone"}, "ar": "بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ", "pron": {"bn": "বিসমিল্লাহি ওয়াল্লাহু আকবার", "en": "Bismillahi wallahu akbar"}, "meaning": {"bn": "আল্লাহর নামে, আল্লাহ সবচেয়ে মহান।", "en": "In the name of Allah, and Allah is the Greatest."}, "ref": {"bn": "সহিহ বুখারি (তাকবির); বিসমিল্লাহ অংশ ইবনে উমর রা.-এর আমল", "en": "Sahih al-Bukhari (the takbir); the Bismillah is from Ibn Umar''s practice"}, "check": true}, {"type": "step", "title": {"bn": "সাত চক্কর", "en": "Seven rounds"}, "text": {"bn": "কাবাকে বাম দিকে রেখে ঘুরতে থাকুন। হাতিমের (অর্ধবৃত্তাকার দেয়াল) বাইরে দিয়ে ঘুরবেন, কারণ এটি কাবার অংশ। প্রতিবার হাজরে আসওয়াদ বরাবর এলে এক চক্কর পূর্ণ হয়; প্রতিবার ইশারা করে ''আল্লাহু আকবার'' বলুন।", "en": "Walk with the Ka''bah on your left, outside the Hatim (the semicircular wall), since it is part of the Ka''bah. Each time you reach the Black Stone line one round is complete; point to it and say ''Allahu akbar'' each time."}}, {"type": "step", "title": {"bn": "রমল (পুরুষ)", "en": "Ramal (men)"}, "text": {"bn": "প্রথম তিন চক্করে পুরুষরা কাঁধ দুলিয়ে ছোট ছোট কদমে একটু দ্রুত হাঁটবেন; বাকি চার চক্কর স্বাভাবিকভাবে। ভিড়ে সম্ভব না হলে ছেড়ে দিন।", "en": "In the first three rounds men walk briskly with short steps, moving the shoulders; the remaining four at a normal pace. Skip it if the crowd makes it impossible."}}, {"type": "step", "title": {"bn": "রুকনে ইয়ামানি", "en": "The Yemeni corner"}, "text": {"bn": "হাজরে আসওয়াদের আগের কোণ রুকনে ইয়ামানি। সহজে সম্ভব হলে ডান হাতে স্পর্শ করুন, চুম্বন করবেন না; ভিড়ে স্পর্শ করা না গেলে ইশারাও করতে হবে না।", "en": "The corner before the Black Stone is the Yemeni corner. Touch it with your right hand if easy, without kissing; if the crowd prevents it, no gesture is needed."}}, {"type": "arabic", "label": {"bn": "রুকনে ইয়ামানি ও হাজরে আসওয়াদের মাঝে", "en": "Between the Yemeni corner and the Black Stone"}, "ar": "رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ", "pron": {"bn": "রাব্বানা আতিনা ফিদ দুনইয়া হাসানাতাও ওয়া ফিল আখিরাতি হাসানাতাও ওয়া কিনা আযাবান নার", "en": "Rabbana atina fid-dunya hasanatan wa fil-akhirati hasanatan wa qina ''adhaban-nar"}, "meaning": {"bn": "হে আমাদের রব! আমাদের দুনিয়াতে কল্যাণ দাও, আখিরাতেও কল্যাণ দাও এবং আমাদের জাহান্নামের আজাব থেকে রক্ষা করো।", "en": "Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire."}, "ref": {"bn": "সুনান আবু দাউদ ১৮৯২; সূরা বাকারা ২:২০১", "en": "Sunan Abi Dawud 1892; Al-Baqarah 2:201"}}, {"type": "note", "tone": "tip", "text": {"bn": "এই অংশ ছাড়া তাওয়াফের জন্য নির্দিষ্ট কোনো দোয়া নেই। বইয়ে ''প্রথম চক্করের দোয়া, দ্বিতীয় চক্করের দোয়া'' যা দেখা যায়, তা হাদিসে নেই। নিজের ভাষায় দোয়া, জিকির, ইস্তিগফার বা কুরআন তিলাওয়াত করুন।", "en": "Apart from this part, tawaf has no set duas. The ''dua of the first round, second round'' found in booklets is not from the hadith. Make dua in your own language, do dhikr, seek forgiveness or recite Quran."}}, {"type": "step", "title": {"bn": "তাওয়াফ শেষ", "en": "Finishing tawaf"}, "text": {"bn": "সপ্তম চক্কর শেষে হাজরে আসওয়াদ বরাবর এসে তাওয়াফ শেষ। এবার ডান কাঁধ ঢেকে নিন।", "en": "Tawaf ends on reaching the Black Stone line after the seventh round. Now cover the right shoulder."}}, {"type": "step", "title": {"bn": "মাকামে ইবরাহিমে দুই রাকাত", "en": "Two rakats at Maqam Ibrahim"}, "text": {"bn": "সম্ভব হলে মাকামে ইবরাহিমকে নিজের ও কাবার মাঝে রেখে দুই রাকাত নামাজ পড়ুন; ভিড় থাকলে মসজিদের যেকোনো স্থানে। প্রথম রাকাতে সূরা কাফিরুন, দ্বিতীয় রাকাতে সূরা ইখলাস পড়া সুন্নত। মাকরুহ সময় হলে পরে পড়বেন।", "en": "If possible pray two rakats with Maqam Ibrahim between you and the Ka''bah; in crowds, anywhere in the masjid. Reciting Al-Kafirun in the first and Al-Ikhlas in the second is sunnah. If it is a disliked time, pray later."}}, {"type": "arabic", "label": {"bn": "মাকামে ইবরাহিমের দিকে যাওয়ার সময়", "en": "When going to Maqam Ibrahim"}, "ar": "وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى", "pron": {"bn": "ওয়াত্তাখিযূ মিম মাকামি ইবরাহীমা মুসাল্লা", "en": "Wattakhidhu mim maqami ibrahima musalla"}, "meaning": {"bn": "আর তোমরা মাকামে ইবরাহিমকে নামাজের স্থান বানাও।", "en": "And take the station of Ibrahim as a place of prayer."}, "ref": {"bn": "সূরা বাকারা ২:১২৫", "en": "Al-Baqarah 2:125"}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১২১৮", "en": "Sahih Muslim 1218"}}, {"type": "step", "title": {"bn": "জমজম", "en": "Zamzam"}, "text": {"bn": "এরপর জমজমের পানি তৃপ্তি সহকারে পান করুন এবং যা চান তার জন্য দোয়া করুন। নবী (সা.) জমজম দাঁড়িয়ে পান করেছেন; বসে পান করাও জায়েজ।", "en": "Then drink Zamzam to your fill and make dua for whatever you wish. The Prophet drank Zamzam standing; sitting is also fine."}}, {"type": "ref", "text": {"bn": "সুনান ইবনে মাজাহ (''জমজমের পানি যে উদ্দেশ্যে পান করা হয়, তার জন্যই'')", "en": "Sunan Ibn Majah (''The water of Zamzam is for whatever it is drunk for'')"}, "check": true}, {"type": "step", "title": {"bn": "আবার হাজরে আসওয়াদ (সুন্নত)", "en": "Back to the Black Stone (sunnah)"}, "text": {"bn": "সম্ভব হলে সাঈতে যাওয়ার আগে আবার হাজরে আসওয়াদ স্পর্শ বা ইশারা করুন; ভিড়ে এটি ছেড়ে দেওয়া যায়।", "en": "If possible, touch or point to the Black Stone again before going to sa''i; it may be left in crowds."}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'umrah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '7b08e5b9-0a68-5419-96cc-07fee7a8262d', id, 'umrah-sai-halq', '{"bn": "উমরাহ: সাঈ ও মাথা মুণ্ডন", "en": "Umrah: sa''i and shaving the head"}', '{"bn": "সাফা থেকে মারওয়া সাত চক্কর সাঈ, সাফার দোয়া, তারপর মাথা মুণ্ডন বা চুল ছোট করে উমরাহ শেষ।", "en": "Seven laps of sa''i from Safa to Marwah, the dua at Safa, then shaving or shortening to complete umrah."}', 'basic', '[{"type": "step", "title": {"bn": "সাফায় যাওয়া", "en": "Go to Safa"}, "text": {"bn": "সাফা পাহাড়ের কাছে এসে (শুধু প্রথমবার) নিচের আয়াতাংশ পড়ুন, তারপর বলুন ''আবদাউ বিমা বাদাআল্লাহু বিহি'' — আল্লাহ যা দিয়ে শুরু করেছেন, আমিও তা দিয়ে শুরু করছি।", "en": "Approaching Safa (the first time only), recite the verse below, then say ''Abda''u bima bada''allahu bih'' — I begin with what Allah began with."}}, {"type": "arabic", "label": {"bn": "সাফার কাছে (প্রথমবার)", "en": "Near Safa (first time)"}, "ar": "إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ ۖ أَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ", "pron": {"bn": "ইন্নাস সাফা ওয়াল মারওয়াতা মিন শাআইরিল্লাহ। আবদাউ বিমা বাদাআল্লাহু বিহি", "en": "Innas-safa wal-marwata min sha''a''irillah. Abda''u bima bada''allahu bih"}, "meaning": {"bn": "নিশ্চয়ই সাফা ও মারওয়া আল্লাহর নিদর্শনগুলোর অন্তর্ভুক্ত। আল্লাহ যা দিয়ে শুরু করেছেন, আমিও তা দিয়ে শুরু করছি।", "en": "Indeed Safa and Marwah are among the symbols of Allah. I begin with what Allah began with."}, "ref": {"bn": "সূরা বাকারা ২:১৫৮; সহিহ মুসলিম ১২১৮", "en": "Al-Baqarah 2:158; Sahih Muslim 1218"}}, {"type": "step", "title": {"bn": "সাফায় দোয়া", "en": "Dua at Safa"}, "text": {"bn": "সাফায় উঠে কাবার দিকে মুখ করুন, দুই হাত দোয়ার মতো তুলুন (নামাজের তাকবিরের মতো কান পর্যন্ত নয়), তিনবার ''আল্লাহু আকবার'' বলে নিচের জিকির পড়ুন, তারপর নিজের ভাষায় দোয়া করুন। এভাবে তিনবার জিকির ও দোয়া করা সুন্নত।", "en": "Climb Safa, face the Ka''bah, raise your hands as in dua (not to the ears as in prayer), say ''Allahu akbar'' three times and the dhikr below, then make your own dua. Doing the dhikr and dua three times is sunnah."}}, {"type": "arabic", "label": {"bn": "সাফা ও মারওয়ার জিকির", "en": "Dhikr at Safa and Marwah"}, "ar": "اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ. لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ، لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ، أَنْجَزَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَهُ", "pron": {"bn": "আল্লাহু আকবার, আল্লাহু আকবার, আল্লাহু আকবার। লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহু, লাহুল মুলকু ওয়া লাহুল হামদু, ওয়া হুয়া আলা কুল্লি শাইয়িন কাদীর। লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু, আনজাযা ওয়া''দাহু, ওয়া নাসারা আবদাহু, ওয়া হাযামাল আহযাবা ওয়াহদাহু", "en": "Allahu akbar, Allahu akbar, Allahu akbar. La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamd, wa huwa ''ala kulli shay''in qadir. La ilaha illallahu wahdah, anjaza wa''dah, wa nasara ''abdah, wa hazamal-ahzaba wahdah"}, "meaning": {"bn": "আল্লাহ সবচেয়ে মহান (তিনবার)। আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি এক, তাঁর কোনো শরিক নেই; রাজত্ব ও প্রশংসা তাঁরই, তিনি সবকিছুর ওপর ক্ষমতাবান। আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি এক; তিনি তাঁর ওয়াদা পূর্ণ করেছেন, তাঁর বান্দাকে সাহায্য করেছেন এবং একাই শত্রুদলগুলোকে পরাজিত করেছেন।", "en": "Allah is the Greatest (three times). There is no god but Allah alone, without partner; His is the dominion and the praise, and He has power over all things. There is no god but Allah alone; He fulfilled His promise, helped His servant and alone defeated the confederates."}, "ref": {"bn": "সহিহ মুসলিম ১২১৮", "en": "Sahih Muslim 1218"}}, {"type": "step", "title": {"bn": "মারওয়ার দিকে", "en": "Towards Marwah"}, "text": {"bn": "সাফা থেকে নেমে মারওয়ার দিকে হাঁটুন। দুই সবুজ বাতির মাঝখানে পুরুষরা মাঝারি গতিতে দৌড়াবেন; নারীরা স্বাভাবিকভাবে হাঁটবেন। পথে যেকোনো দোয়া-জিকির করুন।", "en": "Come down from Safa and walk towards Marwah. Between the two green lights men jog at a moderate pace; women walk normally. Make any dua and dhikr on the way."}}, {"type": "arabic", "label": {"bn": "সাঈর পথে (সাহাবিদের থেকে বর্ণিত)", "en": "During sa''i (reported from Companions)"}, "ar": "رَبِّ اغْفِرْ وَارْحَمْ، إِنَّكَ أَنْتَ الْأَعَزُّ الْأَكْرَمُ", "pron": {"bn": "রাব্বিগফির ওয়ারহাম, ইন্নাকা আনতাল আআযযুল আকরাম", "en": "Rabbighfir warham, innaka antal-a''azzul-akram"}, "meaning": {"bn": "হে আমার রব! ক্ষমা করো ও দয়া করো; নিশ্চয়ই তুমি সর্বাধিক পরাক্রমশালী, সর্বাধিক সম্মানিত।", "en": "My Lord, forgive and have mercy; You are the Most Mighty, the Most Generous."}, "ref": {"bn": "ইবনে মাসউদ ও ইবনে উমর রা. থেকে মাওকুফ বর্ণনা (মুসান্নাফ ইবনে আবি শাইবা)", "en": "Mawquf report from Ibn Mas''ud and Ibn Umar (Musannaf Ibn Abi Shaybah)"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "এটি নবী (সা.)-এর হাদিস নয়, সাহাবিদের আমল হিসেবে বর্ণিত; পড়া যায়, তবে জরুরি নয়।", "en": "This is reported as the practice of Companions, not a hadith of the Prophet; it may be said but is not required."}}, {"type": "step", "title": {"bn": "মারওয়ায়", "en": "At Marwah"}, "text": {"bn": "মারওয়ায় উঠে কাবার দিকে মুখ করে সাফার মতোই জিকির ও দোয়া করুন। সাফা থেকে মারওয়া এক চক্কর, মারওয়া থেকে সাফা আরেক চক্কর।", "en": "At Marwah face the Ka''bah and do the same dhikr and dua as at Safa. Safa to Marwah is one lap, Marwah to Safa another."}}, {"type": "step", "title": {"bn": "সাত চক্কর", "en": "Seven laps"}, "text": {"bn": "এভাবে সাত চক্কর পূর্ণ করুন; সপ্তম চক্কর মারওয়ায় শেষ হবে। ক্লান্ত হলে বিশ্রাম নেওয়া যায়; প্রয়োজনে হুইলচেয়ার ব্যবহার করা যায়।", "en": "Complete seven laps this way; the seventh ends at Marwah. You may rest if tired, and use a wheelchair if needed."}}, {"type": "note", "tone": "tip", "text": {"bn": "সাঈর জন্য ওজু শর্ত নয়, তবে ওজু থাকা উত্তম। তাওয়াফের পর হায়েজ শুরু হলে নারী সাঈ করতে পারবেন, কারণ সাঈর স্থান মসজিদের মূল অংশের বাইরে বলে গণ্য।", "en": "Wudu is not a condition for sa''i, though better. If a woman''s period starts after tawaf she may still do sa''i, as the sa''i area is counted outside the masjid proper."}}, {"type": "step", "title": {"bn": "মাথা মুণ্ডন বা চুল ছোট করা", "en": "Shave or shorten the hair"}, "text": {"bn": "সাঈ শেষে পুরুষরা পুরো মাথা মুণ্ডন করবেন (উত্তম) বা পুরো মাথার চুল ছোট করবেন। নারীরা চুলের আগা থেকে আঙুলের এক কর পরিমাণ কাটবেন। হজের নিকটবর্তী সময়ে তামাত্তুর উমরাহ হলে পুরুষের জন্য চুল ছোট করে হজের মুণ্ডনের জন্য চুল রেখে দেওয়া ভালো।", "en": "After sa''i men shave the whole head (better) or shorten hair from the whole head. Women cut a fingertip''s length from the ends. For a tamattu'' umrah close to hajj, men may prefer to shorten, keeping hair to shave at hajj."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৭২৭; সহিহ মুসলিম ১৩০১", "en": "Sahih al-Bukhari 1727; Sahih Muslim 1301"}}, {"type": "note", "tone": "info", "text": {"bn": "নবী (সা.) মাথা মুণ্ডনকারীদের জন্য তিনবার এবং চুল ছোট করা ব্যক্তিদের জন্য একবার রহমতের দোয়া করেছেন। মুণ্ডন বা চুল ছোট করার মাধ্যমে উমরাহ পূর্ণ হয় এবং ইহরামের সব নিষেধ উঠে যায়।", "en": "The Prophet prayed for mercy for those who shave three times and for those who shorten once. With shaving or shortening the umrah is complete and all ihram restrictions end."}}, {"type": "arabic", "label": {"bn": "মসজিদ থেকে বের হওয়ার দোয়া (বাম পা দিয়ে)", "en": "Dua on leaving the masjid (left foot first)"}, "ar": "اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ", "pron": {"bn": "আল্লাহুম্মা ইন্নী আসআলুকা মিন ফাদলিক", "en": "Allahumma inni as''aluka min fadlik"}, "meaning": {"bn": "হে আল্লাহ! আমি তোমার অনুগ্রহ প্রার্থনা করি।", "en": "O Allah, I ask You of Your bounty."}, "ref": {"bn": "সহিহ মুসলিম ৭১৩", "en": "Sahih Muslim 713"}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'umrah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '3fa02e01-7a2c-5a70-982b-9965affd0782', id, 'umrah-checklist', '{"bn": "উমরাহর চেকলিস্ট", "en": "Umrah checklist"}', '{"bn": "যাত্রার আগে কী নেবেন, কী শিখবেন, আর উমরাহর ধাপগুলো মিলিয়ে নেওয়ার তালিকা।", "en": "What to pack and learn before travelling, and a list to tick off the steps of umrah."}', 'basic', '[{"type": "heading", "text": {"bn": "যাত্রার আগে", "en": "Before travelling"}}, {"type": "list", "items": [{"bn": "পাসপোর্ট, ভিসা, টিকিট, হোটেল ও এজেন্সির কাগজ, টিকার সনদ (প্রযোজ্য হলে); সবকিছুর কপি ও ফোনে ছবি", "en": "Passport, visa, tickets, hotel and agency papers, vaccination certificate (if required); copies and photos on your phone"}, {"bn": "নিয়ত খাঁটি করা, তওবা, ঋণ ও মানুষের হক মিটিয়ে নেওয়া, পরিবারের কাছ থেকে বিদায় ও ক্ষমা চাওয়া", "en": "Purify the intention, repent, settle debts and others'' rights, say farewell and seek forgiveness from family"}, {"bn": "উমরাহর নিয়ম, তালবিয়া ও প্রয়োজনীয় দোয়াগুলো আগে থেকে শিখে নেওয়া", "en": "Learn the rites, the talbiyah and key duas beforehand"}, {"bn": "হালাল অর্থে খরচের ব্যবস্থা", "en": "Make sure the money is lawful"}]}, {"type": "heading", "text": {"bn": "সঙ্গে নেবেন", "en": "What to pack"}}, {"type": "list", "items": [{"bn": "পুরুষ: দুই সেট ইহরামের চাদর, ইহরামের বেল্ট/টাকার থলে, পায়ের পাতার মাঝখান খোলা স্যান্ডেল", "en": "Men: two sets of ihram sheets, an ihram belt/money pouch, sandals that leave the middle of the foot exposed"}, {"bn": "নারী: ঢিলেঢালা শালীন পোশাক, হিজাব, আরামদায়ক জুতা ও মোজা", "en": "Women: loose modest clothes, hijab, comfortable shoes and socks"}, {"bn": "সুগন্ধিহীন সাবান, শ্যাম্পু, টুথপেস্ট ও লোশন", "en": "Unscented soap, shampoo, toothpaste and lotion"}, {"bn": "নিয়মিত ওষুধ ও প্রেসক্রিপশন, ব্যথানাশক, ফোস্কার প্লাস্টার", "en": "Regular medicines and prescriptions, painkillers, blister plasters"}, {"bn": "জুতা রাখার ছোট ব্যাগ, পানির বোতল, ছাতা, পাওয়ার ব্যাংক", "en": "Small shoe bag, water bottle, umbrella, power bank"}, {"bn": "ছোট দোয়ার বই বা এই অ্যাপ (অফলাইনে চলে এমনভাবে)", "en": "A small dua book or this app (available offline)"}]}, {"type": "heading", "text": {"bn": "উমরাহর ধাপ মিলিয়ে নিন", "en": "Tick off the steps"}}, {"type": "list", "items": [{"bn": "গোসল/ওজু, ইহরামের পোশাক, (সম্ভব হলে) দুই রাকাত", "en": "Ghusl/wudu, ihram clothing, (if possible) two rakats"}, {"bn": "মিকাতের আগে নিয়ত ও তালবিয়া", "en": "Intention and talbiyah before the miqat"}, {"bn": "ইহরামের নিষেধগুলো মেনে চলা", "en": "Observe the prohibitions of ihram"}, {"bn": "ডান পা দিয়ে মসজিদুল হারামে প্রবেশ ও দোয়া", "en": "Enter Al-Masjid al-Haram with the right foot and the dua"}, {"bn": "ওজুসহ সাত চক্কর তাওয়াফ, হাজরে আসওয়াদ থেকে শুরু ও শেষ (পুরুষ: ইজতিবা ও প্রথম তিন চক্করে রমল)", "en": "Seven rounds of tawaf in wudu, starting and ending at the Black Stone (men: idtiba'' and ramal in the first three)"}, {"bn": "রুকনে ইয়ামানি ও হাজরে আসওয়াদের মাঝে ''রাব্বানা আতিনা''", "en": "''Rabbana atina'' between the Yemeni corner and the Black Stone"}, {"bn": "কাঁধ ঢেকে মাকামে ইবরাহিমের পেছনে বা মসজিদের যেকোনো স্থানে দুই রাকাত", "en": "Cover the shoulder and pray two rakats behind Maqam Ibrahim or anywhere in the masjid"}, {"bn": "জমজম পান ও দোয়া", "en": "Drink Zamzam and make dua"}, {"bn": "সাফা থেকে শুরু করে মারওয়ায় শেষ, সাত চক্কর সাঈ", "en": "Seven laps of sa''i, starting at Safa and ending at Marwah"}, {"bn": "মাথা মুণ্ডন বা চুল ছোট করা — উমরাহ সম্পন্ন", "en": "Shave or shorten the hair — umrah complete"}]}, {"type": "note", "tone": "tip", "text": {"bn": "উমরাহর পরে মক্কায় যত দিন থাকবেন, মসজিদুল হারামে জামাতে নামাজ ও নফল তাওয়াফে সময় দিন। মক্কা ছাড়ার আগে বিদায়ী তাওয়াফ শুধু উমরাহকারীর জন্য হানাফিসহ অনেক আলেমের মতে ওয়াজিব নয় (শাফেয়ি মতে মক্কা ত্যাগকারী সবার জন্য ওয়াজিব); তবে করে নেওয়াই উত্তম।", "en": "While you remain in Makkah after umrah, spend time in congregational prayer and voluntary tawaf at Al-Masjid al-Haram. For someone who came only for umrah, a farewell tawaf is not obligatory for Hanafis and many others (Shafi''is make it obligatory for anyone leaving Makkah); doing it is best."}}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'umrah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'e31869d6-bfbb-5592-b83d-689419b9490a', id, 'qurbani-ruling', '{"bn": "কুরবানি: হুকুম ও কার ওপর", "en": "Qurbani: ruling and who must offer it"}', '{"bn": "কুরবানির গুরুত্ব, এটি ওয়াজিব না সুন্নত — মাজহাবগুলোর মত, এবং কার ওপর আবশ্যক।", "en": "The importance of qurbani, whether it is wajib or sunnah in the different schools, and on whom it is due."}', 'basic', '[{"type": "arabic", "ar": "فَصَلِّ لِرَبِّكَ وَانْحَرْ", "pron": {"bn": "ফাসাল্লি লিরাব্বিকা ওয়ানহার", "en": "Fasalli lirabbika wanhar"}, "meaning": {"bn": "অতএব তোমার রবের উদ্দেশে নামাজ পড়ো এবং কুরবানি করো।", "en": "So pray to your Lord and sacrifice."}, "ref": {"bn": "সূরা কাওসার ১০৮:২", "en": "Al-Kawthar 108:2"}}, {"type": "arabic", "ar": "لَنْ يَنَالَ اللَّهَ لُحُومُهَا وَلَا دِمَاؤُهَا وَلَٰكِنْ يَنَالُهُ التَّقْوَىٰ مِنْكُمْ", "pron": {"bn": "লাই ইয়ানালাল্লাহা লুহূমুহা ওয়ালা দিমাউহা ওয়ালাকিই ইয়ানালুহুত তাকওয়া মিনকুম", "en": "Lay yanalallaha luhumuha wa la dima''uha wa lakiy yanaluhut-taqwa minkum"}, "meaning": {"bn": "আল্লাহর কাছে এগুলোর গোশত বা রক্ত পৌঁছায় না, বরং তাঁর কাছে পৌঁছায় তোমাদের তাকওয়া।", "en": "Neither their meat nor their blood reaches Allah; what reaches Him is your piety."}, "ref": {"bn": "সূরা হজ ২২:৩৭", "en": "Al-Hajj 22:37"}}, {"type": "text", "text": {"bn": "কুরবানি হলো ঈদুল আজহার দিনগুলোতে আল্লাহর সন্তুষ্টির জন্য নির্দিষ্ট পশু জবাই করা। এটি ইবরাহিম (আ.)-এর সুন্নত এবং নবী (সা.) মদিনায় প্রতি বছর কুরবানি করেছেন। উদ্দেশ্য গোশত খাওয়া নয়, বরং আল্লাহর জন্য ত্যাগ ও তাকওয়া।", "en": "Qurbani is slaughtering specified animals on the days of Eid al-Adha for the pleasure of Allah. It is the sunnah of Ibrahim, and the Prophet offered it every year in Madinah. Its purpose is not the meat but sacrifice and piety for Allah."}}, {"type": "differ", "title": {"bn": "কুরবানি ওয়াজিব না সুন্নত", "en": "Is qurbani wajib or sunnah"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "কুরবানির দিনগুলোতে নিসাব পরিমাণ সম্পদের মালিক প্রত্যেক প্রাপ্তবয়স্ক, সুস্থ মস্তিষ্কের, মুকিম (মুসাফির নয়) মুসলিমের ওপর কুরবানি ওয়াজিব।", "en": "Qurbani is wajib on every adult, sane, resident (not travelling) Muslim who owns the nisab during the days of sacrifice."}, "evidence": {"bn": "হাদিস: ''যার সামর্থ্য আছে অথচ কুরবানি করে না, সে যেন আমাদের ঈদগাহের কাছে না আসে'' (ইবনে মাজাহ); এবং ''ফাসাল্লি লিরাব্বিকা ওয়ানহার'' আয়াতের নির্দেশ।", "en": "Hadith: ''Whoever can afford it and does not sacrifice, let him not come near our place of prayer'' (Ibn Majah); and the command in the verse ''so pray to your Lord and sacrifice''."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "সামর্থ্যবানের জন্য সুন্নতে মুয়াক্কাদা (জোরালো সুন্নত); সামর্থ্য থাকা সত্ত্বেও ছেড়ে দেওয়া মাকরুহ।", "en": "An emphasised sunnah for those able; leaving it while able is disliked."}, "evidence": {"bn": "উম্মে সালামা (রা.)-এর হাদিস: ''তোমাদের কেউ কুরবানি করতে চাইলে...'' — ''চাইলে'' শব্দ ইচ্ছাধীনতার ইঙ্গিত দেয় (মুসলিম); আবু বকর (রা.) ও উমর (রা.) কখনো কখনো কুরবানি করতেন না, যাতে মানুষ একে ওয়াজিব না ভাবে।", "en": "Umm Salamah''s hadith: ''If one of you wants to sacrifice...'' — ''wants'' implies choice (Muslim); Abu Bakr and Umar sometimes did not sacrifice so people would not think it obligatory."}}]}, {"type": "ref", "text": {"bn": "সুনান ইবনে মাজাহ ৩১২৩; সহিহ মুসলিম ১৯৭৭", "en": "Sunan Ibn Majah 3123; Sahih Muslim 1977"}}, {"type": "heading", "text": {"bn": "হানাফি মতে কার ওপর ওয়াজিব", "en": "On whom it is wajib (Hanafi)"}}, {"type": "list", "items": [{"bn": "মুসলিম, প্রাপ্তবয়স্ক ও সুস্থ মস্তিষ্কের", "en": "Muslim, adult and sane"}, {"bn": "মুকিম; শরিয়তসম্মত মুসাফিরের ওপর ওয়াজিব নয়", "en": "Resident; not obligatory on a Shariah traveller"}, {"bn": "১০ জিলহজ সুবহে সাদিক থেকে ১২ জিলহজ সূর্যাস্তের মধ্যে যেকোনো সময় মৌলিক প্রয়োজন ও ঋণের অতিরিক্ত নিসাব পরিমাণ সম্পদের মালিক (সদকাতুল ফিতরের নিসাবের মতো; বছর পূর্ণ হওয়া শর্ত নয়)", "en": "Owning, at any time between dawn on 10 and sunset on 12 Dhul Hijjah, the nisab beyond basic needs and debts (as for sadaqatul fitr; a full year is not required)"}]}, {"type": "note", "tone": "info", "text": {"bn": "নিসাবের হিসাবে যাকাতের মতো শুধু নগদ-সোনা-রূপা নয়, মৌলিক প্রয়োজনের অতিরিক্ত যেকোনো সম্পদ (অব্যবহৃত জমি, অতিরিক্ত বাড়ি, অপ্রয়োজনীয় জিনিস) হানাফি মতে যোগ হয়।", "en": "For this nisab, Hanafis count not only cash, gold and silver but any wealth beyond basic needs (unused land, an extra house, surplus goods)."}}, {"type": "note", "tone": "tip", "text": {"bn": "পরিবারের প্রত্যেক সদস্য, যিনি নিজে নিসাবের মালিক (যেমন গয়নার মালিক স্ত্রী বা উপার্জনক্ষম সন্তান), হানাফি মতে তার ওপর আলাদা কুরবানি ওয়াজিব। মৃত ব্যক্তির পক্ষ থেকে নফল কুরবানি করা যায়।", "en": "In the Hanafi view every family member who personally owns the nisab (e.g. a wife who owns jewellery, or an earning child) has a separate qurbani due. A voluntary qurbani may be offered on behalf of the deceased."}}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'qurbani' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '543b2036-9619-5049-a935-05fdc49dd384', id, 'qurbani-animals', '{"bn": "কুরবানির পশু: বয়স, ভাগ ও দোষত্রুটি", "en": "Qurbani animals: age, shares and defects"}', '{"bn": "কোন পশু, কত বয়সে, কয়জন শরিক হতে পারে, আর কোন দোষ থাকলে কুরবানি হবে না।", "en": "Which animals, at what age, how many may share, and which defects disqualify an animal."}', 'basic', '[{"type": "text", "text": {"bn": "কুরবানির পশু হতে হবে গৃহপালিত চতুষ্পদ পশুর (আনআম) মধ্য থেকে: উট, গরু, মহিষ, ছাগল, ভেড়া ও দুম্বা। নর-মাদি দুটোই চলবে। হরিণ, মুরগি বা অন্য প্রাণী দিয়ে কুরবানি হয় না।", "en": "The animal must be from the livestock (an''am): camels, cattle, buffalo, goats, sheep and rams. Male or female are both fine. Deer, chickens or other animals do not count."}}, {"type": "table", "head": [{"bn": "পশু", "en": "Animal"}, {"bn": "ন্যূনতম বয়স (হানাফি)", "en": "Minimum age (Hanafi)"}, {"bn": "কতজন শরিক", "en": "Shares"}], "rows": [[{"bn": "ছাগল", "en": "Goat"}, {"bn": "পূর্ণ ১ বছর", "en": "Full 1 year"}, {"bn": "১ জন", "en": "1 person"}], [{"bn": "ভেড়া, দুম্বা", "en": "Sheep, ram"}, {"bn": "পূর্ণ ১ বছর; তবে ৬ মাস পার হয়ে এত হৃষ্টপুষ্ট যে এক বছরের মতো দেখায়, তাহলেও চলবে", "en": "Full 1 year; or over 6 months if so well-grown it looks a year old"}, {"bn": "১ জন", "en": "1 person"}], [{"bn": "গরু, মহিষ", "en": "Cow, buffalo"}, {"bn": "পূর্ণ ২ বছর", "en": "Full 2 years"}, {"bn": "সর্বোচ্চ ৭ জন", "en": "Up to 7 people"}], [{"bn": "উট", "en": "Camel"}, {"bn": "পূর্ণ ৫ বছর", "en": "Full 5 years"}, {"bn": "সর্বোচ্চ ৭ জন", "en": "Up to 7 people"}]]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১৯৬৩; সহিহ মুসলিম ১৩১৮", "en": "Sahih Muslim 1963; Sahih Muslim 1318"}}, {"type": "note", "tone": "info", "text": {"bn": "অন্য মাজহাবে বয়সে সামান্য পার্থক্য আছে (যেমন শাফেয়ি মতে ছাগলের বয়স পূর্ণ ২ বছর)। বয়স নিশ্চিত হতে দাঁত দেখা বা বিক্রেতার নির্ভরযোগ্য তথ্য নিন; বয়স কম হলে কুরবানি হবে না।", "en": "Other schools differ slightly on ages (e.g. Shafi''is require a goat of a full 2 years). Check the teeth or rely on trustworthy information from the seller; an underage animal does not count."}}, {"type": "heading", "text": {"bn": "গরু-উটে ভাগে কুরবানি", "en": "Sharing a cow or camel"}}, {"type": "list", "items": [{"bn": "গরু, মহিষ বা উটে সর্বোচ্চ সাতজন শরিক হতে পারেন; সাতের কম (২, ৩, ৫ জন) হলেও চলবে।", "en": "Up to seven may share a cow, buffalo or camel; fewer (2, 3, 5) is also fine."}, {"bn": "কারও ভাগ সাত ভাগের এক ভাগের কম হতে পারবে না।", "en": "No one''s share may be less than one seventh."}, {"bn": "প্রত্যেক শরিকের নিয়ত আল্লাহর সন্তুষ্টি (কুরবানি বা আকিকা) হতে হবে। হানাফি মতে কোনো একজন শুধু গোশত খাওয়ার নিয়তে শরিক হলে কারও কুরবানি সহিহ হবে না।", "en": "Every partner''s intention must be for Allah (qurbani or aqiqah). In the Hanafi view, if even one joins only for meat, no one''s qurbani is valid."}, {"bn": "সব শরিকের টাকা হালাল হওয়া জরুরি; গোশত ওজন করে সমান ভাগ করবেন, অনুমানে নয়।", "en": "All partners'' money must be lawful; divide the meat equally by weight, not by guess."}]}, {"type": "differ", "title": {"bn": "একটি ছাগল কি পুরো পরিবারের পক্ষ থেকে যথেষ্ট", "en": "Does one goat suffice for a whole household"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "একটি ছাগল বা ভেড়া কেবল একজনের ওয়াজিব কুরবানি আদায় করে। পরিবারের যার যার ওপর কুরবানি ওয়াজিব, প্রত্যেককে আলাদা কুরবানি দিতে হবে; তবে সওয়াবে অন্যদের শরিক করা যায়।", "en": "One goat or sheep discharges the wajib qurbani of one person only. Each family member on whom it is wajib must offer separately, though others may be included in the reward."}, "evidence": {"bn": "কুরবানি প্রত্যেক সামর্থ্যবানের ব্যক্তিগত দায়িত্ব; নবী (সা.) কর্তৃক পরিবারের পক্ষ থেকে কুরবানি সওয়াবে শরিক করার অর্থে।", "en": "Qurbani is a personal duty of each person able; the Prophet''s sacrifice for his family is understood as sharing the reward."}}, {"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "একজন ব্যক্তি নিজের ও পুরো পরিবারের পক্ষ থেকে একটি ছাগল কুরবানি করলে সবার পক্ষ থেকে সুন্নত আদায় হয়ে যায়।", "en": "A man sacrificing one goat for himself and his household fulfils the sunnah for all of them."}, "evidence": {"bn": "আবু আইয়ুব (রা.): নবী (সা.)-এর যুগে একজন নিজের ও পরিবারের পক্ষ থেকে একটি ছাগল কুরবানি করত (তিরমিজি); নবী (সা.) কুরবানির সময় বলেছেন, ''মুহাম্মদ ও মুহাম্মদের পরিবারের পক্ষ থেকে'' (মুসলিম)।", "en": "Abu Ayyub: in the Prophet''s time a man would sacrifice one sheep for himself and his household (Tirmidhi); the Prophet said at his sacrifice, ''from Muhammad and the family of Muhammad'' (Muslim)."}}]}, {"type": "ref", "text": {"bn": "জামে তিরমিজি ১৫০৫; সহিহ মুসলিম ১৯৬৭", "en": "Jami'' at-Tirmidhi 1505; Sahih Muslim 1967"}}, {"type": "heading", "text": {"bn": "যেসব দোষ থাকলে কুরবানি হবে না", "en": "Defects that disqualify"}}, {"type": "text", "text": {"bn": "নবী (সা.) চার ধরনের পশু কুরবানি করতে নিষেধ করেছেন: স্পষ্ট কানা, স্পষ্ট অসুস্থ, স্পষ্ট খোঁড়া এবং এত শুকনো যে হাড়ে মজ্জা নেই।", "en": "The Prophet forbade four kinds of animals: one clearly blind in one eye, one clearly sick, one clearly lame, and one so emaciated it has no marrow."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ২৮০২; জামে তিরমিজি ১৪৯৭", "en": "Sunan Abi Dawud 2802; Jami'' at-Tirmidhi 1497"}}, {"type": "list", "items": [{"bn": "এক বা দুই চোখ অন্ধ, বা এক চোখের বেশির ভাগ দৃষ্টি নেই", "en": "Blind in one or both eyes, or most of one eye''s sight gone"}, {"bn": "এমন খোঁড়া যে জবাইয়ের স্থান পর্যন্ত নিজে হেঁটে যেতে পারে না", "en": "So lame it cannot walk to the place of slaughter"}, {"bn": "এমন রোগা বা অসুস্থ যে চলাফেরা ও খাওয়া স্বাভাবিক নয়", "en": "So thin or sick that it cannot move or eat normally"}, {"bn": "হানাফি মতে: কান বা লেজের এক-তৃতীয়াংশের বেশি কাটা; শিং গোড়া থেকে ভেঙে মগজ পর্যন্ত ক্ষত; দাঁত না থাকায় ঘাস খেতে পারে না; জন্মগতভাবে কান নেই; ছাগলের একটি বা গরুর দুটি স্তনের বোঁটা কাটা বা শুকনো", "en": "Hanafi: more than a third of the ear or tail cut off; a horn broken at the root with injury reaching inside; toothless so it cannot graze; born without ears; one teat of a goat or two of a cow cut off or dry"}]}, {"type": "heading", "text": {"bn": "যেসব কারণে সমস্যা নেই", "en": "What does not disqualify"}}, {"type": "list", "items": [{"bn": "খাসি (বীজ কাটা) পশু; এটি বরং ভালো", "en": "A castrated animal; this is even preferred"}, {"bn": "জন্মগতভাবে শিং নেই, বা শিং সামান্য ভাঙা", "en": "Born without horns, or a slightly broken horn"}, {"bn": "কানে ছোট ছিদ্র বা সামান্য কাটা, এক-তৃতীয়াংশের কম", "en": "A small hole or cut in the ear, less than a third"}, {"bn": "জবাইয়ের জন্য শোয়ানোর সময় হঠাৎ আঘাত লেগে খুঁত হওয়া (হানাফি মত)", "en": "A defect that occurs suddenly while laying the animal down for slaughter (Hanafi view)"}]}, {"type": "note", "tone": "tip", "text": {"bn": "সবচেয়ে ভালো, হৃষ্টপুষ্ট ও সুন্দর পশু বাছাই করা উত্তম। নবী (সা.) দুটি সাদা-কালো রঙের শিংওয়ালা দুম্বা কুরবানি করেছেন।", "en": "Choosing the best, healthiest and finest animal is better. The Prophet sacrificed two horned rams, white with black markings."}}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'qurbani' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '9c73737b-7e1e-5ee7-90b6-06241c142dcc', id, 'qurbani-time-slaughter', '{"bn": "কুরবানির সময়, জবাইয়ের নিয়ম ও দোয়া", "en": "Time, method of slaughter and dua"}', '{"bn": "কখন থেকে কখন পর্যন্ত কুরবানি করা যায়, সুন্নত পদ্ধতিতে জবাই এবং জবাইয়ের দোয়া।", "en": "When qurbani may be offered, the sunnah method of slaughter and the dua."}', 'basic', '[{"type": "heading", "text": {"bn": "কুরবানির সময়", "en": "The time of qurbani"}}, {"type": "text", "text": {"bn": "ঈদুল আজহার নামাজের পর থেকে কুরবানির সময় শুরু। যেখানে ঈদের নামাজ হয়, সেখানে নামাজের আগে জবাই করলে তা কুরবানি হয় না, সাধারণ গোশত হয়; আবার কুরবানি দিতে হবে। (হানাফি মতে যে গ্রামে ঈদের নামাজ হয় না, সেখানে ১০ তারিখ সুবহে সাদিকের পরই জবাই করা যায়।) প্রথম দিন, অর্থাৎ ১০ জিলহজ কুরবানি করা উত্তম।", "en": "The time begins after the Eid al-Adha prayer. Where the Eid prayer is held, an animal slaughtered before it is ordinary meat, not qurbani, and must be replaced. (For Hanafis, in a village with no Eid prayer, slaughter is valid after dawn on the 10th.) The first day, the 10th, is best."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি; সহিহ মুসলিম (বারা ইবনে আযিব রা.: নামাজের আগে জবাই করা পশু সাধারণ গোশত)", "en": "Sahih al-Bukhari; Sahih Muslim (al-Bara'' ibn ''Azib: an animal slaughtered before the prayer is just meat)"}, "check": true}, {"type": "differ", "title": {"bn": "কুরবানির শেষ সময়", "en": "The last time for qurbani"}, "views": [{"label": {"bn": "হানাফি, মালেকি, হাম্বলি", "en": "Hanafi, Maliki, Hanbali"}, "text": {"bn": "১২ জিলহজ সূর্যাস্ত পর্যন্ত, অর্থাৎ ঈদের দিনসহ মোট তিন দিন।", "en": "Until sunset on 12 Dhul Hijjah: three days including Eid day."}, "evidence": {"bn": "উমর (রা.), আলী (রা.), ইবনে আব্বাস (রা.)সহ কয়েকজন সাহাবি থেকে বর্ণিত: কুরবানির দিন তিনটি।", "en": "Reported from Companions such as Umar, Ali and Ibn Abbas: the days of sacrifice are three."}}, {"label": {"bn": "শাফেয়ি", "en": "Shafi''i"}, "text": {"bn": "১৩ জিলহজ সূর্যাস্ত পর্যন্ত, অর্থাৎ আইয়ামে তাশরিকের শেষ দিন পর্যন্ত মোট চার দিন।", "en": "Until sunset on 13 Dhul Hijjah, the last day of Tashriq: four days."}, "evidence": {"bn": "হাদিস: ''আইয়ামে তাশরিকের সব দিনই জবাইয়ের দিন'' (মুসনাদে আহমাদ)।", "en": "Hadith: ''All the days of Tashriq are days of slaughter'' (Musnad Ahmad)."}}]}, {"type": "note", "tone": "info", "text": {"bn": "রাতে জবাই করা জায়েজ, তবে অন্ধকারে ভুল হওয়ার আশঙ্কায় হানাফি মতে মাকরুহ; দিনে করা উত্তম।", "en": "Slaughtering at night is permitted, but Hanafis dislike it for fear of mistakes in the dark; daytime is better."}}, {"type": "heading", "text": {"bn": "জবাইয়ের নিয়ম", "en": "The method of slaughter"}}, {"type": "step", "title": {"bn": "নিজে বা উপস্থিত থেকে", "en": "Yourself or present"}, "text": {"bn": "সম্ভব হলে নিজের কুরবানি নিজে জবাই করা উত্তম; না পারলে অন্যকে দিয়ে করানো এবং নিজে উপস্থিত থাকা ভালো। নারীরাও জবাই করতে পারেন।", "en": "It is best to slaughter your own animal if you can; otherwise have someone do it and be present. Women may also slaughter."}}, {"type": "step", "title": {"bn": "পশুর প্রতি দয়া", "en": "Kindness to the animal"}, "text": {"bn": "ছুরি খুব ধারালো করবেন, পশুর সামনে ধার দেবেন না, এক পশুর সামনে আরেকটি জবাই করবেন না, পানি খাওয়াবেন এবং টেনে-হিঁচড়ে কষ্ট দেবেন না।", "en": "Sharpen the knife well, not in front of the animal; do not slaughter one in sight of another; give it water and do not drag or hurt it."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১৯৫৫", "en": "Sahih Muslim 1955"}}, {"type": "step", "title": {"bn": "শোয়ানো", "en": "Laying it down"}, "text": {"bn": "পশুকে বাম কাতে কিবলামুখী করে শোয়ান; বড় পশুর জন্য কয়েকজন সাহায্যকারী রাখুন।", "en": "Lay the animal on its left side facing the qiblah; have helpers for large animals."}}, {"type": "step", "title": {"bn": "বিসমিল্লাহ বলে জবাই", "en": "Slaughter with Bismillah"}, "text": {"bn": "জবাইয়ের সময় ''বিসমিল্লাহি আল্লাহু আকবার'' বলে দ্রুত গলার সামনের দিকে ছুরি চালান। যিনি ছুরি চালাবেন এবং যিনি ছুরিতে হাত দিয়ে সাহায্য করবেন, দুজনকেই বিসমিল্লাহ বলতে হবে।", "en": "Say ''Bismillahi Allahu akbar'' and cut swiftly across the front of the throat. Whoever moves the knife, and anyone holding the knife with him, must both say Bismillah."}}, {"type": "step", "title": {"bn": "কী কাটতে হবে", "en": "What must be cut"}, "text": {"bn": "শ্বাসনালি, খাদ্যনালি এবং দুই পাশের দুটি বড় রক্তনালি (মোট চারটি)। হানাফি মতে এর যেকোনো তিনটি কাটা গেলে জবাই সহিহ। মাথা আলাদা করে ফেলা বা ঘাড়ের হাড় ভাঙা মাকরুহ।", "en": "The windpipe, the gullet and the two large blood vessels at the sides (four in all). For Hanafis cutting any three of these makes it valid. Cutting the head off or breaking the neck is disliked."}}, {"type": "step", "title": {"bn": "পুরো নিস্তেজ হওয়া পর্যন্ত অপেক্ষা", "en": "Wait until it is still"}, "text": {"bn": "পশু পুরোপুরি নিস্তেজ ও ঠান্ডা না হওয়া পর্যন্ত চামড়া ছাড়ানো বা কাটা শুরু করবেন না।", "en": "Do not begin skinning or cutting until the animal is completely still."}}, {"type": "note", "tone": "warn", "text": {"bn": "ইচ্ছা করে বিসমিল্লাহ ছেড়ে দিলে হানাফি ও অধিকাংশ আলেমের মতে সেই পশু খাওয়া হালাল নয় (সূরা আনআম ৬:১২১); ভুলে গেলে হালাল। শাফেয়ি মতে বিসমিল্লাহ সুন্নত।", "en": "If Bismillah is deliberately omitted, the meat is not lawful according to the Hanafis and most scholars (Al-An''am 6:121); if forgotten, it is lawful. For Shafi''is Bismillah is sunnah."}}, {"type": "heading", "text": {"bn": "জবাইয়ের দোয়া", "en": "Duas at slaughter"}}, {"type": "arabic", "label": {"bn": "জবাইয়ের সময় (জরুরি অংশ: বিসমিল্লাহ)", "en": "At the moment of slaughter (the essential part: Bismillah)"}, "ar": "بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ", "pron": {"bn": "বিসমিল্লাহি ওয়াল্লাহু আকবার", "en": "Bismillahi wallahu akbar"}, "meaning": {"bn": "আল্লাহর নামে, আর আল্লাহ সবচেয়ে মহান।", "en": "In the name of Allah, and Allah is the Greatest."}, "ref": {"bn": "সহিহ মুসলিম ১৯৬৬", "en": "Sahih Muslim 1966"}}, {"type": "arabic", "label": {"bn": "জবাইয়ের আগে পড়ার দোয়া (ঐচ্ছিক)", "en": "Dua before slaughter (optional)"}, "ar": "إِنِّي وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَاوَاتِ وَالْأَرْضَ عَلَىٰ مِلَّةِ إِبْرَاهِيمَ حَنِيفًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ، إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ، لَا شَرِيكَ لَهُ وَبِذَٰلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ، اللَّهُمَّ مِنْكَ وَلَكَ", "pron": {"bn": "ইন্নী ওয়াজ্জাহতু ওয়াজহিয়া লিল্লাযী ফাতারাস সামাওয়াতি ওয়াল আরদা আলা মিল্লাতি ইবরাহীমা হানীফাও ওয়ামা আনা মিনাল মুশরিকীন, ইন্না সালাতী ওয়া নুসুকী ওয়া মাহইয়ায়া ওয়া মামাতী লিল্লাহি রাব্বিল আলামীন, লা শারীকা লাহু ওয়া বিযালিকা উমিরতু ওয়া আনা মিনাল মুসলিমীন, আল্লাহুম্মা মিনকা ওয়া লাকা", "en": "Inni wajjahtu wajhiya lilladhi fataras-samawati wal-arda ''ala millati ibrahima hanifan wa ma ana minal-mushrikin, inna salati wa nusuki wa mahyaya wa mamati lillahi rabbil-''alamin, la sharika lahu wa bidhalika umirtu wa ana minal-muslimin, Allahumma minka wa lak"}, "meaning": {"bn": "আমি একনিষ্ঠভাবে ইবরাহিমের দ্বীনের ওপর থেকে সেই সত্তার দিকে মুখ ফেরালাম, যিনি আসমান ও জমিন সৃষ্টি করেছেন; আমি মুশরিকদের অন্তর্ভুক্ত নই। নিশ্চয়ই আমার নামাজ, আমার কুরবানি, আমার জীবন ও মরণ জগৎসমূহের রব আল্লাহর জন্য; তাঁর কোনো শরিক নেই। আমাকে এরই নির্দেশ দেওয়া হয়েছে, আর আমি মুসলিমদের একজন। হে আল্লাহ! এটি তোমারই দান এবং তোমারই জন্য।", "en": "I turn my face to the One who created the heavens and the earth, upon the way of Ibrahim, inclining to truth, and I am not of the polytheists. My prayer, my sacrifice, my living and my dying are for Allah, Lord of the worlds; He has no partner. This I am commanded, and I am of the Muslims. O Allah, it is from You and for You."}, "ref": {"bn": "সুনান আবু দাউদ ২৭৯৫", "en": "Sunan Abi Dawud 2795"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "এই দোয়াটি জাবির (রা.)-এর বর্ণনায় এসেছে; সনদ নিয়ে হাদিসবিশারদদের আলোচনা আছে। দোয়ার পরে ''বিসমিল্লাহি ওয়াল্লাহু আকবার'' বলে জবাই করবেন। মুখে নিয়ত বা অংশীদারদের নাম বলা জরুরি নয়; মনে নিয়ত থাকাই যথেষ্ট। চাইলে বলতে পারেন ''আল্লাহুম্মা তাকাব্বাল মিন্নী'' (হে আল্লাহ, আমার পক্ষ থেকে কবুল করো) — নবী (সা.) বলেছিলেন ''আল্লাহুম্মা তাকাব্বাল মিন মুহাম্মাদিন ওয়া আলি মুহাম্মাদ...''।", "en": "This dua comes in Jabir''s narration; hadith scholars discuss its chain. After it, slaughter saying ''Bismillahi wallahu akbar''. Saying the intention or the partners'' names aloud is not required; the intention in the heart is enough. You may say ''Allahumma taqabbal minni'' (O Allah, accept from me) — the Prophet said ''Allahumma taqabbal min Muhammadin wa ali Muhammad...''."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১৯৬৭", "en": "Sahih Muslim 1967"}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'qurbani' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'e0d1f63c-8175-5469-b640-e48481121adf', id, 'qurbani-meat-skin', '{"bn": "কুরবানির গোশত ও চামড়া", "en": "Qurbani meat and skin"}', '{"bn": "গোশত কীভাবে ভাগ করবেন, চামড়া ও কসাইয়ের মজুরির বিধান।", "en": "How to divide the meat, and the rulings on the skin and the butcher''s wage."}', 'basic', '[{"type": "arabic", "ar": "فَكُلُوا مِنْهَا وَأَطْعِمُوا الْقَانِعَ وَالْمُعْتَرَّ", "pron": {"bn": "ফাকুলূ মিনহা ওয়া আতইমুল কানিআ ওয়াল মু''তার", "en": "Fakulu minha wa at''imul-qani''a wal-mu''tarr"}, "meaning": {"bn": "তোমরা তা থেকে খাও এবং যে চায় না ও যে চায় — উভয় অভাবীকে খাওয়াও।", "en": "Eat from them and feed both the one who does not ask and the one who asks."}, "ref": {"bn": "সূরা হজ ২২:৩৬", "en": "Al-Hajj 22:36"}}, {"type": "heading", "text": {"bn": "গোশত বণ্টন", "en": "Dividing the meat"}}, {"type": "table", "head": [{"bn": "ভাগ", "en": "Share"}, {"bn": "কাদের জন্য", "en": "For whom"}], "rows": [[{"bn": "এক-তৃতীয়াংশ", "en": "One third"}, {"bn": "নিজের ও পরিবারের জন্য", "en": "Yourself and your family"}], [{"bn": "এক-তৃতীয়াংশ", "en": "One third"}, {"bn": "আত্মীয়স্বজন, প্রতিবেশী ও বন্ধুদের জন্য (ধনী হলেও দেওয়া যায়)", "en": "Relatives, neighbours and friends (even if well-off)"}], [{"bn": "এক-তৃতীয়াংশ", "en": "One third"}, {"bn": "গরিব-মিসকিনদের জন্য", "en": "The poor and needy"}]]}, {"type": "note", "tone": "info", "text": {"bn": "তিন ভাগ করা মুস্তাহাব (উত্তম), বাধ্যতামূলক নয়। পরিবার বড় হলে বেশি রাখা যায়, আবার পুরোটা দান করাও যায়। গোশত সংরক্ষণ করে পরে খাওয়াও জায়েজ।", "en": "Dividing into thirds is recommended, not compulsory. A large family may keep more, and one may also give it all away. Storing the meat to eat later is allowed."}}, {"type": "ref", "text": {"bn": "সূরা হজ ২২:২৮", "en": "Al-Hajj 22:28"}}, {"type": "list", "items": [{"bn": "কুরবানির গোশত, চর্বি, হাড় বা কোনো অংশ বিক্রি করা জায়েজ নয়।", "en": "Selling any part of the qurbani animal — meat, fat or bones — is not allowed."}, {"bn": "কসাইয়ের মজুরি কুরবানির গোশত বা চামড়া দিয়ে দেওয়া যাবে না; আলাদা টাকা দিতে হবে। মজুরি দেওয়ার পর উপহার হিসেবে গোশত দেওয়া যায়।", "en": "The butcher''s wage must not be paid with meat or skin; pay separately. Meat may be given to him as a gift beyond the wage."}, {"bn": "মানতের কুরবানি হলে পুরো গোশত গরিবদের দিতে হবে; মানতকারী ও তার পরিবার খেতে পারবে না।", "en": "If the qurbani was vowed (nazr), all the meat goes to the poor; the person and his family may not eat it."}, {"bn": "হানাফি মতে অমুসলিম প্রতিবেশীকেও উপহার হিসেবে কুরবানির গোশত দেওয়া যায়।", "en": "Hanafis allow giving qurbani meat as a gift to non-Muslim neighbours too."}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১৩১৭", "en": "Sahih Muslim 1317"}}, {"type": "heading", "text": {"bn": "চামড়া", "en": "The skin"}}, {"type": "text", "text": {"bn": "চামড়া নিজে ব্যবহার করা (যেমন জায়নামাজ বা মশক বানানো) বা কাউকে দান করা যায়। চামড়া বিক্রি করলে সেই টাকা নিজে ব্যবহার করা যাবে না; পুরো টাকা যাকাতের হকদার গরিবদের সদকা করে দিতে হবে। মাদরাসার লিল্লাহ বোর্ডিং বা গরিব ছাত্রদের দেওয়া প্রচলিত ও উত্তম খাত।", "en": "The skin may be used personally (e.g. as a prayer mat or water skin) or donated. If it is sold, the money may not be used by the owner; all of it must be given as charity to those eligible for zakat. Orphanage and poor-student funds of madrasahs are a common good choice."}}, {"type": "note", "tone": "warn", "text": {"bn": "চামড়ার টাকা দিয়ে মসজিদ নির্মাণ, ইমামের বেতন বা কর্মচারীর পারিশ্রমিক দেওয়া হানাফি মতে ঠিক নয়; এটি গরিবের হক।", "en": "Using the skin money for building a masjid, the imam''s salary or workers'' wages is not correct in the Hanafi view; it is the right of the poor."}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'qurbani' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '92bbbe80-6de2-5a02-b109-7a0575cf49a7', id, 'qurbani-dhul-hijjah-takbir', '{"bn": "জিলহজের দশ দিন ও তাকবিরে তাশরিক", "en": "The ten days of Dhul Hijjah and takbir at-tashriq"}', '{"bn": "জিলহজের প্রথম দশ দিনের ফজিলত, নখ-চুল না কাটার সুন্নত, আরাফার রোজা এবং তাকবিরে তাশরিক।", "en": "The virtue of the first ten days of Dhul Hijjah, the sunnah of not cutting nails and hair, the Arafah fast and takbir at-tashriq."}', 'basic', '[{"type": "arabic", "ar": "وَالْفَجْرِ ۝ وَلَيَالٍ عَشْرٍ", "pron": {"bn": "ওয়াল ফাজর, ওয়া লায়ালিন আশর", "en": "Wal-fajr, wa layalin ''ashr"}, "meaning": {"bn": "শপথ ভোরের, শপথ দশ রাতের।", "en": "By the dawn, and by the ten nights."}, "ref": {"bn": "সূরা ফজর ৮৯:১–২", "en": "Al-Fajr 89:1–2"}}, {"type": "text", "text": {"bn": "অধিকাংশ মুফাসসিরের মতে এই দশ রাত জিলহজের প্রথম দশ রাত। নবী (সা.) বলেছেন, এমন কোনো দিন নেই যেদিনের নেক আমল আল্লাহর কাছে এই দশ দিনের আমলের চেয়ে বেশি প্রিয়।", "en": "Most commentators say these ten nights are the first ten of Dhul Hijjah. The Prophet said there are no days in which good deeds are more beloved to Allah than these ten days."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৯৬৯", "en": "Sahih al-Bukhari 969"}}, {"type": "list", "items": [{"bn": "বেশি বেশি তাকবির (আল্লাহু আকবার), তাহলিল (লা ইলাহা ইল্লাল্লাহ) ও তাহমিদ (আলহামদুলিল্লাহ) পড়া", "en": "Say takbir, tahlil and tahmid abundantly"}, {"bn": "নফল রোজা, বিশেষ করে ৯ জিলহজ আরাফার রোজা (হাজি ছাড়া অন্যদের জন্য); এটি আগের ও পরের এক বছরের গুনাহের কাফফারা হওয়ার আশা করা যায়", "en": "Voluntary fasting, especially the Arafah fast on the 9th (for non-pilgrims); it is hoped to expiate the year before and after"}, {"bn": "দান-সদকা, কুরআন তিলাওয়াত, তওবা ও সব ধরনের নেক কাজ", "en": "Charity, Quran, repentance and all good deeds"}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১১৬২", "en": "Sahih Muslim 1162"}}, {"type": "heading", "text": {"bn": "নখ ও চুল না কাটা", "en": "Not cutting nails and hair"}}, {"type": "text", "text": {"bn": "উম্মে সালামা (রা.) বর্ণনা করেন, নবী (সা.) বলেছেন: জিলহজের দশক শুরু হলে তোমাদের যে কুরবানি করতে চায়, সে যেন তার চুল ও নখ থেকে কিছু না কাটে (কুরবানি করা পর্যন্ত)।", "en": "Umm Salamah reported that the Prophet said: when the ten days of Dhul Hijjah begin, whoever of you intends to sacrifice should not cut anything of his hair or nails (until he has sacrificed)."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১৯৭৭", "en": "Sahih Muslim 1977"}}, {"type": "differ", "title": {"bn": "এই নিষেধের হুকুম", "en": "Ruling of this prohibition"}, "views": [{"label": {"bn": "হাম্বলি", "en": "Hanbali"}, "text": {"bn": "কুরবানিদাতার জন্য চুল-নখ কাটা হারাম; কেটে ফেললে তওবা করবে, তবে কোনো কাফফারা নেই।", "en": "Cutting hair or nails is forbidden for the one sacrificing; if done, he repents, with no expiation."}, "evidence": {"bn": "হাদিসে সরাসরি নিষেধাজ্ঞা এসেছে, আর নিষেধের মূল অর্থ হারাম।", "en": "The hadith gives a direct prohibition, whose basic meaning is forbiddance."}}, {"label": {"bn": "শাফেয়ি ও মালেকি", "en": "Shafi''i and Maliki"}, "text": {"bn": "মাকরুহ তানযিহি (না কাটা সুন্নত, কাটলে গুনাহ নেই)।", "en": "Mildly disliked (not cutting is sunnah; cutting is not a sin)."}, "evidence": {"bn": "আয়েশা (রা.)-এর হাদিস: নবী (সা.) মদিনা থেকে কুরবানির পশু পাঠাতেন, কিন্তু ইহরামকারীর জন্য নিষিদ্ধ কোনো কিছু নিজের ওপর হারাম করতেন না।", "en": "Aishah''s hadith: the Prophet sent sacrificial animals from Madinah, yet did not make anything forbidden for himself that is forbidden to a pilgrim in ihram."}}, {"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "মুস্তাহাব; না কাটা উত্তম, কাটলে গুনাহ নেই। অনেক আলেম কুরবানি না দেওয়া ব্যক্তির জন্যও এতে শামিল হওয়া ভালো বলেছেন।", "en": "Recommended; not cutting is better and cutting is no sin. Many scholars say it is good for those not sacrificing to join in too."}, "evidence": {"bn": "দুটি হাদিসের সমন্বয়: নিষেধকে উত্তমতার অর্থে নেওয়া।", "en": "Reconciling the two hadiths by taking the prohibition as a recommendation."}}]}, {"type": "note", "tone": "info", "text": {"bn": "নিষেধটি কুরবানিদাতার নিজের জন্য, তার পরিবারের সবার জন্য নয়। ইহরামের মতো সুগন্ধি বা অন্য কিছু নিষেধ নয়।", "en": "The prohibition is for the person sacrificing, not his whole family. Nothing else, like perfume as in ihram, is forbidden."}}, {"type": "heading", "text": {"bn": "তাকবিরে তাশরিক", "en": "Takbir at-tashriq"}}, {"type": "arabic", "label": {"bn": "তাকবিরে তাশরিক", "en": "Takbir at-tashriq"}, "ar": "اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، لَا إِلَٰهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، وَلِلَّهِ الْحَمْدُ", "pron": {"bn": "আল্লাহু আকবার আল্লাহু আকবার, লা ইলাহা ইল্লাল্লাহু, ওয়াল্লাহু আকবার আল্লাহু আকবার, ওয়া লিল্লাহিল হামদ", "en": "Allahu akbar Allahu akbar, la ilaha illallah, wallahu akbar Allahu akbar, wa lillahil-hamd"}, "meaning": {"bn": "আল্লাহ সবচেয়ে মহান, আল্লাহ সবচেয়ে মহান; আল্লাহ ছাড়া কোনো ইলাহ নেই; আল্লাহ সবচেয়ে মহান, আল্লাহ সবচেয়ে মহান, আর সব প্রশংসা আল্লাহর।", "en": "Allah is the Greatest, Allah is the Greatest; there is no god but Allah; Allah is the Greatest, Allah is the Greatest, and to Allah belongs all praise."}, "ref": {"bn": "ইবনে মাসউদ রা. থেকে বর্ণিত (মুসান্নাফ ইবনে আবি শাইবা)", "en": "Reported from Ibn Mas''ud (Musannaf Ibn Abi Shaybah)"}, "check": true}, {"type": "arabic", "ar": "وَاذْكُرُوا اللَّهَ فِي أَيَّامٍ مَعْدُودَاتٍ", "pron": {"bn": "ওয়াযকুরুল্লাহা ফী আইয়ামিম মা''দূদাত", "en": "Wadhkurullaha fi ayyamim ma''dudat"}, "meaning": {"bn": "আর নির্দিষ্ট দিনগুলোতে আল্লাহকে স্মরণ করো।", "en": "And remember Allah during the appointed days."}, "ref": {"bn": "সূরা বাকারা ২:২০৩", "en": "Al-Baqarah 2:203"}}, {"type": "differ", "title": {"bn": "তাকবিরে তাশরিকের হুকুম ও দিন", "en": "Ruling and days of takbir at-tashriq"}, "views": [{"label": {"bn": "হানাফি (ফতোয়া: ইমাম আবু ইউসুফ ও মুহাম্মদের মত)", "en": "Hanafi (fatwa: the view of Abu Yusuf and Muhammad)"}, "text": {"bn": "৯ জিলহজ ফজর থেকে ১৩ জিলহজ আসর পর্যন্ত মোট ২৩ ওয়াক্ত ফরজ নামাজের পর একবার করে পড়া ওয়াজিব; পুরুষ উচ্চস্বরে, নারী নিচু স্বরে। একা বা জামাতে, মুকিম বা মুসাফির সবার জন্য। শুরুতে দুবার ''আল্লাহু আকবার''।", "en": "Wajib once after each of the 23 obligatory prayers from Fajr on the 9th to Asr on the 13th; men aloud, women quietly; alone or in congregation, resident or traveller. Two takbirs at the start."}, "evidence": {"bn": "আলী (রা.) আরাফার দিন ফজর থেকে আইয়ামে তাশরিকের শেষ দিনের আসর পর্যন্ত তাকবির বলতেন; শব্দ ইবনে মাসউদ (রা.) থেকে। (ইমাম আবু হানিফার মূল মত ছিল ইবনে মাসউদ রা.-এর অনুসরণে ১০ তারিখের আসর পর্যন্ত।)", "en": "Ali said the takbir from Fajr on the day of Arafah to Asr on the last day of Tashriq; the wording is from Ibn Mas''ud. (Abu Hanifa''s own view, following Ibn Mas''ud, was until Asr on the 10th.)"}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "সুন্নত। হাজি নন এমন ব্যক্তির জন্য ৯ জিলহজ ফজর থেকে ১৩ জিলহজ আসর পর্যন্ত ফরজ নামাজের পর (মুকাইয়াদ); এ ছাড়া জিলহজের প্রথম থেকে সব সময় যেকোনো স্থানে তাকবির বলা (মুতলাক)। শাফেয়ি মতে শুরুতে তিনবার ''আল্লাহু আকবার''।", "en": "Sunnah. For non-pilgrims, after obligatory prayers from Fajr on the 9th to Asr on the 13th (restricted takbir), plus takbir at any time and place from the start of Dhul Hijjah (unrestricted). Shafi''is begin with three takbirs."}, "evidence": {"bn": "আলী (রা.) ও অন্যান্য সাহাবির আমল; ইবনে উমর (রা.) ও আবু হুরাইরা (রা.) এই দশ দিনে বাজারে তাকবির বলতেন (সহিহ বুখারিতে তালিক হিসেবে)।", "en": "Practice of Ali and other Companions; Ibn Umar and Abu Hurayrah said the takbir in the markets in these ten days (reported without chain in Sahih al-Bukhari)."}}, {"label": {"bn": "মালেকি", "en": "Maliki"}, "text": {"bn": "সুন্নত; ১০ জিলহজ জোহর থেকে ১৩ জিলহজ ফজর পর্যন্ত ১৫ ওয়াক্ত ফরজ নামাজের পর।", "en": "Sunnah; after 15 obligatory prayers from Zuhr on the 10th to Fajr on the 13th."}, "evidence": {"bn": "হাজিদের তালবিয়া শেষ হয়ে তাকবির শুরু হয় ১০ তারিখে; অন্যরা তাদের অনুসরণ করবে।", "en": "The pilgrims'' talbiyah ends and their takbir begins on the 10th; others follow them."}}]}, {"type": "note", "tone": "tip", "text": {"bn": "ঈদুল আজহার নামাজে যাওয়ার পথে উচ্চস্বরে তাকবির বলা সুন্নত।", "en": "Saying the takbir aloud on the way to the Eid al-Adha prayer is sunnah."}}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'qurbani' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '9f16b3e2-cd66-5676-8ea7-a15441515ef3', id, 'qurbani-aqiqah', '{"bn": "আকিকা: নিয়ম, পশু, নাম রাখা ও মাথা মুণ্ডন", "en": "Aqiqah: method, animals, naming and shaving the head"}', '{"bn": "সন্তান জন্মের পর আকিকা কখন ও কীভাবে করবেন, ছেলে ও মেয়ের জন্য কয়টি পশু, নাম রাখা, মাথা মুণ্ডন ও অন্যান্য সুন্নত।", "en": "When and how to do aqiqah after a birth, how many animals for a boy and a girl, naming, shaving the head and related sunnahs."}', 'basic', '[{"type": "text", "text": {"bn": "আকিকা মানে সন্তান জন্মের শুকরিয়া হিসেবে আল্লাহর জন্য পশু জবাই করা। নবী (সা.) বলেছেন: প্রত্যেক শিশু তার আকিকার সঙ্গে বন্ধক থাকে; সপ্তম দিনে তার পক্ষ থেকে পশু জবাই করা হবে, তার মাথা মুণ্ডন করা হবে এবং নাম রাখা হবে।", "en": "Aqiqah is slaughtering an animal for Allah in gratitude for a child''s birth. The Prophet said: every child is held in pledge by his aqiqah; an animal is slaughtered for him on the seventh day, his head is shaved and he is named."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ২৮৩৮; জামে তিরমিজি ১৫২২", "en": "Sunan Abi Dawud 2838; Jami'' at-Tirmidhi 1522"}}, {"type": "differ", "title": {"bn": "আকিকার হুকুম", "en": "Ruling on aqiqah"}, "views": [{"label": {"bn": "শাফেয়ি, মালেকি, হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "সুন্নতে মুয়াক্কাদা; সাধারণত বাবা বা যার ওপর সন্তানের ভরণপোষণের দায়িত্ব, তিনি করবেন।", "en": "An emphasised sunnah, usually done by the father or whoever supports the child."}, "evidence": {"bn": "ওপরের হাদিস এবং নবী (সা.) কর্তৃক হাসান ও হুসাইন (রা.)-এর আকিকা।", "en": "The hadith above and the Prophet''s aqiqah for Al-Hasan and Al-Husayn."}}, {"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "মুস্তাহাব (শুকরিয়া হিসেবে উত্তম আমল); না করলে গুনাহ নেই।", "en": "Recommended (a good act of gratitude); no sin if not done."}, "evidence": {"bn": "কিছু বর্ণনায় নবী (সা.) বলেছেন, ''যে সন্তানের পক্ষ থেকে কুরবানি (আকিকা) করতে চায়, সে করুক'' — এতে ইচ্ছাধীনতা বোঝায় (আবু দাউদ, নাসায়ি)।", "en": "In some reports the Prophet said, ''Whoever wishes to sacrifice for his child, let him do so'' — indicating choice (Abu Dawud, an-Nasa''i)."}}], "check": true}, {"type": "heading", "text": {"bn": "কখন", "en": "When"}}, {"type": "list", "items": [{"bn": "জন্মের সপ্তম দিনে আকিকা করা সুন্নত (জন্মের দিনসহ গণনা; যেমন শুক্রবার জন্ম হলে পরের বৃহস্পতিবার)।", "en": "The sunnah is the seventh day (counting the day of birth; e.g. born on Friday, aqiqah on the next Thursday)."}, {"bn": "সপ্তম দিনে না পারলে কিছু আলেম ১৪ বা ২১ তম দিনের কথা বলেন (এ সম্পর্কিত বর্ণনা দুর্বল); না পারলে পরে যেকোনো সময় করা যায়।", "en": "If not possible on the seventh day, some scholars suggest the 14th or 21st (the report on this is weak); otherwise any time later."}, {"bn": "সন্তান সপ্তম দিনের আগে মারা গেলেও অনেক আলেমের মতে আকিকা করা যায়।", "en": "Many scholars allow aqiqah even if the child died before the seventh day."}]}, {"type": "heading", "text": {"bn": "কয়টি পশু", "en": "How many animals"}}, {"type": "table", "head": [{"bn": "সন্তান", "en": "Child"}, {"bn": "সুন্নত পরিমাণ", "en": "Sunnah amount"}, {"bn": "ন্যূনতম", "en": "Minimum"}], "rows": [[{"bn": "ছেলে", "en": "Boy"}, {"bn": "সমান মানের দুটি ছাগল/ভেড়া", "en": "Two comparable goats/sheep"}, {"bn": "একটি ছাগল/ভেড়াও যথেষ্ট", "en": "One goat/sheep also suffices"}], [{"bn": "মেয়ে", "en": "Girl"}, {"bn": "একটি ছাগল/ভেড়া", "en": "One goat/sheep"}, {"bn": "একটি", "en": "One"}]]}, {"type": "ref", "text": {"bn": "জামে তিরমিজি ১৫১৩", "en": "Jami'' at-Tirmidhi 1513"}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ (হাসান ও হুসাইন রা.-এর পক্ষ থেকে একটি করে দুম্বা)", "en": "Sunan Abi Dawud (one ram each for Al-Hasan and Al-Husayn)"}, "check": true}, {"type": "differ", "title": {"bn": "গরু বা উটের ভাগে আকিকা", "en": "Aqiqah as a share of a cow or camel"}, "views": [{"label": {"bn": "হানাফি ও শাফেয়ি", "en": "Hanafi and Shafi''i"}, "text": {"bn": "গরু বা উটের সাত ভাগের এক ভাগ দিয়ে আকিকা করা যায় (ছেলের জন্য দুই ভাগ); কুরবানির পশুতে আকিকার ভাগ রাখাও জায়েজ।", "en": "Aqiqah may be done with one seventh of a cow or camel (two sevenths for a boy); an aqiqah share in a qurbani animal is also allowed."}, "evidence": {"bn": "কুরবানির ওপর কিয়াস, যেখানে গরু-উট সাতজনের পক্ষ থেকে যথেষ্ট।", "en": "Analogy with qurbani, where a cow or camel suffices for seven."}}, {"label": {"bn": "মালেকি ও হাম্বলি", "en": "Maliki and Hanbali"}, "text": {"bn": "ভাগে আকিকা হয় না; পুরো একটি পশু লাগবে (গরু বা উট পুরোটা দিলে চলবে)।", "en": "Shares do not count for aqiqah; a whole animal is needed (a whole cow or camel is fine)."}, "evidence": {"bn": "আকিকা একটি জীবনের বিনিময়ে একটি পূর্ণ প্রাণ উৎসর্গ; হাদিসে ছাগল/ভেড়ার কথা এসেছে।", "en": "Aqiqah offers one whole life for a life; the hadith speaks of sheep and goats."}}]}, {"type": "note", "tone": "info", "text": {"bn": "আকিকার পশুর বয়স ও দোষত্রুটির শর্ত কুরবানির পশুর মতোই। জবাইয়ের নিয়মও একই।", "en": "The age and defect conditions for the aqiqah animal are the same as for qurbani, and so is the method of slaughter."}}, {"type": "arabic", "label": {"bn": "আকিকার জবাইয়ের সময় (ঐচ্ছিক)", "en": "At the aqiqah slaughter (optional)"}, "ar": "بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ، اللَّهُمَّ لَكَ وَإِلَيْكَ، هَٰذِهِ عَقِيقَةُ فُلَانٍ", "pron": {"bn": "বিসমিল্লাহি ওয়াল্লাহু আকবার, আল্লাহুম্মা লাকা ওয়া ইলাইকা, হাযিহি আকীকাতু (সন্তানের নাম)", "en": "Bismillahi wallahu akbar, Allahumma laka wa ilayk, hadhihi ''aqiqatu (child''s name)"}, "meaning": {"bn": "আল্লাহর নামে, আল্লাহ সবচেয়ে মহান। হে আল্লাহ! তোমারই জন্য এবং তোমারই কাছে। এটি অমুকের আকিকা।", "en": "In the name of Allah, Allah is the Greatest. O Allah, for You and to You. This is the aqiqah of (name)."}, "ref": {"bn": "আয়েশা রা. থেকে বর্ণিত (সুনানুল কুবরা, বায়হাকি)", "en": "Reported from Aishah (as-Sunan al-Kubra, al-Bayhaqi)"}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "জরুরি শুধু ''বিসমিল্লাহ'' বলা; বাকিটা ঐচ্ছিক। সন্তানের নাম মুখে বলা শর্ত নয়, মনে নিয়ত থাকাই যথেষ্ট।", "en": "Only ''Bismillah'' is essential; the rest is optional. Saying the child''s name aloud is not a condition; the intention in the heart is enough."}}, {"type": "heading", "text": {"bn": "গোশত", "en": "The meat"}}, {"type": "text", "text": {"bn": "আকিকার গোশত কুরবানির মতো তিন ভাগ করা যায়, রান্না করে আত্মীয়-প্রতিবেশী ও গরিবদের খাওয়ানো যায়, কাঁচাও বিতরণ করা যায়। মা-বাবা ও পরিবারের সবাই খেতে পারেন। চামড়ার বিধান কুরবানির মতো।", "en": "The aqiqah meat may be divided in thirds like qurbani, cooked to feed relatives, neighbours and the poor, or given raw. Parents and the whole family may eat from it. The skin follows the qurbani ruling."}}, {"type": "heading", "text": {"bn": "নাম রাখা", "en": "Naming"}}, {"type": "list", "items": [{"bn": "জন্মের দিন বা সপ্তম দিনে নাম রাখা যায়; দুটোই হাদিসে এসেছে।", "en": "The child may be named on the day of birth or the seventh day; both are in the hadith."}, {"bn": "আল্লাহর কাছে সবচেয়ে প্রিয় নাম আবদুল্লাহ ও আবদুর রহমান। নবী-রাসুল ও সাহাবিদের নাম এবং সুন্দর অর্থের নাম রাখুন।", "en": "The names most beloved to Allah are Abdullah and Abdur-Rahman. Choose names of prophets and Companions and names with good meanings."}, {"bn": "আল্লাহ ছাড়া অন্য কারও দাসত্ব বোঝায় এমন নাম (যেমন আবদুন নবী, গোলাম রসুল) বা খারাপ অর্থের নাম রাখা যাবে না; নবী (সা.) খারাপ অর্থের নাম বদলে দিতেন।", "en": "Do not use names implying servitude to other than Allah (e.g. Abdun-Nabi, Ghulam Rasul) or with bad meanings; the Prophet used to change such names."}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২১৩২", "en": "Sahih Muslim 2132"}}, {"type": "note", "tone": "tip", "text": {"bn": "এই অ্যাপের ''ইসলামিক নাম'' অংশ থেকে অর্থসহ নাম বাছাই করতে পারেন।", "en": "You can choose names with their meanings from this app''s Islamic Names section."}}, {"type": "heading", "text": {"bn": "মাথা মুণ্ডন ও অন্যান্য সুন্নত", "en": "Shaving the head and other sunnahs"}}, {"type": "step", "title": {"bn": "মাথা মুণ্ডন", "en": "Shave the head"}, "text": {"bn": "সপ্তম দিনে শিশুর (ছেলে-মেয়ে উভয়ের) মাথার চুল মুণ্ডন করা সুন্নত।", "en": "On the seventh day shaving the baby''s head (boy or girl) is sunnah."}}, {"type": "step", "title": {"bn": "চুলের ওজনে রূপা সদকা", "en": "Silver equal to the hair''s weight"}, "text": {"bn": "মুণ্ডিত চুলের ওজনের সমপরিমাণ রূপা (বা তার মূল্য) সদকা করা মুস্তাহাব; নবী (সা.) হাসান (রা.)-এর ক্ষেত্রে ফাতিমা (রা.)-কে এমন করতে বলেছিলেন।", "en": "Giving in charity silver equal to the weight of the shaved hair (or its value) is recommended; the Prophet told Fatimah to do this for Al-Hasan."}}, {"type": "ref", "text": {"bn": "জামে তিরমিজি (আলী রা.-এর বর্ণনা: হাসান রা.-এর চুলের ওজনে রূপা সদকা)", "en": "Jami'' at-Tirmidhi (Ali: silver equal to the weight of Al-Hasan''s hair)"}, "check": true}, {"type": "step", "title": {"bn": "তাহনিক", "en": "Tahnik"}, "text": {"bn": "কোনো নেককার ব্যক্তি খেজুর চিবিয়ে নরম করে শিশুর তালুতে সামান্য লাগিয়ে দেওয়া এবং বরকতের দোয়া করা সুন্নত; নবী (সা.) নবজাতকদের তাহনিক করতেন।", "en": "It is sunnah for a righteous person to chew a date until soft, rub a little on the baby''s palate and pray for blessing; the Prophet did tahnik for newborns."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি; সহিহ মুসলিম (আবু মুসা রা.-এর পুত্র ইবরাহিমের তাহনিক)", "en": "Sahih al-Bukhari; Sahih Muslim (tahnik of Abu Musa''s son Ibrahim)"}, "check": true}, {"type": "step", "title": {"bn": "কানে আজান", "en": "Adhan in the ear"}, "text": {"bn": "জন্মের পর শিশুর ডান কানে আজান দেওয়ার প্রচলন আছে। আবু রাফে (রা.) বর্ণনা করেন যে নবী (সা.) হাসান (রা.)-এর কানে আজান দিয়েছেন; তিরমিজি একে সহিহ বলেছেন, তবে অনেক হাদিসবিশারদ সনদকে দুর্বল বলেছেন। বাম কানে ইকামতের বর্ণনা আরও দুর্বল।", "en": "Giving the adhan in the newborn''s right ear is common practice. Abu Rafi'' reported that the Prophet gave the adhan in Al-Hasan''s ear; at-Tirmidhi graded it sound, but many hadith scholars consider the chain weak. The report of iqamah in the left ear is weaker still."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ; জামে তিরমিজি (আবু রাফে রা.-এর বর্ণনা)", "en": "Sunan Abi Dawud; Jami'' at-Tirmidhi (narration of Abu Rafi'')"}, "check": true}, {"type": "note", "tone": "warn", "text": {"bn": "শিশুর জন্মে কুসংস্কারমূলক রীতি (যেমন নির্দিষ্ট দিনে ঘর থেকে বের না হওয়া, তাবিজ ঝোলানো) থেকে বিরত থাকুন। মেয়ে সন্তানের জন্মে আনন্দ ও কৃতজ্ঞতা ছেলের মতোই।", "en": "Avoid superstitious customs around birth (such as not leaving the house on certain days, or hanging amulets). The birth of a daughter calls for the same joy and gratitude as a son."}}]', 'in_review', 60 FROM is_guide_topics WHERE slug = 'qurbani' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '5188e8f9-d532-5d8d-ac1f-a0c10b44deab', id, 'janazah-near-death', '{"bn": "মৃত্যুর সময় করণীয় ও তালকিন", "en": "Near Death: Care and Talqin"}', '{"bn": "মৃত্যুপথযাত্রী মানুষের পাশে কী করবেন: কালিমার তালকিন, দোয়া, আশা জাগানো এবং যা এড়িয়ে চলবেন।", "en": "What to do beside a dying person: gently prompting the kalimah, du''as, giving hope, and what to avoid."}', 'basic', '[{"type": "text", "text": {"bn": "মৃত্যু প্রত্যেকের জন্য নির্ধারিত। প্রিয়জনের শেষ সময়ে পাশে থাকা, তাকে আল্লাহর কথা মনে করিয়ে দেওয়া এবং শান্ত রাখা একটি বড় খেদমত।", "en": "Death comes to everyone. Being beside a loved one at the end, reminding them of Allah and keeping them calm is a great service."}}, {"type": "heading", "text": {"bn": "তালকিন: কালিমা মনে করিয়ে দেওয়া", "en": "Talqin: prompting the kalimah"}}, {"type": "arabic", "label": {"bn": "নবীজি (সা.)-এর নির্দেশ", "en": "The Prophet''s instruction"}, "ar": "لَقِّنُوا مَوْتَاكُمْ لَا إِلٰهَ إِلَّا اللّٰهُ", "pron": {"bn": "লাক্কিনূ মাওতাকুম লা ইলাহা ইল্লাল্লাহ।", "en": "Laqqinu mawtakum la ilaha illallah."}, "meaning": {"bn": "তোমাদের মৃত্যুপথযাত্রীদের ‘লা ইলাহা ইল্লাল্লাহ’-এর তালকিন দাও (মনে করিয়ে দাও)।", "en": "Prompt your dying ones with ''La ilaha illallah''."}, "ref": {"bn": "সহিহ মুসলিম ৯১৬", "en": "Sahih Muslim 916"}}, {"type": "text", "text": {"bn": "নবীজি (সা.) বলেছেন, যার শেষ কথা হবে ‘লা ইলাহা ইল্লাল্লাহ’, সে জান্নাতে প্রবেশ করবে (সুনান আবু দাউদ ৩১১৬)।", "en": "The Prophet said: whoever''s last words are ''La ilaha illallah'' will enter Paradise (Sunan Abi Dawud 3116)."}}, {"type": "list", "items": [{"bn": "রোগীর পাশে শান্ত স্বরে ‘লা ইলাহা ইল্লাল্লাহ’ বলুন, যাতে তিনি শুনে নিজেও বলেন। তাকে ‘বলুন, বলুন’ বলে চাপ দেবেন না।", "en": "Say ''La ilaha illallah'' softly near them so they hear and say it; do not pressure them with ''say it, say it''."}, {"bn": "একবার বলে ফেললে বারবার বলাবেন না; তবে এরপর অন্য কোনো কথা বললে আবার আস্তে করে মনে করিয়ে দিন।", "en": "Once they say it, do not keep repeating; if they speak of other things afterwards, gently remind them again."}, {"bn": "সম্ভব হলে তাকে কিবলামুখী করে শোয়ান, হানাফি মতে ডান কাতে; কষ্ট হলে যেভাবে আরাম পান সেভাবেই রাখুন।", "en": "If possible lay them facing the qiblah, on the right side in the Hanafi view; if uncomfortable, leave them as is."}, {"bn": "আল্লাহর রহমতের আশা জাগান। নবীজি (সা.) বলেছেন, তোমাদের কেউ যেন আল্লাহর প্রতি সুধারণা নিয়েই মৃত্যুবরণ করে (সহিহ মুসলিম ২৮৭৭)।", "en": "Give hope in Allah''s mercy. ''Let none of you die except thinking well of Allah'' (Sahih Muslim 2877)."}, {"bn": "শুধু ভালো কথা বলুন; নবীজি (সা.) বলেছেন, এ সময় ফেরেশতারা তোমাদের কথায় আমিন বলেন (সহিহ মুসলিম ৯২০)।", "en": "Speak only good; the Prophet said the angels say amin to what you say (Sahih Muslim 920)."}, {"bn": "ঋণ, আমানত, ওসিয়ত বা কারও হক থাকলে সময় থাকতে জেনে নিন ও লিখে রাখুন।", "en": "If there are debts, trusts, a will or others'' rights, find out and write them down while there is time."}]}, {"type": "heading", "text": {"bn": "মৃত্যুপথযাত্রীর নিজের দোয়া", "en": "The dying person''s own du''a"}}, {"type": "arabic", "label": {"bn": "নবীজি (সা.)-এর শেষ সময়ের দোয়া", "en": "The Prophet''s du''a in his final moments"}, "ar": "اللّٰهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى", "pron": {"bn": "আল্লাহুম্মাগফির লী ওয়ারহামনী ওয়া আলহিকনী বিররাফীকিল আ''লা।", "en": "Allahummaghfir li warhamni wa alhiqni bir-rafiqil-a''la."}, "meaning": {"bn": "হে আল্লাহ, আমাকে ক্ষমা করো, আমার প্রতি দয়া করো এবং আমাকে সর্বোচ্চ সঙ্গীর সাথে মিলিত করো।", "en": "O Allah, forgive me, have mercy on me, and join me with the highest companion."}, "ref": {"bn": "সহিহ বুখারি ৫৬৭৪", "en": "Sahih al-Bukhari 5674"}}, {"type": "arabic", "label": {"bn": "কষ্টে মৃত্যু কামনা না করে এই দোয়া", "en": "Instead of wishing for death in hardship"}, "ar": "اللّٰهُمَّ أَحْيِنِي مَا كَانَتِ الْحَيَاةُ خَيْرًا لِي، وَتَوَفَّنِي إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِي", "pron": {"bn": "আল্লাহুম্মা আহয়িনী মা কানাতিল হায়াতু খাইরাল লী, ওয়া তাওয়াফফানী ইযা কানাতিল ওয়াফাতু খাইরাল লী।", "en": "Allahumma ahyini ma kanatil-hayatu khayran li, wa tawaffani idha kanatil-wafatu khayran li."}, "meaning": {"bn": "হে আল্লাহ, যতদিন বেঁচে থাকা আমার জন্য কল্যাণকর, ততদিন আমাকে বাঁচিয়ে রাখো; আর যখন মৃত্যু আমার জন্য কল্যাণকর, তখন আমাকে মৃত্যু দাও।", "en": "O Allah, keep me alive as long as life is better for me, and take me when death is better for me."}, "ref": {"bn": "সহিহ বুখারি ৫৬৭১", "en": "Sahih al-Bukhari 5671"}}, {"type": "note", "tone": "warn", "text": {"bn": "রোগ বা কষ্টের কারণে মৃত্যু কামনা করা নিষেধ (সহিহ বুখারি ৫৬৭১); প্রয়োজনে উপরের দোয়াটি পড়ুন।", "en": "Wishing for death because of illness or hardship is forbidden (Sahih al-Bukhari 5671); say the du''a above instead."}}, {"type": "note", "tone": "info", "text": {"bn": "মৃত্যুপথযাত্রীর কাছে সূরা ইয়াসিন পড়ার হাদিস (সুনান আবু দাউদ ৩১২১) সনদের দিক থেকে দুর্বল বলে অনেক মুহাদ্দিস উল্লেখ করেছেন। তবু অনেক আলেম কুরআন পড়াকে ভালো বলেছেন; পড়লে আস্তে পড়ুন, যাতে রোগীর কষ্ট না হয়।", "en": "The hadith on reciting Ya-Sin to the dying (Sunan Abi Dawud 3121) is graded weak by many scholars. Many still consider reciting Quran good; if you do, recite softly so as not to disturb the person."}}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'cf0821ad-8aeb-526f-be82-fee282d3df5a', id, 'janazah-after-death', '{"bn": "মৃত্যুর পর তাৎক্ষণিক করণীয়", "en": "Immediately After Death"}', '{"bn": "মৃত্যুর পর চোখ বন্ধ করা, দোয়া, শরীর ঢেকে রাখা, দ্রুত দাফনের প্রস্তুতি, ঋণ পরিশোধ ও শোক প্রকাশের সীমা।", "en": "Closing the eyes, du''as, covering the body, hastening the funeral, settling debts, and the limits of grief."}', 'basic', '[{"type": "arabic", "label": {"bn": "মৃত্যুর খবর শুনে", "en": "On hearing of a death"}, "ar": "إِنَّا لِلّٰهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللّٰهُمَّ أْجُرْنِي فِي مُصِيبَتِي وَأَخْلِفْ لِي خَيْرًا مِنْهَا", "pron": {"bn": "ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি রাজিউন, আল্লাহুম্মা''জুরনী ফী মুসীবাতী ওয়া আখলিফ লী খাইরাম মিনহা।", "en": "Inna lillahi wa inna ilayhi raji''un, Allahumma''jurni fi musibati wa akhlif li khayran minha."}, "meaning": {"bn": "আমরা আল্লাহরই এবং তাঁর কাছেই ফিরে যাব। হে আল্লাহ, আমার এই বিপদে আমাকে প্রতিদান দাও এবং এর চেয়ে উত্তম কিছু আমাকে দান করো।", "en": "We belong to Allah and to Him we return. O Allah, reward me in my affliction and give me something better in its place."}, "ref": {"bn": "সূরা বাকারা ২:১৫৬; সহিহ মুসলিম ৯১৮", "en": "Al-Baqarah 2:156; Sahih Muslim 918"}}, {"type": "step", "title": {"bn": "চোখ বন্ধ করা", "en": "Close the eyes"}, "text": {"bn": "আস্তে করে চোখ বন্ধ করে দিন। নবীজি (সা.) আবু সালামা (রা.)-এর চোখ বন্ধ করে বলেছিলেন, রুহ কবজ হলে দৃষ্টি তার পিছু নেয় (সহিহ মুসলিম ৯২০)।", "en": "Gently close the eyes. The Prophet closed Abu Salamah''s eyes and said the sight follows the soul when it is taken (Sahih Muslim 920)."}}, {"type": "step", "title": {"bn": "দোয়া করা", "en": "Make du''a"}, "text": {"bn": "মৃত ব্যক্তির জন্য দোয়া করুন; নিচের দোয়ায় ‘ফুলান’-এর জায়গায় তার নাম বলুন।", "en": "Make du''a for the deceased; say their name in place of ''fulan'' below."}}, {"type": "arabic", "label": {"bn": "চোখ বন্ধ করার পর", "en": "After closing the eyes"}, "ar": "اللّٰهُمَّ اغْفِرْ لِفُلَانٍ، وَارْفَعْ دَرَجَتَهُ فِي الْمَهْدِيِّينَ، وَاخْلُفْهُ فِي عَقِبِهِ فِي الْغَابِرِينَ، وَاغْفِرْ لَنَا وَلَهُ يَا رَبَّ الْعَالَمِينَ، وَافْسَحْ لَهُ فِي قَبْرِهِ، وَنَوِّرْ لَهُ فِيهِ", "pron": {"bn": "আল্লাহুম্মাগফির লি(ফুলান), ওয়ারফা'' দারাজাতাহূ ফিল মাহদিয়্যীন, ওয়াখলুফহু ফী আকিবিহী ফিল গাবিরীন, ওয়াগফির লানা ওয়া লাহূ ইয়া রাব্বাল আলামীন, ওয়াফসাহ লাহূ ফী কাবরিহী, ওয়া নাওয়ির লাহূ ফীহ।", "en": "Allahummaghfir li-(fulan), warfa'' darajatahu fil-mahdiyyin, wakhlufhu fi ''aqibihi fil-ghabirin, waghfir lana wa lahu ya Rabbal-''alamin, wafsah lahu fi qabrihi, wa nawwir lahu fih."}, "meaning": {"bn": "হে আল্লাহ, অমুককে ক্ষমা করো, হেদায়াতপ্রাপ্তদের মধ্যে তার মর্যাদা বাড়িয়ে দাও, তার রেখে যাওয়া পরিবারের তুমি অভিভাবক হও; হে জগতসমূহের রব, আমাদের ও তাকে ক্ষমা করো, তার কবর প্রশস্ত করো এবং তার জন্য কবর আলোকিত করো।", "en": "O Allah, forgive (name), raise his rank among the guided, be the guardian of those he left behind, forgive us and him, O Lord of the worlds, widen his grave and give him light in it."}, "ref": {"bn": "সহিহ মুসলিম ৯২০", "en": "Sahih Muslim 920"}}, {"type": "step", "title": {"bn": "শরীর ঠিক করে ঢেকে দেওয়া", "en": "Straighten and cover the body"}, "text": {"bn": "চোয়াল একটি কাপড় দিয়ে মাথার সাথে আলতো বেঁধে দিন, হাত-পা সোজা করে দিন, পরনের কাপড় খুলে একটি চাদর দিয়ে পুরো শরীর ঢেকে দিন। পেটের ওপর ভারী কিছু রাখার প্রয়োজন নেই।", "en": "Tie the jaw gently with a strip of cloth, straighten the limbs, remove the clothes and cover the whole body with a sheet."}}, {"type": "step", "title": {"bn": "দ্রুত গোসল, কাফন ও দাফন", "en": "Hasten washing, shrouding and burial"}, "text": {"bn": "দেরি না করে গোসল, কাফন, জানাযা ও দাফনের ব্যবস্থা করুন। নবীজি (সা.) বলেছেন, জানাযা দ্রুত নিয়ে যাও (সহিহ বুখারি ১৩১৫)। দূরের আত্মীয়দের জন্য অযথা দীর্ঘ অপেক্ষা করবেন না।", "en": "Arrange washing, shrouding, prayer and burial without delay. ''Hasten with the funeral'' (Sahih al-Bukhari 1315). Do not wait unduly for distant relatives."}}, {"type": "step", "title": {"bn": "মানুষকে জানানো", "en": "Inform people"}, "text": {"bn": "আত্মীয়, প্রতিবেশী ও মসজিদে মৃত্যুর খবর ও জানাযার সময় জানানো জায়েজ, যাতে বেশি মানুষ জানাযায় আসে; নবীজি (সা.) নাজাশির মৃত্যুর খবর জানিয়েছিলেন (সহিহ বুখারি ১২৪৫)।", "en": "It is permissible to announce the death and funeral time so more people attend; the Prophet announced the death of the Negus (Sahih al-Bukhari 1245)."}}, {"type": "step", "title": {"bn": "ঋণ পরিশোধ ও ওসিয়ত", "en": "Pay debts and carry out the will"}, "text": {"bn": "মৃতের সম্পদ থেকে ক্রমানুসারে: কাফন-দাফনের খরচ, তারপর ঋণ পরিশোধ, তারপর ওসিয়ত (অনাত্মীয়দের জন্য সম্পদের সর্বোচ্চ এক-তৃতীয়াংশ), তারপর বাকিটা উত্তরাধিকারীদের মধ্যে ফারায়েজ অনুযায়ী বণ্টন। নবীজি (সা.) বলেছেন, মুমিনের রুহ তার ঋণের সাথে ঝুলে থাকে, যতক্ষণ না তা পরিশোধ করা হয় (জামে তিরমিজি ১০৭৮)।", "en": "From the estate, in order: funeral costs, then debts, then the will (at most one third, not for heirs), then the rest divided among the heirs by the shares of inheritance. ''The believer''s soul is held by his debt until it is paid'' (Jami'' al-Tirmidhi 1078)."}}, {"type": "ref", "text": {"bn": "ওসিয়ত এক-তৃতীয়াংশ: সহিহ বুখারি ২৭৪২", "en": "Will limited to one third: Sahih al-Bukhari 2742"}}, {"type": "heading", "text": {"bn": "শোক প্রকাশের সীমা", "en": "Limits of grief"}}, {"type": "text", "text": {"bn": "কান্না করা, চোখের পানি ফেলা স্বাভাবিক ও জায়েজ। পুত্র ইবরাহিমের মৃত্যুতে নবীজি (সা.)-এর চোখে পানি এসেছিল; তিনি বলেছিলেন, চোখ অশ্রু ঝরায়, হৃদয় ব্যথিত হয়, কিন্তু আমরা কেবল তা-ই বলি যাতে আমাদের রব সন্তুষ্ট (সহিহ বুখারি ১৩০৩)।", "en": "Crying and tears are natural and allowed. The Prophet wept at his son Ibrahim''s death and said: the eye weeps and the heart grieves, but we say only what pleases our Lord (Sahih al-Bukhari 1303)."}}, {"type": "note", "tone": "warn", "text": {"bn": "বিলাপ করে চিৎকার, গালে চড় মারা, কাপড় ছেঁড়া, বুক চাপড়ানো ও জাহেলি যুগের মতো কথা বলা নিষেধ: ‘সে আমাদের দলভুক্ত নয়, যে গালে আঘাত করে, কাপড় ছেঁড়ে এবং জাহেলি যুগের মতো আহাজারি করে’ (সহিহ বুখারি ১২৯৪)।", "en": "Wailing, slapping the cheeks, tearing clothes, beating the chest and words of the Jahiliyyah are forbidden: ''He is not of us who slaps his cheeks, tears his clothes and calls with the call of the Jahiliyyah'' (Sahih al-Bukhari 1294)."}}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'ae28428a-f5e4-5552-8d19-ba14f77d1fa7', id, 'janazah-ghusl', '{"bn": "মৃতের গোসল", "en": "Washing the Deceased (Ghusl)"}', '{"bn": "মৃত ব্যক্তিকে গোসল দেওয়ার ধাপগুলো, কে গোসল দেবেন, এবং প্রয়োজনীয় সামগ্রী।", "en": "Step-by-step washing of the deceased, who should wash, and what you need."}', 'detail', '[{"type": "text", "text": {"bn": "মৃত মুসলিমকে গোসল দেওয়া ফরজে কিফায়া: কিছু মানুষ করলে সবার দায়িত্ব আদায় হয়। নবীজি (সা.) তাঁর কন্যার গোসলের সময় বলেছিলেন, তাকে বরই পাতার পানি দিয়ে তিন, পাঁচ বা প্রয়োজনে আরও বেশি বার গোসল দাও, শেষবার কর্পূর দাও (সহিহ বুখারি ১২৫৩), এবং ডান দিক ও ওযুর অঙ্গগুলো থেকে শুরু করো (সহিহ বুখারি ১২৫৫)।", "en": "Washing a deceased Muslim is a communal obligation. At his daughter''s washing the Prophet said: wash her three, five or more times with water and lote leaves, with camphor in the last (Sahih al-Bukhari 1253), and begin with the right side and the parts of wudu (Sahih al-Bukhari 1255)."}}, {"type": "heading", "text": {"bn": "কে গোসল দেবেন", "en": "Who washes"}}, {"type": "list", "items": [{"bn": "পুরুষকে পুরুষ, নারীকে নারী গোসল দেবেন; পরিবারের নিকটজন ও যারা নিয়ম জানেন, তারা অগ্রাধিকার পাবেন।", "en": "Men wash men and women wash women; close family and those who know the method come first."}, {"bn": "ছোট শিশুকে (যে এখনো কামনার বয়সে পৌঁছেনি) পুরুষ বা নারী যে কেউ গোসল দিতে পারেন।", "en": "A young child may be washed by a man or a woman."}, {"bn": "গোসলদাতা বিশ্বস্ত হবেন; মৃতের শরীরে কোনো খারাপ কিছু দেখলে তা গোপন রাখবেন।", "en": "The washer should be trustworthy and keep private anything unpleasant they see."}]}, {"type": "differ", "title": {"bn": "স্বামী-স্ত্রী একে অপরকে গোসল দিতে পারবেন কি", "en": "May spouses wash each other"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "স্ত্রী মৃত স্বামীকে গোসল দিতে পারেন (ইদ্দত চলাকালে বিবাহের কিছু বিধান বহাল থাকে)। কিন্তু স্বামী মৃত স্ত্রীকে গোসল দিতে পারবেন না; মৃত্যুতে বিবাহের সম্পর্ক শেষ হয়ে যায়। তবে দেখতে ও কাফনের ওপর দিয়ে স্পর্শ করতে পারবেন।", "en": "A wife may wash her deceased husband (some marriage rulings continue during her ''iddah), but a husband may not wash his deceased wife, as the marriage ends with her death; he may see her and touch her over the shroud."}, "evidence": {"bn": "আয়েশা (রা.) বলেছেন, যা পরে জেনেছি তা আগে জানলে নবীজি (সা.)-কে তাঁর স্ত্রীরাই গোসল দিতেন (সুনান আবু দাউদ); স্ত্রীর ইদ্দত পালন বিবাহের প্রভাব বহাল থাকার প্রমাণ।", "en": "''A''ishah said that had she known earlier what she later knew, only his wives would have washed the Prophet (Sunan Abi Dawud); the widow''s ''iddah shows the marriage''s effects continue."}}, {"label": {"bn": "শাফেয়ি, মালেকি ও হাম্বলি", "en": "Shafi''i, Maliki, Hanbali"}, "text": {"bn": "স্বামী-স্ত্রী পরস্পরকে গোসল দিতে পারেন।", "en": "Spouses may wash each other."}, "evidence": {"bn": "নবীজি (সা.) আয়েশা (রা.)-কে বলেছিলেন, তুমি আমার আগে মারা গেলে আমি তোমাকে গোসল দিতাম ও কাফন পরাতাম (সুনান ইবনে মাজাহ ১৪৬৫); আলী (রা.) ফাতিমা (রা.)-কে গোসল দিয়েছিলেন বলে বর্ণিত।", "en": "The Prophet told ''A''ishah that if she died before him he would wash and shroud her (Sunan Ibn Majah 1465); ''Ali is reported to have washed Fatimah."}}], "check": true}, {"type": "heading", "text": {"bn": "প্রয়োজনীয় সামগ্রী", "en": "What you need"}}, {"type": "list", "items": [{"bn": "গোসলের খাটিয়া বা উঁচু তক্তা, পর্দা দেওয়া আড়াল", "en": "A washing board or raised bed, and a screened area"}, {"bn": "কুসুম গরম পানি, সাবান বা বরই পাতা মেশানো পানি, কর্পূর", "en": "Lukewarm water, soap or water with lote (boroi) leaves, camphor"}, {"bn": "সতর ঢাকার কাপড় (নাভি থেকে হাঁটু পর্যন্ত), হাতমোজা বা হাতে জড়ানোর কাপড়", "en": "A cloth to cover the awrah (navel to knee), gloves or hand cloths"}, {"bn": "তুলা, তোয়ালে, আতর বা সুগন্ধি, আগে থেকে প্রস্তুত কাফন", "en": "Cotton, towels, perfume, and the shroud ready beforehand"}]}, {"type": "heading", "text": {"bn": "গোসলের ধাপ", "en": "Steps of the ghusl"}}, {"type": "step", "title": {"bn": "খাটিয়ায় রাখা ও সতর ঢাকা", "en": "Place on the board and cover"}, "text": {"bn": "মৃতকে খাটিয়ায় রাখুন, সতর (নাভি থেকে হাঁটু) কাপড়ে ঢেকে পরনের কাপড় খুলে নিন। সতরের দিকে তাকাবেন না।", "en": "Lay the body on the board, cover the awrah (navel to knee), then remove the clothes. Do not look at the awrah."}}, {"type": "step", "title": {"bn": "পেট হালকা চেপে ইস্তিঞ্জা", "en": "Press the stomach and clean"}, "text": {"bn": "প্রাপ্তবয়স্ক হলে আস্তে করে পেটে চাপ দিন, যাতে ময়লা বের হয়ে যায়। হাতে কাপড় বা গ্লাভস পরে ঢাকা অবস্থায় লজ্জাস্থান পরিষ্কার করুন।", "en": "For an adult, gently press the stomach to expel waste. Wearing a glove or cloth, wash the private parts under the cover."}}, {"type": "step", "title": {"bn": "ওযু করানো", "en": "Give wudu"}, "text": {"bn": "নামাজের ওযুর মতো ওযু করান: চেহারা, হাত কনুই পর্যন্ত, মাথা মাসেহ, পা। হানাফি মতে কুলি ও নাকে পানি দেওয়া হয় না; ভেজা কাপড় বা তুলা দিয়ে দাঁত, মাড়ি ও নাকের ছিদ্র মুছে দিন, যাতে ভেতরে পানি না ঢোকে।", "en": "Perform wudu as for prayer: face, arms to the elbows, wipe the head, feet. Hanafis do not rinse the mouth and nose; wipe the teeth, gums and nostrils with wet cloth or cotton so water does not enter."}}, {"type": "step", "title": {"bn": "মাথা ও দাড়ি ধোয়া", "en": "Wash head and beard"}, "text": {"bn": "সাবান বা বরই পাতার পানি দিয়ে মাথা ও দাড়ি (বা চুল) ধুয়ে দিন।", "en": "Wash the head and beard (or hair) with soap or lote-leaf water."}}, {"type": "step", "title": {"bn": "বাম কাতে শুইয়ে ডান পাশ ধোয়া", "en": "Right side first"}, "text": {"bn": "মৃতকে বাম কাতে শুইয়ে মাথা থেকে পা পর্যন্ত ডান পাশে পানি ঢালুন, যতক্ষণ না পানি নিচ পর্যন্ত পৌঁছায় (সাধারণত তিনবার)।", "en": "Turn the body onto the left side and pour water over the right side from head to foot until it reaches underneath (usually three times)."}}, {"type": "step", "title": {"bn": "ডান কাতে শুইয়ে বাম পাশ ধোয়া", "en": "Then the left side"}, "text": {"bn": "এবার ডান কাতে শুইয়ে একইভাবে বাম পাশ ধুয়ে দিন।", "en": "Turn onto the right side and wash the left side the same way."}}, {"type": "step", "title": {"bn": "আবার পেট চেপে দেখা", "en": "Press the stomach again"}, "text": {"bn": "মৃতকে নিজের গায়ে হেলান দিয়ে একটু বসিয়ে আস্তে পেটে চাপ দিন। কিছু বের হলে শুধু সেই জায়গা ধুয়ে দিন; গোসল বা ওযু আবার করাতে হবে না (হানাফি)।", "en": "Sit the body up slightly against you and gently press the stomach. If anything comes out, wash only that area; the ghusl or wudu need not be repeated (Hanafi)."}}, {"type": "step", "title": {"bn": "শেষবার কর্পূর মেশানো পানি", "en": "Last wash with camphor"}, "text": {"bn": "শেষে কর্পূর মেশানো পানি পুরো শরীরে ঢালুন। মোট ধোয়া বেজোড় সংখ্যক হওয়া সুন্নত (তিন, পাঁচ বা সাত)।", "en": "Finally pour camphor water over the whole body. An odd number of washes is sunnah (three, five or seven)."}}, {"type": "step", "title": {"bn": "শুকানো ও সুগন্ধি", "en": "Dry and perfume"}, "text": {"bn": "তোয়ালে দিয়ে আস্তে মুছে দিন। মাথা ও দাড়িতে আতর, আর সিজদার অঙ্গগুলোতে (কপাল, নাক, দুই হাত, দুই হাঁটু, দুই পা) কর্পূর লাগান। তারপর কাফন পরান।", "en": "Pat dry with a towel. Apply perfume to the head and beard and camphor to the places of sajdah (forehead, nose, hands, knees, feet). Then shroud."}}, {"type": "note", "tone": "info", "text": {"bn": "হানাফি মতে মৃতের চুল আঁচড়ানো, নখ বা চুল কাটা হয় না। যুদ্ধক্ষেত্রে শহিদ হলে তাকে গোসল দেওয়া হয় না, পরনের কাপড়েই দাফন করা হয়; এর বিস্তারিত বিধান আলেমদের কাছে জেনে নিন।", "en": "In the Hanafi school the hair is not combed and nails and hair are not cut. A martyr killed in battle is not washed and is buried in his clothes; ask scholars for the details."}}, {"type": "note", "tone": "tip", "text": {"bn": "গোসলদাতার জন্য পরে নিজে গোসল করা মুস্তাহাব (সুনান আবু দাউদ ৩১৬১; এই হাদিসের মান নিয়ে মতভেদ আছে)।", "en": "It is recommended for the washer to bathe afterwards (Sunan Abi Dawud 3161; its grading is disputed)."}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '42081037-41f1-5482-82c5-2ed9fe3866bf', id, 'janazah-kafan', '{"bn": "কাফন: পুরুষ ও নারীর জন্য", "en": "The Shroud (Kafan) for Men and Women"}', '{"bn": "সুন্নত কাফনের কাপড়, পুরুষের তিন ও নারীর পাঁচ কাপড়, এবং কাফন পরানোর ধাপ।", "en": "The sunnah shroud: three pieces for men, five for women, and how to wrap."}', 'detail', '[{"type": "text", "text": {"bn": "কাফন সাদা কাপড়ের হওয়া উত্তম: ‘তোমরা সাদা কাপড় পরো, কারণ তা তোমাদের উত্তম পোশাক, আর এতে তোমাদের মৃতদের কাফন দাও’ (সুনান আবু দাউদ ৩৮৭৮; জামে তিরমিজি ৯৯৪)। নবীজি (সা.)-কে তিনটি সাদা ইয়েমেনি সুতি কাপড়ে কাফন দেওয়া হয়েছিল, তাতে জামা বা পাগড়ি ছিল না (সহিহ বুখারি ১২৬৪)। কাফনের খরচ মৃতের সম্পদ থেকে সবার আগে দেওয়া হয়; সাধ্যের বাইরে দামি কাফন জরুরি নয়।", "en": "White is best: ''Wear white, for it is among your best clothes, and shroud your dead in it'' (Sunan Abi Dawud 3878; Jami'' al-Tirmidhi 994). The Prophet was shrouded in three white Yemeni cotton sheets, with no shirt or turban (Sahih al-Bukhari 1264). The shroud is paid from the estate first; an expensive shroud is not needed."}}, {"type": "table", "head": [{"bn": "কাপড়", "en": "Piece"}, {"bn": "বিবরণ (হানাফি পরিভাষা)", "en": "Description (Hanafi terms)"}, {"bn": "পুরুষ", "en": "Men"}, {"bn": "নারী", "en": "Women"}], "rows": [[{"bn": "লিফাফা (চাদর)", "en": "Lifafah (outer sheet)"}, {"bn": "মাথার ওপর থেকে পায়ের নিচ পর্যন্ত, দুই প্রান্তে বাঁধার মতো বাড়তি", "en": "From above the head to below the feet, with extra to tie at both ends"}, {"bn": "✓", "en": "✓"}, {"bn": "✓", "en": "✓"}], [{"bn": "ইজার", "en": "Izar (inner sheet)"}, {"bn": "মাথা থেকে পা পর্যন্ত", "en": "From head to feet"}, {"bn": "✓", "en": "✓"}, {"bn": "✓", "en": "✓"}], [{"bn": "কামিস (কোর্তা)", "en": "Qamis (shirt)"}, {"bn": "কাঁধ থেকে হাঁটুর নিচ পর্যন্ত, হাতা ও কলি ছাড়া, মাথা ঢোকানোর ফাঁক থাকে", "en": "Shoulders to below the knees, without sleeves or side panels, with a slit for the head"}, {"bn": "✓", "en": "✓"}, {"bn": "✓", "en": "✓"}], [{"bn": "ওড়না (খিমার)", "en": "Khimar (head cover)"}, {"bn": "মাথা ও চুল ঢাকার কাপড়", "en": "Covers the head and hair"}, {"bn": "—", "en": "—"}, {"bn": "✓", "en": "✓"}], [{"bn": "সিনাবন্দ", "en": "Sinaband (chest wrap)"}, {"bn": "বুক থেকে উরু পর্যন্ত", "en": "From the chest to the thighs"}, {"bn": "—", "en": "—"}, {"bn": "✓", "en": "✓"}]]}, {"type": "text", "text": {"bn": "পুরুষের সুন্নত কাফন তিন কাপড়; প্রয়োজনে দুই কাপড়ও যথেষ্ট (কিফায়া)। নারীর সুন্নত কাফন পাঁচ কাপড়; প্রয়োজনে তিন কাপড় (লিফাফা, ইজার, ওড়না) যথেষ্ট। নিরুপায় অবস্থায় যতটুকু পাওয়া যায়, তাতেই শরীর ঢেকে দেওয়া হবে।", "en": "The sunnah shroud for men is three pieces; two suffice if needed. For women it is five; three (lifafah, izar, khimar) suffice if needed. In necessity, cover the body with whatever is available."}}, {"type": "note", "tone": "info", "text": {"bn": "নারীর পাঁচ কাপড়ের হাদিস (সুনান আবু দাউদ ৩১৫৭) সনদের দিক থেকে দুর্বল বলে মুহাদ্দিসরা উল্লেখ করেছেন; তবে চার মাজহাবেই নারীর জন্য পাঁচ কাপড় সুন্নত বলা হয়েছে (কাপড়ের ধরনে কিছু ভিন্নতাসহ)।", "en": "The hadith on five pieces for women (Sunan Abi Dawud 3157) is graded weak, but all four schools hold five pieces sunnah for women (with some differences in the pieces)."}}, {"type": "heading", "text": {"bn": "পুরুষের কাফন পরানো", "en": "Shrouding a man"}}, {"type": "step", "title": {"bn": "কাপড় বিছানো", "en": "Lay out the sheets"}, "text": {"bn": "প্রথমে লিফাফা বিছান, তার ওপর ইজার, তার ওপর কামিসের নিচের অংশ (ওপরের অংশ মাথার দিকে গুটিয়ে রাখুন)। চাইলে কাপড়ে বেজোড় সংখ্যায় সুগন্ধির ধোঁয়া দিতে পারেন।", "en": "Spread the lifafah, then the izar on it, then the lower half of the qamis (fold the upper half towards the head)."}}, {"type": "step", "title": {"bn": "কামিস পরানো", "en": "Put on the qamis"}, "text": {"bn": "মৃতকে শুইয়ে কামিসের ওপরের অংশ মাথা গলিয়ে বুক ও শরীরের ওপর টেনে দিন; সতরের কাপড় সরিয়ে নিন।", "en": "Lay the body down, pass the qamis over the head and draw it down over the body; remove the awrah cloth."}}, {"type": "step", "title": {"bn": "ইজার মোড়ানো", "en": "Wrap the izar"}, "text": {"bn": "ইজারের বাম পাশ আগে শরীরের ওপর ভাঁজ করুন, তারপর ডান পাশ ওপরে দিন।", "en": "Fold the left side of the izar over the body first, then the right side over it."}}, {"type": "step", "title": {"bn": "লিফাফা মোড়ানো ও বাঁধা", "en": "Wrap and tie the lifafah"}, "text": {"bn": "একইভাবে লিফাফার বাম পাশ, তারপর ডান পাশ ভাঁজ করুন। খুলে যাওয়ার আশঙ্কা থাকলে মাথা, কোমর ও পায়ের দিকে কাপড়ের ফিতা দিয়ে বেঁধে দিন; কবরে রাখার পর বাঁধনগুলো খুলে দেবেন।", "en": "Fold the lifafah left then right in the same way. Tie strips at the head, waist and feet if it may open; untie them in the grave."}}, {"type": "heading", "text": {"bn": "নারীর কাফন পরানো", "en": "Shrouding a woman"}}, {"type": "step", "title": {"bn": "কাপড় বিছানো", "en": "Lay out the sheets"}, "text": {"bn": "প্রথমে লিফাফা, তার ওপর সিনাবন্দ (কেউ কেউ শেষে ওপরে বাঁধেন), তার ওপর ইজার, তার ওপর কামিস বিছান।", "en": "Spread the lifafah, then the sinaband (some tie it last, on top), then the izar, then the qamis."}}, {"type": "step", "title": {"bn": "কামিস ও চুল", "en": "Qamis and hair"}, "text": {"bn": "কামিস পরিয়ে দিন। চুল দুই ভাগ করে কামিসের ওপর বুকের দুই পাশে রেখে দিন।", "en": "Put on the qamis. Divide the hair into two parts and place them on the chest over the qamis."}}, {"type": "step", "title": {"bn": "ওড়না", "en": "Khimar"}, "text": {"bn": "ওড়না দিয়ে মাথা ও চুল ঢেকে দিন; বাঁধবেন না, পেঁচাবেন না।", "en": "Cover the head and hair with the khimar, without tying or twisting it."}}, {"type": "step", "title": {"bn": "ইজার, সিনাবন্দ ও লিফাফা", "en": "Izar, sinaband and lifafah"}, "text": {"bn": "ইজার বাম তারপর ডান পাশ থেকে মোড়ান, তারপর সিনাবন্দ বুক থেকে উরু পর্যন্ত বেঁধে দিন, সবশেষে লিফাফা বাম তারপর ডান পাশ থেকে মুড়িয়ে প্রয়োজনে মাথা, কোমর ও পায়ের দিকে বেঁধে দিন।", "en": "Wrap the izar left then right, tie the sinaband from chest to thighs, then wrap the lifafah left then right and tie at the head, waist and feet if needed."}}, {"type": "note", "tone": "warn", "text": {"bn": "কাফনে কালিমা, আয়াত বা দোয়া লেখার প্রথা কুরআন-সুন্নাহয় নেই; কাপড় নাপাক হওয়ার আশঙ্কায় অনেক আলেম এ থেকে নিষেধ করেছেন।", "en": "Writing the kalimah, verses or du''as on the shroud has no basis in the Quran or sunnah; many scholars forbid it since the cloth may become impure."}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '2e749364-1451-5174-b322-2853dd48c913', id, 'janazah-prayer', '{"bn": "জানাযার নামাজ: ধাপে ধাপে", "en": "Janazah Prayer Step by Step"}', '{"bn": "চার তাকবিরের জানাযার নামাজ: প্রতিটি তাকবিরের পর কী পড়বেন, প্রাপ্তবয়স্ক নারী-পুরুষ ও শিশুর জন্য দোয়া, এবং মতভেদের বিষয়গুলো।", "en": "The four-takbir funeral prayer: what to recite after each takbir, du''as for adults (male and female) and children, and points of difference."}', 'basic', '[{"type": "text", "text": {"bn": "জানাযার নামাজ ফরজে কিফায়া। এতে রুকু-সিজদা নেই; দাঁড়িয়ে চার তাকবিরে পড়া হয়। নবীজি (সা.) নাজাশির জানাযায় চার তাকবির দিয়েছিলেন (সহিহ বুখারি ১২৪৫)। নামাজের মতোই ওযু, পবিত্রতা, সতর ঢাকা ও কিবলামুখী হওয়া শর্ত।", "en": "The funeral prayer is a communal obligation. It has no ruku'' or sajdah; it is prayed standing with four takbirs. The Prophet made four takbirs over the Negus (Sahih al-Bukhari 1245). Wudu, purity, covered awrah and facing the qiblah are required as for prayer."}}, {"type": "arabic", "label": {"bn": "ফজিলত", "en": "Virtue"}, "ar": "مَنْ شَهِدَ الْجَنَازَةَ حَتَّى يُصَلَّى عَلَيْهَا فَلَهُ قِيرَاطٌ، وَمَنْ شَهِدَهَا حَتَّى تُدْفَنَ فَلَهُ قِيرَاطَانِ", "pron": {"bn": "মান শাহিদাল জানাযাতা হাত্তা ইউসাল্লা আলাইহা ফালাহূ কীরাত, ওয়া মান শাহিদাহা হাত্তা তুদফানা ফালাহূ কীরাতান।", "en": "Man shahidal-janazata hatta yusalla ''alayha falahu qirat, wa man shahidaha hatta tudfana falahu qiratan."}, "meaning": {"bn": "যে জানাযায় উপস্থিত থেকে নামাজ পড়ে, তার জন্য এক কিরাত সওয়াব; আর যে দাফন পর্যন্ত থাকে, তার জন্য দুই কিরাত। জিজ্ঞেস করা হলো, দুই কিরাত কী? তিনি বললেন, দুটি বিশাল পাহাড়ের সমান।", "en": "Whoever attends a funeral until the prayer gets one qirat of reward; whoever stays until burial gets two qirats, like two great mountains."}, "ref": {"bn": "সহিহ বুখারি ১৩২৫", "en": "Sahih al-Bukhari 1325"}}, {"type": "heading", "text": {"bn": "প্রস্তুতি", "en": "Preparation"}}, {"type": "list", "items": [{"bn": "লাশ ইমামের সামনে কিবলার দিকে রাখা হবে, মাথা উত্তর দিকে (বাংলাদেশে) থাকে।", "en": "The body is placed in front of the imam towards the qiblah, with the head to the north (in Bangladesh)."}, {"bn": "কাতার বেজোড় সংখ্যায় করা মুস্তাহাব বলে অনেকে উল্লেখ করেন; তিন কাতারের ফজিলতের হাদিস (সুনান আবু দাউদ ৩১৬৬) দুর্বল।", "en": "Many prefer an odd number of rows; the hadith on three rows (Sunan Abi Dawud 3166) is weak."}, {"bn": "নিয়ত মনে মনে। উদাহরণ (প্রচলিত বাংলা): ‘আমি এই মাইয়্যেতের জানাযার নামাজ চার তাকবিরের সাথে আল্লাহর জন্য, মাইয়্যেতের জন্য দোয়া হিসেবে, এই ইমামের পেছনে আদায় করছি।’ মুখে বলা জরুরি নয়।", "en": "Niyyah in the heart. Example (common Bangla phrasing): ''I am praying the funeral prayer for this deceased with four takbirs, for Allah, as a du''a for the deceased, behind this imam.'' Saying it is not required."}]}, {"type": "differ", "title": {"bn": "ইমাম লাশের কোন বরাবর দাঁড়াবেন", "en": "Where the imam stands"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "পুরুষ ও নারী উভয়ের ক্ষেত্রে বুক বরাবর।", "en": "At the chest, for both men and women."}, "evidence": {"bn": "বুক ঈমানের স্থান; সাহাবিদের কিছু আমল থেকে নেওয়া।", "en": "The chest is the seat of faith; based on some Companions'' practice."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "পুরুষের মাথা বরাবর, নারীর কোমর (মাঝখান) বরাবর।", "en": "At the head of a man and the middle of a woman."}, "evidence": {"bn": "নবীজি (সা.) প্রসবকালে মৃত এক নারীর জানাযায় তার মাঝখান বরাবর দাঁড়িয়েছিলেন (সহিহ বুখারি ১৩৩২); আনাস (রা.) পুরুষের মাথা ও নারীর মাঝখান বরাবর দাঁড়াতেন (সুনান আবু দাউদ ৩১৯৪; জামে তিরমিজি ১০৩৪)।", "en": "The Prophet stood at the middle of a woman who died in childbirth (Sahih al-Bukhari 1332); Anas stood at a man''s head and a woman''s middle (Sunan Abi Dawud 3194; Jami'' al-Tirmidhi 1034)."}}]}, {"type": "heading", "text": {"bn": "প্রথম তাকবির ও সানা", "en": "First takbir and thana"}}, {"type": "step", "title": {"bn": "প্রথম তাকবির", "en": "First takbir"}, "text": {"bn": "কান পর্যন্ত হাত তুলে ‘আল্লাহু আকবার’ বলে নাভির নিচে (নারীরা বুকে) হাত বাঁধুন। ইমাম জোরে তাকবির বলবেন, মুক্তাদিরা আস্তে।", "en": "Raise the hands to the ears saying ''Allahu Akbar'' and fold them. The imam says the takbirs aloud, followers quietly."}}, {"type": "arabic", "label": {"bn": "তাকবির", "en": "Takbir"}, "ar": "اللّٰهُ أَكْبَرُ", "pron": {"bn": "আল্লাহু আকবার", "en": "Allahu Akbar"}, "meaning": {"bn": "আল্লাহ সবচেয়ে বড়।", "en": "Allah is the Greatest."}}, {"type": "arabic", "label": {"bn": "সানা (প্রথম তাকবিরের পর, হানাফি)", "en": "Thana (after the first takbir, Hanafi)"}, "ar": "سُبْحَانَكَ اللّٰهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَىٰ جَدُّكَ، وَجَلَّ ثَنَاؤُكَ، وَلَا إِلٰهَ غَيْرُكَ", "pron": {"bn": "সুবহানাকা আল্লাহুম্মা ওয়া বিহামদিকা, ওয়া তাবারাকাসমুকা, ওয়া তাআলা জাদ্দুকা, ওয়া জাল্লা সানাউকা, ওয়া লা ইলাহা গাইরুক।", "en": "Subhanakallahumma wa bihamdika, wa tabarakasmuka, wa ta''ala jadduka, wa jalla thana''uka, wa la ilaha ghayruk."}, "meaning": {"bn": "হে আল্লাহ, তুমি পবিত্র, সকল প্রশংসা তোমার; তোমার নাম বরকতময়, তোমার মর্যাদা সুউচ্চ, তোমার প্রশংসা মহান; আর তুমি ছাড়া কোনো ইলাহ নেই।", "en": "Glory be to You, O Allah, and praise; blessed is Your name, exalted is Your majesty, great is Your praise, and there is no god besides You."}, "ref": {"bn": "মূল সানা: সুনান আবু দাউদ ৭৭৬", "en": "Base thana: Sunan Abi Dawud 776"}}, {"type": "note", "tone": "info", "text": {"bn": "‘ওয়া জাল্লা সানাউকা’ অংশটি সাধারণ নামাজের সানার হাদিসে (আবু দাউদ ৭৭৬) নেই; হানাফি ফিকহের কিতাবে জানাযার সানায় এটি যোগ করার কথা বলা হয়েছে। না বললেও নামাজ হয়ে যাবে।", "en": "The phrase ''wa jalla thana''uka'' is not in the hadith of the regular thana (Abu Dawud 776); Hanafi fiqh books add it in the funeral thana. The prayer is valid without it."}}, {"type": "differ", "title": {"bn": "প্রথম তাকবিরের পর সানা না সূরা ফাতিহা", "en": "Thana or al-Fatihah after the first takbir"}, "views": [{"label": {"bn": "হানাফি ও মালেকি", "en": "Hanafi and Maliki"}, "text": {"bn": "সানা পড়বে; জানাযায় কিরাত হিসেবে সূরা ফাতিহা পড়া জরুরি নয়। (হানাফি মতে কেউ সানা ও প্রশংসার নিয়তে ফাতিহা পড়লে সমস্যা নেই।)", "en": "Recite the thana; al-Fatihah is not required as recitation (Hanafis allow it with the intention of praise)."}, "evidence": {"bn": "জানাযা মূলত মৃতের জন্য দোয়া; ইবনে মাসউদ (রা.) প্রমুখ সাহাবি থেকে জানাযায় নির্দিষ্ট কিরাত না থাকার কথা বর্ণিত।", "en": "The funeral prayer is essentially du''a; reports from Ibn Mas''ud and others that it has no fixed recitation."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "প্রথম তাকবিরের পর সূরা ফাতিহা পড়া ফরজ/রুকন।", "en": "Reciting al-Fatihah after the first takbir is obligatory."}, "evidence": {"bn": "ইবনে আব্বাস (রা.) জানাযায় সূরা ফাতিহা পড়ে বললেন, যাতে তোমরা জানো এটি সুন্নত (সহিহ বুখারি ১৩৩৫)।", "en": "Ibn ''Abbas recited al-Fatihah in a funeral prayer and said, ''so that you know it is the sunnah'' (Sahih al-Bukhari 1335)."}}]}, {"type": "heading", "text": {"bn": "দ্বিতীয় তাকবির ও দরুদ", "en": "Second takbir and durood"}}, {"type": "step", "title": {"bn": "দ্বিতীয় তাকবির", "en": "Second takbir"}, "text": {"bn": "হাত না তুলে (হানাফি) ‘আল্লাহু আকবার’ বলুন এবং দরুদে ইবরাহিম পড়ুন।", "en": "Say ''Allahu Akbar'' without raising the hands (Hanafi) and recite the durood Ibrahim."}}, {"type": "arabic", "label": {"bn": "দরুদে ইবরাহিম", "en": "Durood Ibrahim"}, "ar": "اللّٰهُمَّ صَلِّ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ. اللّٰهُمَّ بَارِكْ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ", "pron": {"bn": "আল্লাহুম্মা সাল্লি আলা মুহাম্মাদিও ওয়া আলা আলি মুহাম্মাদ, কামা সাল্লাইতা আলা ইবরাহীমা ওয়া আলা আলি ইবরাহীম, ইন্নাকা হামীদুম মাজীদ। আল্লাহুম্মা বারিক আলা মুহাম্মাদিও ওয়া আলা আলি মুহাম্মাদ, কামা বারাকতা আলা ইবরাহীমা ওয়া আলা আলি ইবরাহীম, ইন্নাকা হামীদুম মাজীদ।", "en": "Allahumma salli ''ala Muhammadin wa ''ala ali Muhammad, kama sallayta ''ala Ibrahima wa ''ala ali Ibrahim, innaka Hamidum Majid. Allahumma barik ''ala Muhammadin wa ''ala ali Muhammad, kama barakta ''ala Ibrahima wa ''ala ali Ibrahim, innaka Hamidum Majid."}, "meaning": {"bn": "হে আল্লাহ, মুহাম্মাদ ও মুহাম্মাদের পরিবারের ওপর রহমত বর্ষণ করো, যেমন ইবরাহিম ও ইবরাহিমের পরিবারের ওপর করেছ; নিশ্চয়ই তুমি প্রশংসিত, মহিমান্বিত। হে আল্লাহ, মুহাম্মাদ ও মুহাম্মাদের পরিবারের ওপর বরকত দাও, যেমন ইবরাহিম ও ইবরাহিমের পরিবারের ওপর দিয়েছ; নিশ্চয়ই তুমি প্রশংসিত, মহিমান্বিত।", "en": "O Allah, send blessings on Muhammad and the family of Muhammad as You sent blessings on Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious. O Allah, bless Muhammad and the family of Muhammad as You blessed Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious."}, "ref": {"bn": "সহিহ বুখারি ৩৩৭০", "en": "Sahih al-Bukhari 3370"}}, {"type": "heading", "text": {"bn": "তৃতীয় তাকবির ও মৃতের জন্য দোয়া", "en": "Third takbir and du''a for the deceased"}}, {"type": "step", "title": {"bn": "তৃতীয় তাকবির", "en": "Third takbir"}, "text": {"bn": "‘আল্লাহু আকবার’ বলে মৃতের জন্য দোয়া পড়ুন। প্রাপ্তবয়স্কের জন্য প্রথম দোয়াটি (নারী-পুরুষ সবার জন্য) পড়া যায়; সাথে বা এর বদলে পুরুষ/নারীর আলাদা দোয়াটিও পড়া যায়। নাবালেগ শিশুর জন্য শিশুর দোয়া।", "en": "Say ''Allahu Akbar'' and make du''a for the deceased. For an adult, the first du''a (for men and women) may be said, and/or the separate male/female du''a. For a child, the child''s du''a."}}, {"type": "arabic", "label": {"bn": "প্রাপ্তবয়স্কের জন্য দোয়া (নারী-পুরুষ উভয়ের জন্য)", "en": "Du''a for an adult (male or female)"}, "ar": "اللّٰهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا، وَشَاهِدِنَا وَغَائِبِنَا، وَصَغِيرِنَا وَكَبِيرِنَا، وَذَكَرِنَا وَأُنْثَانَا. اللّٰهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِسْلَامِ، وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الْإِيمَانِ", "pron": {"bn": "আল্লাহুম্মাগফির লিহাইয়িনা ওয়া মাইয়িতিনা, ওয়া শাহিদিনা ওয়া গাইবিনা, ওয়া সাগীরিনা ওয়া কাবীরিনা, ওয়া যাকারিনা ওয়া উনসানা। আল্লাহুম্মা মান আহইয়াইতাহূ মিন্না ফাআহয়িহী আলাল ইসলাম, ওয়া মান তাওয়াফফাইতাহূ মিন্না ফাতাওয়াফফাহূ আলাল ঈমান।", "en": "Allahummaghfir lihayyina wa mayyitina, wa shahidina wa gha''ibina, wa saghirina wa kabirina, wa dhakarina wa unthana. Allahumma man ahyaytahu minna fa-ahyihi ''alal-Islam, wa man tawaffaytahu minna fatawaffahu ''alal-iman."}, "meaning": {"bn": "হে আল্লাহ, আমাদের জীবিত ও মৃত, উপস্থিত ও অনুপস্থিত, ছোট ও বড়, পুরুষ ও নারী সবাইকে ক্ষমা করো। হে আল্লাহ, আমাদের মধ্যে যাকে তুমি জীবিত রাখো, তাকে ইসলামের ওপর জীবিত রাখো; আর যাকে মৃত্যু দাও, তাকে ঈমানের সাথে মৃত্যু দাও।", "en": "O Allah, forgive our living and our dead, those present and absent, our young and old, our males and females. O Allah, whoever of us You keep alive, keep him alive upon Islam, and whoever of us You take, take him upon faith."}, "ref": {"bn": "জামে তিরমিজি ১০২৪; সুনান আবু দাউদ ৩২০১; সুনান ইবনে মাজাহ ১৪৯৮", "en": "Jami'' al-Tirmidhi 1024; Sunan Abi Dawud 3201; Sunan Ibn Majah 1498"}}, {"type": "note", "tone": "info", "text": {"bn": "আবু দাউদের বর্ণনায় ‘ইসলাম’ ও ‘ঈমান’ শব্দ দুটির স্থান উল্টো, এবং শেষে আছে: ‘আল্লাহুম্মা লা তাহরিমনা আজরাহূ ওয়া লা তুদিল্লানা বা''দাহূ’ (হে আল্লাহ, আমাদের তার প্রতিদান থেকে বঞ্চিত কোরো না এবং তার পরে আমাদের পথভ্রষ্ট কোরো না)। এটি যোগ করে পড়া যায়।", "en": "Abu Dawud''s narration swaps ''Islam'' and ''iman'' and adds: ''Allahumma la tahrimna ajrahu wa la tudillana ba''dah'' (O Allah, do not deprive us of his reward or lead us astray after him). It may be added."}}, {"type": "arabic", "label": {"bn": "পুরুষের জন্য দোয়া", "en": "Du''a for a man"}, "ar": "اللّٰهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ، وَعَافِهِ وَاعْفُ عَنْهُ، وَأَكْرِمْ نُزُلَهُ، وَوَسِّعْ مُدْخَلَهُ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ، وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ، وَزَوْجًا خَيْرًا مِنْ زَوْجِهِ، وَأَدْخِلْهُ الْجَنَّةَ، وَأَعِذْهُ مِنْ عَذَابِ الْقَبْرِ وَعَذَابِ النَّارِ", "pron": {"bn": "আল্লাহুম্মাগফির লাহূ ওয়ারহামহু, ওয়া আফিহী ওয়া''ফু আনহু, ওয়া আকরিম নুযুলাহূ, ওয়া ওয়াসসি'' মুদখালাহূ, ওয়াগসিলহু বিলমায়ি ওয়াসসালজি ওয়াল বারাদ, ওয়া নাক্কিহী মিনাল খাতায়া কামা নাক্কাইতাস সাওবাল আবইয়াদা মিনাদ দানাস, ওয়া আবদিলহু দারান খাইরাম মিন দারিহী, ওয়া আহলান খাইরাম মিন আহলিহী, ওয়া যাওজান খাইরাম মিন যাওজিহী, ওয়া আদখিলহুল জান্নাতা, ওয়া আইযহু মিন আযাবিল কাবরি ওয়া আযাবিন নার।", "en": "Allahummaghfir lahu warhamhu, wa ''afihi wa''fu ''anhu, wa akrim nuzulahu, wa wassi'' mudkhalahu, waghsilhu bil-ma''i wath-thalji wal-barad, wa naqqihi minal-khataya kama naqqaytath-thawbal-abyada minad-danas, wa abdilhu daran khayran min darihi, wa ahlan khayran min ahlihi, wa zawjan khayran min zawjihi, wa adkhilhul-jannata, wa a''idhhu min ''adhabil-qabri wa ''adhabin-nar."}, "meaning": {"bn": "হে আল্লাহ, তাকে ক্ষমা করো, তার প্রতি দয়া করো, তাকে নিরাপদ রাখো ও মাফ করে দাও; তার আতিথেয়তা সম্মানজনক করো, তার প্রবেশস্থল (কবর) প্রশস্ত করো; তাকে পানি, বরফ ও শিলা দিয়ে ধুয়ে দাও; তাকে গুনাহ থেকে এমনভাবে পরিষ্কার করো, যেমন সাদা কাপড় ময়লা থেকে পরিষ্কার করা হয়; তাকে তার ঘরের চেয়ে উত্তম ঘর, পরিবারের চেয়ে উত্তম পরিবার ও সঙ্গীর চেয়ে উত্তম সঙ্গী দাও; তাকে জান্নাতে প্রবেশ করাও এবং কবরের আজাব ও জাহান্নামের আজাব থেকে রক্ষা করো।", "en": "O Allah, forgive him and have mercy on him, keep him safe and pardon him, honour his reception and widen his entry, wash him with water, snow and hail, cleanse him of sins as a white garment is cleansed of dirt, give him a home better than his home, a family better than his family and a spouse better than his spouse, admit him to Paradise and protect him from the punishment of the grave and of the Fire."}, "ref": {"bn": "সহিহ মুসলিম ৯৬৩ (আওফ ইবনে মালিক রা.)", "en": "Sahih Muslim 963 (''Awf ibn Malik)"}}, {"type": "arabic", "label": {"bn": "নারীর জন্য দোয়া", "en": "Du''a for a woman"}, "ar": "اللّٰهُمَّ اغْفِرْ لَهَا وَارْحَمْهَا، وَعَافِهَا وَاعْفُ عَنْهَا، وَأَكْرِمْ نُزُلَهَا، وَوَسِّعْ مُدْخَلَهَا، وَاغْسِلْهَا بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهَا مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ، وَأَبْدِلْهَا دَارًا خَيْرًا مِنْ دَارِهَا، وَأَهْلًا خَيْرًا مِنْ أَهْلِهَا، وَزَوْجًا خَيْرًا مِنْ زَوْجِهَا، وَأَدْخِلْهَا الْجَنَّةَ، وَأَعِذْهَا مِنْ عَذَابِ الْقَبْرِ وَعَذَابِ النَّارِ", "pron": {"bn": "আল্লাহুম্মাগফির লাহা ওয়ারহামহা, ওয়া আফিহা ওয়া''ফু আনহা, ওয়া আকরিম নুযুলাহা, ওয়া ওয়াসসি'' মুদখালাহা, ওয়াগসিলহা বিলমায়ি ওয়াসসালজি ওয়াল বারাদ, ওয়া নাক্কিহা মিনাল খাতায়া কামা নাক্কাইতাস সাওবাল আবইয়াদা মিনাদ দানাস, ওয়া আবদিলহা দারান খাইরাম মিন দারিহা, ওয়া আহলান খাইরাম মিন আহলিহা, ওয়া যাওজান খাইরাম মিন যাওজিহা, ওয়া আদখিলহাল জান্নাতা, ওয়া আইযহা মিন আযাবিল কাবরি ওয়া আযাবিন নার।", "en": "Allahummaghfir laha warhamha, wa ''afiha wa''fu ''anha, wa akrim nuzulaha, wa wassi'' mudkhalaha, waghsilha bil-ma''i wath-thalji wal-barad, wa naqqiha minal-khataya kama naqqaytath-thawbal-abyada minad-danas, wa abdilha daran khayran min dariha, wa ahlan khayran min ahliha, wa zawjan khayran min zawjiha, wa adkhilhal-jannata, wa a''idhha min ''adhabil-qabri wa ''adhabin-nar."}, "meaning": {"bn": "একই দোয়া নারীর জন্য (সর্বনাম স্ত্রীলিঙ্গে): হে আল্লাহ, তাকে ক্ষমা করো, তার প্রতি দয়া করো ... তাকে জান্নাতে প্রবেশ করাও এবং কবর ও জাহান্নামের আজাব থেকে রক্ষা করো।", "en": "The same du''a for a woman (feminine pronouns): O Allah, forgive her and have mercy on her ... admit her to Paradise and protect her from the punishment of the grave and of the Fire."}, "ref": {"bn": "সহিহ মুসলিম ৯৬৩-এর দোয়া, স্ত্রীলিঙ্গে", "en": "The du''a of Sahih Muslim 963 in the feminine"}}, {"type": "note", "tone": "info", "text": {"bn": "মুসলিমের বর্ণনায় শেষ অংশে বর্ণনাকারী বলেছেন ‘কবরের আজাব থেকে অথবা জাহান্নামের আজাব থেকে’; তাই এখানে দুটোই রাখা হয়েছে। নারীর ক্ষেত্রে ‘ওয়া যাওজান খাইরাম মিন যাওজিহা’ অংশ বলা নিয়ে আলেমদের ভিন্নমত আছে; কেউ কেউ এ অংশ বাদ দিয়ে পড়েন।", "en": "In Muslim''s narration the narrator says ''from the punishment of the grave or of the Fire'', so both are kept here. For a woman, scholars differ on saying ''a spouse better than her spouse''; some omit it."}}, {"type": "arabic", "label": {"bn": "নাবালেগ ছেলে শিশুর জন্য", "en": "For a boy (not yet adult)"}, "ar": "اللّٰهُمَّ اجْعَلْهُ لَنَا فَرَطًا، وَاجْعَلْهُ لَنَا أَجْرًا وَذُخْرًا، وَاجْعَلْهُ لَنَا شَافِعًا وَمُشَفَّعًا", "pron": {"bn": "আল্লাহুম্মাজ আলহু লানা ফারাতাও, ওয়াজ আলহু লানা আজরাও ওয়া যুখরাও, ওয়াজ আলহু লানা শাফিআও ওয়া মুশাফফাআ।", "en": "Allahummaj''alhu lana faratan, waj''alhu lana ajran wa dhukhran, waj''alhu lana shafi''an wa mushaffa''a."}, "meaning": {"bn": "হে আল্লাহ, তাকে আমাদের জন্য অগ্রগামী (আমাদের আগে পৌঁছে অপেক্ষাকারী) বানাও, তাকে আমাদের জন্য প্রতিদান ও সঞ্চয় বানাও, এবং তাকে আমাদের জন্য সুপারিশকারী ও এমন বানাও যার সুপারিশ কবুল হয়।", "en": "O Allah, make him a forerunner for us, a reward and a treasure for us, and an intercessor for us whose intercession is accepted."}, "ref": {"bn": "হানাফি ফিকহের কিতাবে বর্ণিত; সহিহ বুখারির জানাযা অধ্যায়ে হাসান বসরি (রহ.)-এর উক্তিতে ‘আল্লাহুম্মাজ আলহু লানা ফারাতান ওয়া সালাফান ওয়া আজরান’ আছে", "en": "Given in Hanafi fiqh books; Sahih al-Bukhari''s funerals chapter cites al-Hasan al-Basri saying ''Allahummaj''alhu lana faratan wa salafan wa ajra''"}, "check": true}, {"type": "arabic", "label": {"bn": "নাবালেগ মেয়ে শিশুর জন্য", "en": "For a girl (not yet adult)"}, "ar": "اللّٰهُمَّ اجْعَلْهَا لَنَا فَرَطًا، وَاجْعَلْهَا لَنَا أَجْرًا وَذُخْرًا، وَاجْعَلْهَا لَنَا شَافِعَةً وَمُشَفَّعَةً", "pron": {"bn": "আল্লাহুম্মাজ আলহা লানা ফারাতাও, ওয়াজ আলহা লানা আজরাও ওয়া যুখরাও, ওয়াজ আলহা লানা শাফিআতাও ওয়া মুশাফফাআহ।", "en": "Allahummaj''alha lana faratan, waj''alha lana ajran wa dhukhran, waj''alha lana shafi''atan wa mushaffa''ah."}, "meaning": {"bn": "হে আল্লাহ, তাকে (মেয়েটিকে) আমাদের জন্য অগ্রগামী বানাও, আমাদের জন্য প্রতিদান ও সঞ্চয় বানাও, এবং আমাদের জন্য সুপারিশকারিণী ও এমন বানাও যার সুপারিশ কবুল হয়।", "en": "O Allah, make her a forerunner for us, a reward and a treasure for us, and an intercessor for us whose intercession is accepted."}, "ref": {"bn": "হানাফি ফিকহের কিতাবে বর্ণিত (ছেলে শিশুর দোয়ার স্ত্রীলিঙ্গ রূপ)", "en": "Given in Hanafi fiqh books (feminine of the boy''s du''a)"}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "কোনো দোয়া মুখস্থ না থাকলে যতটুকু জানেন বা নিজের ভাষায় মৃতের জন্য ক্ষমা ও রহমতের দোয়া করুন; জানাযার মূল উদ্দেশ্য মৃতের জন্য আন্তরিক দোয়া।", "en": "If you do not know these by heart, make du''a for forgiveness and mercy for the deceased with what you know or in your own words; sincere du''a is the heart of this prayer."}}, {"type": "heading", "text": {"bn": "চতুর্থ তাকবির ও সালাম", "en": "Fourth takbir and salam"}}, {"type": "step", "title": {"bn": "চতুর্থ তাকবির", "en": "Fourth takbir"}, "text": {"bn": "‘আল্লাহু আকবার’ বলুন। এরপর কোনো নির্দিষ্ট দোয়া জরুরি নয় (হানাফি মতে সরাসরি সালাম)।", "en": "Say ''Allahu Akbar''. No particular du''a is required after it (Hanafis proceed to salam)."}}, {"type": "step", "title": {"bn": "সালাম", "en": "Salam"}, "text": {"bn": "প্রথমে ডান দিকে, তারপর বাম দিকে সালাম ফেরান (হানাফি)। কিছু আলেমের মতে ডান দিকে এক সালামই যথেষ্ট।", "en": "Turn the salam to the right, then to the left (Hanafi). Some scholars hold a single salam to the right suffices."}}, {"type": "arabic", "label": {"bn": "সালাম", "en": "Salam"}, "ar": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللّٰهِ", "pron": {"bn": "আসসালামু আলাইকুম ওয়া রাহমাতুল্লাহ।", "en": "As-salamu ''alaykum wa rahmatullah."}, "meaning": {"bn": "তোমাদের ওপর শান্তি ও আল্লাহর রহমত বর্ষিত হোক।", "en": "Peace and the mercy of Allah be upon you."}}, {"type": "differ", "title": {"bn": "প্রতি তাকবিরে হাত তোলা", "en": "Raising the hands at each takbir"}, "views": [{"label": {"bn": "হানাফি ও মালেকি (প্রসিদ্ধ মত)", "en": "Hanafi and Maliki (well-known view)"}, "text": {"bn": "শুধু প্রথম তাকবিরে হাত তোলা; বাকি তিনটিতে নয়।", "en": "Raise the hands only at the first takbir."}, "evidence": {"bn": "দারাকুতনিতে ইবনে আব্বাস (রা.) থেকে এ মর্মে বর্ণনা আছে (সনদ নিয়ে আলোচনা আছে)।", "en": "A report from Ibn ''Abbas in al-Daraqutni (its chain is discussed)."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "প্রতিটি তাকবিরে হাত তোলা।", "en": "Raise the hands at every takbir."}, "evidence": {"bn": "ইবনে উমর (রা.) জানাযার প্রতিটি তাকবিরে হাত তুলতেন (সহিহ বুখারিতে অধ্যায়ের শিরোনামে উল্লেখিত)।", "en": "Ibn ''Umar raised his hands at every funeral takbir (cited in a chapter heading of Sahih al-Bukhari)."}}], "check": true}, {"type": "heading", "text": {"bn": "দেরিতে এলে (মাসবুক)", "en": "If you join late"}}, {"type": "text", "text": {"bn": "ইমাম কয়েক তাকবির দিয়ে ফেললে, হানাফি মতে পরবর্তী তাকবিরের জন্য অপেক্ষা করুন এবং ইমামের সাথে তাকবির বলে যোগ দিন। ইমাম সালাম ফেরালে লাশ তুলে নেওয়ার আগেই ছুটে যাওয়া তাকবিরগুলো দোয়া ছাড়া দ্রুত বলে সালাম ফেরান।", "en": "If the imam has already made some takbirs, Hanafis wait for his next takbir and join with it. After the imam''s salam, say the missed takbirs quickly (without the du''as) before the body is lifted, then give salam."}}, {"type": "differ", "title": {"bn": "গায়েবানা জানাযা (লাশ অনুপস্থিত থাকলে)", "en": "Funeral prayer in absentia"}, "views": [{"label": {"bn": "হানাফি ও মালেকি", "en": "Hanafi and Maliki"}, "text": {"bn": "গায়েবানা জানাযা জায়েজ নয়; নাজাশির ঘটনা বিশেষ ক্ষেত্র ছিল।", "en": "Not prescribed; the Negus''s case was special."}, "evidence": {"bn": "নবীজি (সা.)-এর যুগে অনেক সাহাবি দূরে ইন্তেকাল করেছেন, কিন্তু সবার গায়েবানা জানাযা পড়ার বর্ণনা নেই।", "en": "Many Companions died far away in the Prophet''s time, with no report of absentee prayers for them all."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "জায়েজ।", "en": "Permissible."}, "evidence": {"bn": "নবীজি (সা.) মদিনায় থেকে নাজাশির গায়েবানা জানাযা পড়েছেন (সহিহ বুখারি ১২৪৫)।", "en": "The Prophet prayed in Madinah over the Negus who died in Abyssinia (Sahih al-Bukhari 1245)."}}, {"label": {"bn": "কিছু আলেম (যেমন ইবনে তাইমিয়া)", "en": "Some scholars (e.g. Ibn Taymiyyah)"}, "text": {"bn": "যার জানাযা কোথাও পড়া হয়নি, শুধু তার জন্য গায়েবানা জানাযা।", "en": "Only for someone over whom no funeral prayer was offered."}, "evidence": {"bn": "নাজাশির দেশে তাঁর জানাযা পড়ার মতো কেউ ছিল না বলে ধারণা করা হয়।", "en": "It is understood that no one in his land prayed over the Negus."}}]}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '123642e3-dcfe-5d13-bfea-c89db101e991', id, 'janazah-carrying-burial', '{"bn": "লাশ বহন ও দাফন", "en": "Carrying and Burial"}', '{"bn": "খাটিয়া বহনের আদব, কবরের ধরন, কবরে রাখার দোয়া, মাটি দেওয়া ও দাফনের পর দোয়া।", "en": "Etiquette of carrying the bier, the grave, the du''a when placing the body, soil, and du''a after burial."}', 'basic', '[{"type": "heading", "text": {"bn": "খাটিয়া বহন", "en": "Carrying the bier"}}, {"type": "list", "items": [{"bn": "দ্রুত পায়ে (দৌড়ে নয়) লাশ নিয়ে যাওয়া সুন্নত (সহিহ বুখারি ১৩১৫)।", "en": "Carry it at a brisk pace, not running (Sahih al-Bukhari 1315)."}, {"bn": "চারজনে খাটিয়ার চার পায়া ধরা এবং পালাক্রমে কাঁধ দেওয়া উত্তম; মাথা সামনের দিকে থাকবে।", "en": "Four people take the four handles and take turns; the head goes in front."}, {"bn": "জানাযার সাথে যারা যাবেন, লাশ মাটিতে রাখার আগে বসবেন না (সহিহ বুখারি ১৩১০)।", "en": "Those following should not sit until the bier is put down (Sahih al-Bukhari 1310)."}, {"bn": "চুপচাপ চলা ও মৃত্যুর কথা ভাবা উত্তম; জোরে জিকির, কালিমা বা স্লোগান দিতে দিতে চলাকে হানাফিসহ অনেক আলেম মাকরুহ বলেছেন।", "en": "Walk quietly reflecting on death; many scholars including Hanafis disliked loud dhikr or chanting while walking."}, {"bn": "নারীদের জন্য জানাযার সাথে কবরস্থানে যাওয়া নিরুৎসাহিত।", "en": "Women are discouraged from following the bier to the graveyard."}]}, {"type": "heading", "text": {"bn": "কবর", "en": "The grave"}}, {"type": "text", "text": {"bn": "কবর যথেষ্ট গভীর হবে, যাতে গন্ধ বের না হয় এবং পশুপাখি ক্ষতি করতে না পারে। লাহদ (কবরের কিবলার দিকের দেয়ালে খোঁড়া খাঁজ) উত্তম; সা''দ (রা.) ওসিয়ত করেছিলেন, তাঁর জন্য লাহদ করা হোক, যেমন নবীজি (সা.)-এর জন্য করা হয়েছিল (সহিহ মুসলিম ৯৬৬)। মাটি নরম হলে (বাংলাদেশের অনেক জায়গায়) মাঝখানে খাদ করা ‘শাক’ কবর করা হয়, যা জায়েজ।", "en": "The grave should be deep enough to contain smell and protect from animals. The lahd (a niche in the qiblah-side wall) is best; Sa''d asked for a lahd as was made for the Prophet (Sahih Muslim 966). In soft soil (as in much of Bangladesh) a shaqq (trench in the middle) is used, which is permissible."}}, {"type": "heading", "text": {"bn": "কবরে রাখা", "en": "Placing in the grave"}}, {"type": "step", "title": {"bn": "কবরে নামানো", "en": "Lower the body"}, "text": {"bn": "সম্ভব হলে কিবলার দিক থেকে লাশ কবরে নামান। মাহরাম ও নিকটজনরা নামাবেন; নারীর লাশ নামানোর সময় চাদর দিয়ে আড়াল করা উত্তম।", "en": "Lower the body, from the qiblah side if possible. Close relatives do this; for a woman, screen the grave with a sheet."}}, {"type": "step", "title": {"bn": "দোয়া পড়া", "en": "Say the du''a"}, "text": {"bn": "কবরে রাখার সময় নিচের দোয়া পড়ুন।", "en": "Say the du''a below while placing the body."}}, {"type": "arabic", "label": {"bn": "কবরে রাখার দোয়া", "en": "Du''a when placing in the grave"}, "ar": "بِسْمِ اللّٰهِ وَعَلَىٰ سُنَّةِ رَسُولِ اللّٰهِ", "pron": {"bn": "বিসমিল্লাহি ওয়া আলা সুন্নাতি রাসূলিল্লাহ।", "en": "Bismillahi wa ''ala sunnati Rasulillah."}, "meaning": {"bn": "আল্লাহর নামে এবং আল্লাহর রাসুলের সুন্নাতের ওপর (তোমাকে রাখছি)।", "en": "In the name of Allah and upon the sunnah of the Messenger of Allah."}, "ref": {"bn": "সুনান আবু দাউদ ৩২১৩", "en": "Sunan Abi Dawud 3213"}}, {"type": "arabic", "label": {"bn": "আরেকটি বর্ণনা", "en": "Another narration"}, "ar": "بِسْمِ اللّٰهِ وَبِاللّٰهِ وَعَلَىٰ مِلَّةِ رَسُولِ اللّٰهِ", "pron": {"bn": "বিসমিল্লাহি ওয়া বিল্লাহি ওয়া আলা মিল্লাতি রাসূলিল্লাহ।", "en": "Bismillahi wa billahi wa ''ala millati Rasulillah."}, "meaning": {"bn": "আল্লাহর নামে, আল্লাহর সাহায্যে এবং আল্লাহর রাসুলের মিল্লাতের (দ্বীনের) ওপর।", "en": "In the name of Allah, by Allah, and upon the religion of the Messenger of Allah."}, "ref": {"bn": "জামে তিরমিজি ১০৪৬", "en": "Jami'' al-Tirmidhi 1046"}}, {"type": "step", "title": {"bn": "কিবলামুখী করে শোয়ানো", "en": "Lay facing the qiblah"}, "text": {"bn": "লাশকে ডান কাতে কিবলামুখী করে শুইয়ে দিন; পিঠের দিকে মাটি বা ইট দিয়ে ঠেস দিন। কাফনের বাঁধনগুলো খুলে দিন।", "en": "Lay the body on its right side facing the qiblah, supported at the back with earth or bricks. Untie the knots of the shroud."}}, {"type": "step", "title": {"bn": "বাঁশ বা তক্তা দিয়ে ঢাকা", "en": "Cover with planks"}, "text": {"bn": "লাহদ বা শাকের মুখ কাঁচা ইট, বাঁশ বা তক্তা দিয়ে বন্ধ করে দিন, যাতে মাটি সরাসরি লাশের ওপর না পড়ে।", "en": "Close the lahd or shaqq with mud bricks, bamboo or planks so soil does not fall directly on the body."}}, {"type": "step", "title": {"bn": "তিন মুঠ মাটি", "en": "Three handfuls of soil"}, "text": {"bn": "উপস্থিতরা মাথার দিক থেকে দুই হাতে তিন মুঠ করে মাটি দেবেন। নবীজি (সা.) এক জানাযার পর কবরের মাথার দিক থেকে তিন মুঠ মাটি দিয়েছিলেন (সুনান ইবনে মাজাহ ১৫৬৫)।", "en": "Those present throw three handfuls of soil from the head side. The Prophet threw three handfuls at the head of a grave (Sunan Ibn Majah 1565)."}}, {"type": "arabic", "label": {"bn": "কুরআনের আয়াত", "en": "Quranic verse"}, "ar": "مِنْهَا خَلَقْنَاكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً أُخْرَىٰ", "pron": {"bn": "মিনহা খালাকনাকুম, ওয়া ফীহা নুঈদুকুম, ওয়া মিনহা নুখরিজুকুম তারাতান উখরা।", "en": "Minha khalaqnakum, wa fiha nu''idukum, wa minha nukhrijukum taratan ukhra."}, "meaning": {"bn": "এ (মাটি) থেকেই আমি তোমাদের সৃষ্টি করেছি, এতেই তোমাদের ফিরিয়ে দেব এবং এ থেকেই তোমাদের আবার বের করব।", "en": "From it (the earth) We created you, into it We return you, and from it We will bring you out once again."}, "ref": {"bn": "সূরা ত্বহা ২০:৫৫", "en": "Ta-Ha 20:55"}}, {"type": "note", "tone": "info", "text": {"bn": "তিন মুঠ মাটি দেওয়ার সময় এই আয়াতের তিন অংশ পড়ার প্রচলন আছে; এ বিষয়ে মুসনাদে আহমাদে একটি বর্ণনা আছে, যার সনদ দুর্বল বলে মুহাদ্দিসরা উল্লেখ করেছেন। আয়াতটি পড়া যায়, তবে জরুরি মনে করবেন না।", "en": "Reciting the three parts of this verse with the three handfuls is common; a narration in Musnad Ahmad mentions it but its chain is graded weak. You may recite it, but do not treat it as required."}, "check": true}, {"type": "step", "title": {"bn": "কবর উঁচু করা", "en": "Raise the mound"}, "text": {"bn": "কবর মাটি দিয়ে ভরে প্রায় এক বিঘত উঁচু ও উটের কুঁজের মতো করে দিন; পানি ছিটিয়ে দেওয়া যায়।", "en": "Fill the grave and raise it about a hand-span in a hump shape; it may be sprinkled with water."}}, {"type": "heading", "text": {"bn": "দাফনের পর", "en": "After burial"}}, {"type": "text", "text": {"bn": "দাফন শেষ হলে নবীজি (সা.) কবরের পাশে দাঁড়িয়ে বলতেন: ‘তোমাদের ভাইয়ের জন্য ক্ষমা চাও এবং তার জন্য দৃঢ়তা চাও, কারণ এখন তাকে প্রশ্ন করা হচ্ছে’ (সুনান আবু দাউদ ৩২২১)।", "en": "After burial the Prophet would stand at the grave and say: ''Seek forgiveness for your brother and ask for him firmness, for he is now being questioned'' (Sunan Abi Dawud 3221)."}}, {"type": "arabic", "label": {"bn": "দাফনের পর দোয়ার উদাহরণ (নারীর জন্য: লাহা / সাব্বিতহা)", "en": "Example du''a after burial (for a woman: laha / thabbitha)"}, "ar": "اللّٰهُمَّ اغْفِرْ لَهُ، اللّٰهُمَّ ثَبِّتْهُ", "pron": {"bn": "আল্লাহুম্মাগফির লাহূ, আল্লাহুম্মা সাব্বিতহু।", "en": "Allahummaghfir lahu, Allahumma thabbithu."}, "meaning": {"bn": "হে আল্লাহ, তাকে ক্ষমা করো; হে আল্লাহ, তাকে (প্রশ্নের উত্তরে) দৃঢ় রাখো।", "en": "O Allah, forgive him; O Allah, make him firm."}, "ref": {"bn": "সুনান আবু দাউদ ৩২২১-এর নির্দেশনা অনুযায়ী", "en": "Following the instruction in Sunan Abi Dawud 3221"}}, {"type": "list", "items": [{"bn": "প্রত্যেকে নিজে নিজে দোয়া করবেন; কিছুক্ষণ কবরের কাছে থেকে দোয়া করা ভালো।", "en": "Each person makes du''a individually; staying a little while at the grave is good."}, {"bn": "কবর পাকা করা, তার ওপর ঘর বা স্থাপনা বানানো ও কবরের ওপর বসা নিষেধ (সহিহ মুসলিম ৯৭০)।", "en": "Plastering graves, building over them and sitting on them is forbidden (Sahih Muslim 970)."}, {"bn": "চেনার জন্য মাথার দিকে একটি পাথর বা চিহ্ন রাখা যায়।", "en": "A stone or marker may be placed at the head for recognition."}]}, {"type": "note", "tone": "info", "text": {"bn": "দাফনের পর মৃতকে সম্বোধন করে তালকিন করা (যেমন ‘হে অমুক, বলো তোমার রব আল্লাহ...’) নিয়ে আলেমদের মতভেদ আছে: কিছু শাফেয়ি ও হাম্বলি আলেম একে মুস্তাহাব বলেছেন; অন্যরা বলেছেন এর হাদিস দুর্বল, তাই করা হবে না। এর বদলে ক্ষমা ও দৃঢ়তার দোয়া সহিহ হাদিসে প্রমাণিত।", "en": "Addressing the deceased with talqin after burial (''O so-and-so, say your Lord is Allah...'') is disputed: some Shafi''i and Hanbali scholars recommended it; others say its hadith is weak and it should not be done. Du''a for forgiveness and firmness is established in sahih hadith."}}]', 'in_review', 60 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'c07be002-1b3c-525a-82c0-af6c95c656e7', id, 'janazah-visiting-graves', '{"bn": "কবর জিয়ারত", "en": "Visiting Graves"}', '{"bn": "কবর জিয়ারতের উদ্দেশ্য, সুন্নত দোয়া, নারীদের জিয়ারত নিয়ে মত, মৃতের কাছে কী পৌঁছে এবং যা থেকে বিরত থাকতে হবে।", "en": "The purpose of visiting graves, the sunnah greeting, views on women visiting, what benefits the dead, and what to avoid."}', 'basic', '[{"type": "text", "text": {"bn": "নবীজি (সা.) বলেছেন: ‘আমি তোমাদের কবর জিয়ারত করতে নিষেধ করেছিলাম; এখন জিয়ারত করো’ (সহিহ মুসলিম ৯৭৭), ‘কারণ তা আখেরাতের কথা মনে করিয়ে দেয়’ (জামে তিরমিজি ১০৫৪)। জিয়ারতের উদ্দেশ্য দুটি: নিজের মৃত্যু ও আখেরাত স্মরণ করা, এবং মৃতদের জন্য দোয়া করা।", "en": "The Prophet said: ''I had forbidden you from visiting graves; now visit them'' (Sahih Muslim 977), ''for it reminds of the Hereafter'' (Jami'' al-Tirmidhi 1054). The purposes are to remember death and the Hereafter, and to pray for the dead."}}, {"type": "arabic", "label": {"bn": "কবর জিয়ারতের দোয়া", "en": "Du''a when visiting graves"}, "ar": "السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللّٰهُ لَلَاحِقُونَ، أَسْأَلُ اللّٰهَ لَنَا وَلَكُمُ الْعَافِيَةَ", "pron": {"bn": "আসসালামু আলাইকুম আহলাদ দিয়ারি মিনাল মু''মিনীনা ওয়াল মুসলিমীন, ওয়া ইন্না ইনশাআল্লাহু লালাহিকূন, আসআলুল্লাহা লানা ওয়া লাকুমুল আফিয়াহ।", "en": "As-salamu ''alaykum ahlad-diyari minal-mu''minina wal-muslimin, wa inna in sha'' Allahu lalahiqun, as''alullaha lana wa lakumul-''afiyah."}, "meaning": {"bn": "হে এই ঘরগুলোর মুমিন ও মুসলিম বাসিন্দারা, তোমাদের ওপর শান্তি বর্ষিত হোক। আল্লাহ চাইলে আমরাও তোমাদের সাথে মিলিত হব। আমি আমাদের ও তোমাদের জন্য আল্লাহর কাছে নিরাপত্তা চাই।", "en": "Peace be upon you, O believing and Muslim dwellers of these abodes. We shall, if Allah wills, join you. I ask Allah for well-being for us and for you."}, "ref": {"bn": "সহিহ মুসলিম ৯৭৫", "en": "Sahih Muslim 975"}}, {"type": "arabic", "label": {"bn": "আরেকটি দোয়া (আয়েশা রা.-এর বর্ণনা)", "en": "Another du''a (narrated by ''A''ishah)"}, "ar": "السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ، وَأَتَاكُمْ مَا تُوعَدُونَ، غَدًا مُؤَجَّلُونَ، وَإِنَّا إِنْ شَاءَ اللّٰهُ بِكُمْ لَاحِقُونَ", "pron": {"bn": "আসসালামু আলাইকুম দারা কাওমিম মু''মিনীন, ওয়া আতাকুম মা তূআদূন, গাদাম মুআজ্জালূন, ওয়া ইন্না ইনশাআল্লাহু বিকুম লাহিকূন।", "en": "As-salamu ''alaykum dara qawmin mu''minin, wa atakum ma tu''adun, ghadan mu''ajjalun, wa inna in sha'' Allahu bikum lahiqun."}, "meaning": {"bn": "হে মুমিন সম্প্রদায়ের আবাসের বাসিন্দারা, তোমাদের ওপর শান্তি। তোমাদের যে প্রতিশ্রুতি দেওয়া হয়েছিল তা তোমাদের কাছে এসেছে, আগামীর জন্য তোমাদের অবকাশ দেওয়া হয়েছে; আর আল্লাহ চাইলে আমরাও তোমাদের সাথে মিলিত হব।", "en": "Peace be upon you, abode of believing people. What you were promised has come to you, deferred until tomorrow, and we shall, if Allah wills, join you."}, "ref": {"bn": "সহিহ মুসলিম ৯৭৪", "en": "Sahih Muslim 974"}}, {"type": "heading", "text": {"bn": "জিয়ারতের আদব", "en": "Etiquette"}}, {"type": "list", "items": [{"bn": "কবরের দিকে মুখ করে সালাম দিন; দোয়ার সময় কিবলামুখী হওয়া উত্তম।", "en": "Face the grave when greeting; face the qiblah for du''a."}, {"bn": "হাত তুলে দোয়া করা যায়; আয়েশা (রা.) বলেন, নবীজি (সা.) বাকি কবরস্থানে গিয়ে দাঁড়িয়ে তিনবার হাত তুলে দোয়া করেছেন (সহিহ মুসলিম ৯৭৪)।", "en": "You may raise your hands in du''a; the Prophet raised his hands three times at al-Baqi'' (Sahih Muslim 974)."}, {"bn": "কবরের ওপর বসবেন না, কবরের দিকে ফিরে নামাজ পড়বেন না (সহিহ মুসলিম ৯৭২)।", "en": "Do not sit on graves or pray facing them (Sahih Muslim 972)."}, {"bn": "কবরে হাঁটবেন না; কবরের মাঝ দিয়ে সাবধানে চলুন।", "en": "Do not walk on graves; move carefully between them."}]}, {"type": "note", "tone": "warn", "text": {"bn": "কবরে সিজদা করা, কবর তাওয়াফ করা, কবরবাসীর কাছে সন্তান, রোগমুক্তি বা প্রয়োজন চাওয়া, কবরে মানত করা: এগুলো ইবাদত, যা কেবল আল্লাহর জন্য। এসব থেকে কঠোরভাবে বিরত থাকুন। দোয়া চাইবেন আল্লাহর কাছে, মৃতের জন্য।", "en": "Prostrating to graves, circling them, asking the dead for children, cures or needs, or making vows to them are acts of worship due to Allah alone; avoid them strictly. Ask Allah, for the dead."}}, {"type": "differ", "title": {"bn": "নারীদের কবর জিয়ারত", "en": "Women visiting graves"}, "views": [{"label": {"bn": "জায়েজ, শর্তসাপেক্ষে (অনেক হানাফি ও অন্য আলেম)", "en": "Permissible with conditions (many Hanafi and other scholars)"}, "text": {"bn": "পর্দা রক্ষা করে, বিলাপ ও উচ্চস্বরে কান্না ছাড়া মাঝে মাঝে জিয়ারত করা যায়।", "en": "Occasionally, with proper covering and without wailing."}, "evidence": {"bn": "নবীজি (সা.) আয়েশা (রা.)-কে কবর জিয়ারতের দোয়া শিখিয়েছেন (সহিহ মুসলিম ৯৭৪); কবরের পাশে কাঁদতে থাকা এক নারীকে নবীজি (সা.) ধৈর্য ধরতে বলেছেন, জিয়ারত থেকে নিষেধ করেননি (সহিহ বুখারি ১২৫২)।", "en": "The Prophet taught ''A''ishah the du''a for visiting graves (Sahih Muslim 974), and told a woman weeping at a grave to be patient without forbidding the visit (Sahih al-Bukhari 1252)."}}, {"label": {"bn": "মাকরুহ বা নিষেধ (কিছু আলেম)", "en": "Disliked or forbidden (some scholars)"}, "text": {"bn": "নারীদের কবর জিয়ারত মাকরুহ, বিশেষ করে ঘন ঘন যাওয়া।", "en": "Disliked, especially frequent visits."}, "evidence": {"bn": "‘নবীজি (সা.) অধিক কবর জিয়ারতকারী নারীদের অভিশাপ দিয়েছেন’ (জামে তিরমিজি ১০৫৬)।", "en": "''The Messenger of Allah cursed women who frequently visit graves'' (Jami'' al-Tirmidhi 1056)."}}]}, {"type": "heading", "text": {"bn": "মৃতের জন্য কী উপকারে আসে", "en": "What benefits the dead"}}, {"type": "text", "text": {"bn": "মৃত্যুর পর মানুষের আমল বন্ধ হয়ে যায়, তিনটি ছাড়া: চলমান সদকা, উপকারী জ্ঞান এবং নেক সন্তান যে তার জন্য দোয়া করে (সহিহ মুসলিম ১৬৩১)।", "en": "When a person dies his deeds end except three: ongoing charity, beneficial knowledge, and a righteous child who prays for him (Sahih Muslim 1631)."}}, {"type": "list", "items": [{"bn": "দোয়া ও ইস্তিগফার: সর্বসম্মতভাবে পৌঁছে (সূরা হাশর ৫৯:১০)।", "en": "Du''a and istighfar: agreed to reach (Al-Hashr 59:10)."}, {"bn": "সদকা: মৃত মায়ের পক্ষ থেকে সদকা করলে সওয়াব পাবেন কি না জিজ্ঞেস করলে নবীজি (সা.) বললেন, হ্যাঁ (সহিহ বুখারি ১৩৮৮)।", "en": "Charity: asked about giving charity for a deceased mother, the Prophet said yes (Sahih al-Bukhari 1388)."}, {"bn": "মৃতের ঋণ পরিশোধ, তার পক্ষ থেকে বদলি হজ এবং মানতের/কাজা রোজা (সহিহ বুখারি ১৯৫২, ১৯৫৩)।", "en": "Paying the deceased''s debts, Hajj on their behalf, and owed fasts (Sahih al-Bukhari 1952, 1953)."}]}, {"type": "differ", "title": {"bn": "কুরআন তিলাওয়াতের সওয়াব মৃতের কাছে পৌঁছে কি", "en": "Does the reward of Quran recitation reach the dead"}, "views": [{"label": {"bn": "হানাফি ও হাম্বলি", "en": "Hanafi and Hanbali"}, "text": {"bn": "হ্যাঁ, কেউ কুরআন পড়ে বা নফল ইবাদত করে সওয়াব মৃতকে দান করলে তা পৌঁছে।", "en": "Yes, the reward of recitation and voluntary worship gifted to the dead reaches them."}, "evidence": {"bn": "সদকা, হজ ও রোজার সওয়াব পৌঁছানোর সহিহ হাদিসগুলোর ওপর কিয়াস (সহিহ বুখারি ১৩৮৮, ১৯৫২)।", "en": "By analogy with the sahih hadiths on charity, Hajj and fasting (Sahih al-Bukhari 1388, 1952)."}}, {"label": {"bn": "শাফেয়ি (প্রসিদ্ধ পুরনো মত) ও মালেকি", "en": "Shafi''i (well-known classical view) and Maliki"}, "text": {"bn": "তিলাওয়াতের সওয়াব সরাসরি পৌঁছে না; তবে তিলাওয়াতের পর মৃতের জন্য দোয়া করলে দোয়ার মাধ্যমে উপকার পৌঁছে (পরবর্তী অনেক শাফেয়ি আলেম এভাবে বলেছেন)।", "en": "The reward of recitation does not reach directly, but du''a for the dead after reciting benefits them (as many later Shafi''is put it)."}, "evidence": {"bn": "‘মানুষ তা-ই পায়, যার জন্য সে চেষ্টা করে’ (সূরা নাজম ৫৩:৩৯); হাদিসে কেবল নির্দিষ্ট কিছু আমলের কথা এসেছে।", "en": "''Man will have only what he strives for'' (An-Najm 53:39); hadiths name only specific deeds."}}]}]', 'in_review', 70 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'fa405e7c-d96e-546c-9d0c-12088bb9ebe4', id, 'janazah-condolence', '{"bn": "শোকাহত পরিবারকে সান্ত্বনা (তা''জিয়াহ)", "en": "Condolence (Ta''ziyah)"}', '{"bn": "শোকাহত পরিবারকে সান্ত্বনা দেওয়ার সুন্নত, কী বলবেন, খাবার পাঠানো এবং শোক পালনের সময়সীমা।", "en": "Comforting the bereaved: what to say, sending food, and the period of mourning."}', 'basic', '[{"type": "text", "text": {"bn": "মৃতের পরিবারকে সান্ত্বনা দেওয়া সুন্নত। তাদের ধৈর্য ধরতে উৎসাহ দিন, মৃতের জন্য দোয়া করুন, এবং বাস্তব সাহায্য করুন। সাধারণত দাফনের আগে-পরে তিন দিনের মধ্যে তা''জিয়াহ করা হয়; দূরে থাকলে পরেও করা যায়।", "en": "Comforting the family is sunnah: encourage patience, pray for the deceased, and help practically. It is usually within three days; someone far away may do it later."}}, {"type": "arabic", "label": {"bn": "সান্ত্বনার দোয়া (নবীজি সা. তাঁর কন্যাকে বলে পাঠিয়েছিলেন)", "en": "Words of condolence (the Prophet''s message to his daughter)"}, "ar": "إِنَّ لِلّٰهِ مَا أَخَذَ، وَلَهُ مَا أَعْطَىٰ، وَكُلٌّ عِنْدَهُ بِأَجَلٍ مُسَمًّى، فَلْتَصْبِرْ وَلْتَحْتَسِبْ", "pron": {"bn": "ইন্না লিল্লাহি মা আখাযা, ওয়া লাহূ মা আ''তা, ওয়া কুল্লুন ইনদাহূ বিআজালিম মুসাম্মা, ফালতাসবির ওয়ালতাহতাসিব।", "en": "Inna lillahi ma akhadha, wa lahu ma a''ta, wa kullun ''indahu bi-ajalin musamma, faltasbir waltahtasib."}, "meaning": {"bn": "আল্লাহ যা নিয়েছেন তা তাঁরই, আর যা দিয়েছেন তাও তাঁরই; তাঁর কাছে প্রত্যেক কিছুর নির্দিষ্ট মেয়াদ আছে। অতএব (তুমি) ধৈর্য ধরো এবং সওয়াবের আশা রাখো।", "en": "To Allah belongs what He took and what He gave, and everything with Him has an appointed term; so be patient and hope for reward."}, "ref": {"bn": "সহিহ বুখারি ১২৮৪", "en": "Sahih al-Bukhari 1284"}}, {"type": "note", "tone": "info", "text": {"bn": "হাদিসে শেষ অংশ ‘ফালতাসবির ওয়ালতাহতাসিব’ স্ত্রীলিঙ্গে, কারণ তা কন্যাকে বলা হয়েছিল। পুরুষকে বলতে পারেন ‘ফাসবির ওয়াহতাসিব’ (فَاصْبِرْ وَاحْتَسِبْ)। নিজের ভাষায় সান্ত্বনা দেওয়াও সুন্নত আদায় করে।", "en": "The last phrase is feminine, as it was said to his daughter. To a man say ''fasbir wahtasib'' (فَاصْبِرْ وَاحْتَسِبْ). Comforting in your own words also fulfils the sunnah."}}, {"type": "heading", "text": {"bn": "যা করবেন", "en": "What to do"}}, {"type": "list", "items": [{"bn": "মৃতের পরিবারের জন্য খাবার পাঠানো: জা''ফর (রা.)-এর শাহাদাতের খবর এলে নবীজি (সা.) বললেন, জা''ফরের পরিবারের জন্য খাবার তৈরি করো, কারণ তাদের ওপর এমন বিপদ এসেছে যা তাদের ব্যস্ত রেখেছে (সুনান আবু দাউদ ৩১৩২; জামে তিরমিজি ৯৯৮)।", "en": "Send food to the family: when news of Ja''far''s death came, the Prophet said, ''Prepare food for Ja''far''s family, for what has befallen them keeps them busy'' (Sunan Abi Dawud 3132; Jami'' al-Tirmidhi 998)."}, {"bn": "সংক্ষিপ্ত ও কোমল কথা বলুন; মৃতের ভালো দিকগুলো স্মরণ করুন।", "en": "Keep your words brief and gentle; mention the deceased''s good qualities."}, {"bn": "মৃতের ঋণ, সন্তানদের দেখাশোনা বা প্রয়োজনীয় কাজে সাহায্যের প্রস্তাব দিন।", "en": "Offer help with debts, children or practical tasks."}]}, {"type": "heading", "text": {"bn": "যা এড়িয়ে চলবেন", "en": "What to avoid"}}, {"type": "list", "items": [{"bn": "শোকাহত পরিবারকে মেহমানদারি ও বড় খাবারের আয়োজন করতে বাধ্য করা। জারির (রা.) বলেন, আমরা মৃতের পরিবারের কাছে সমবেত হওয়া ও তাদের খাবার তৈরি করাকে বিলাপের অংশ মনে করতাম (সুনান ইবনে মাজাহ ১৬১২)।", "en": "Burdening the bereaved with hosting and big meals. Jarir said: we considered gathering at the family of the deceased and their preparing food to be part of wailing (Sunan Ibn Majah 1612)."}, {"bn": "‘তার সময় হয়নি’, ‘কেন এমন হলো’ ধরনের অভিযোগের কথা বা তাকদিরের বিরুদ্ধে কথা।", "en": "Complaints against fate such as ''why did this happen''."}, {"bn": "দীর্ঘ সময় বসে থেকে পরিবারকে ক্লান্ত করা।", "en": "Sitting for long and tiring the family."}]}, {"type": "note", "tone": "info", "text": {"bn": "সুনান ইবনে মাজাহ ১৬১২-এর বর্ণনার সনদ নিয়ে মুহাদ্দিসদের মতভেদ আছে (কেউ সহিহ, কেউ দুর্বল বলেছেন)।", "en": "Scholars differ on the chain of the Sunan Ibn Majah 1612 report (some graded it sahih, others weak)."}}, {"type": "heading", "text": {"bn": "শোক পালনের সময়সীমা", "en": "Period of mourning"}}, {"type": "text", "text": {"bn": "কোনো আত্মীয়ের মৃত্যুতে তিন দিনের বেশি শোক পালন (সাজসজ্জা বর্জন ইত্যাদি) জায়েজ নয়; তবে স্ত্রী তার স্বামীর মৃত্যুতে চার মাস দশ দিন শোক পালন করবেন (সহিহ বুখারি ১২৮১)।", "en": "Mourning (giving up adornment, etc.) for any relative is not allowed beyond three days, except a wife for her husband: four months and ten days (Sahih al-Bukhari 1281)."}}]', 'in_review', 80 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'b9a5d864-8cb9-5738-84d5-8a14bafb9de9', id, 'janazah-iddah', '{"bn": "স্বামীর মৃত্যুর পর ইদ্দত (সংক্ষেপে)", "en": "Widow''s ''Iddah (Brief)"}', '{"bn": "স্বামী মারা গেলে স্ত্রীর ইদ্দতের সময়, এ সময়ে যা করবেন ও যা বর্জন করবেন, এবং প্রচলিত ভুল ধারণা।", "en": "The widow''s waiting period: its length, what to do and avoid, and common misconceptions."}', 'basic', '[{"type": "arabic", "ar": "وَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ أَزْوَاجًا يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا", "pron": {"bn": "ওয়াল্লাযীনা ইউতাওয়াফফাওনা মিনকুম ওয়া ইয়াযারূনা আযওয়াজাই ইয়াতারাব্বাসনা বিআনফুসিহিন্না আরবাআতা আশহুরিও ওয়া আশরা।", "en": "Walladhina yutawaffawna minkum wa yadharuna azwajan yatarabbasna bi-anfusihinna arba''ata ashhurin wa ''ashra."}, "meaning": {"bn": "তোমাদের মধ্যে যারা মারা যায় এবং স্ত্রী রেখে যায়, সেই স্ত্রীরা চার মাস দশ দিন অপেক্ষা করবে।", "en": "Those of you who die leaving wives, the wives shall wait four months and ten days."}, "ref": {"bn": "সূরা বাকারা ২:২৩৪ (আয়াতের অংশ)", "en": "Al-Baqarah 2:234 (part of the verse)"}}, {"type": "table", "head": [{"bn": "অবস্থা", "en": "Situation"}, {"bn": "ইদ্দতের সময়", "en": "Length of ''iddah"}], "rows": [[{"bn": "স্বামীর মৃত্যু, স্ত্রী গর্ভবতী নন", "en": "Husband died, wife not pregnant"}, {"bn": "চার মাস দশ দিন (সূরা বাকারা ২:২৩৪)", "en": "Four months and ten days (Al-Baqarah 2:234)"}], [{"bn": "স্বামীর মৃত্যু, স্ত্রী গর্ভবতী", "en": "Husband died, wife pregnant"}, {"bn": "সন্তান প্রসব পর্যন্ত (সূরা তালাক ৬৫:৪)", "en": "Until she gives birth (At-Talaq 65:4)"}], [{"bn": "তালাক (তুলনার জন্য)", "en": "Divorce (for comparison)"}, {"bn": "তিন ঋতুস্রাব/পবিত্রতা (সূরা বাকারা ২:২২৮); ঋতুস্রাব না হলে তিন মাস (সূরা তালাক ৬৫:৪)", "en": "Three menstrual cycles (Al-Baqarah 2:228); three months if she does not menstruate (At-Talaq 65:4)"}]]}, {"type": "heading", "text": {"bn": "ইদ্দতের সময় করণীয় ও বর্জনীয়", "en": "During the ''iddah"}}, {"type": "list", "items": [{"bn": "স্বামীর ঘরে (যেখানে মৃত্যুর খবর পেয়েছেন) ইদ্দত পালন করবেন। ফুরাইআ (রা.)-কে নবীজি (সা.) ইদ্দত শেষ না হওয়া পর্যন্ত নিজের ঘরে থাকতে বলেছিলেন (সুনান আবু দাউদ ২৩০০)।", "en": "Stay in the marital home. The Prophet told Furay''ah to stay in her house until the ''iddah ended (Sunan Abi Dawud 2300)."}, {"bn": "প্রয়োজনে (যেমন জীবিকা, চিকিৎসা) দিনের বেলায় বের হওয়া যায়, রাতে নিজের ঘরে ফিরবেন।", "en": "She may go out by day for need (livelihood, treatment) and return to sleep at home."}, {"bn": "সাজসজ্জা বর্জন: সুগন্ধি, মেকআপ, মেহেদি, সুরমা (চিকিৎসা ছাড়া), অলংকার ও সাজের জন্য রঙিন জমকালো পোশাক।", "en": "Avoid adornment: perfume, make-up, henna, kohl (except as treatment), jewellery and decorative clothing."}, {"bn": "এ সময় বিয়ে করা বা বিয়ের প্রস্তাব গ্রহণ করা যাবে না; শুধু ইঙ্গিতে আগ্রহ প্রকাশ করা জায়েজ (সূরা বাকারা ২:২৩৫)।", "en": "No marriage or explicit proposal; only an indirect hint is allowed (Al-Baqarah 2:235)."}, {"bn": "গোসল, পরিচ্ছন্নতা, সাধারণ পরিষ্কার কাপড় পরা, নামাজ, কুরআন পড়া, মাহরাম ও প্রয়োজনে অন্যদের সাথে শালীনভাবে কথা বলা: সবই জায়েজ।", "en": "Bathing, cleanliness, plain clean clothes, prayer, Quran, and modest speech with mahrams and others when needed are all allowed."}]}, {"type": "note", "tone": "warn", "text": {"bn": "শুধু সাদা শাড়ি পরা বাধ্যতামূলক, চুড়ি ভাঙা, কারও সাথে কথা না বলা, চাঁদ বা আকাশ দেখা নিষেধ, ঘরের নির্দিষ্ট কোণে আটকে থাকা: এগুলো শরিয়তের বিধান নয়, সামাজিক প্রথা। শরিয়ত যা বলেছে, তা-ই পালন করুন।", "en": "Being required to wear only a white sari, breaking bangles, not speaking to anyone, not looking at the moon or sky, or being confined to a corner are customs, not Shari''ah rulings. Follow what the Shari''ah requires."}}, {"type": "note", "tone": "info", "text": {"bn": "ইদ্দত, উত্তরাধিকার ও তালাকের বিস্তারিত বিধান জটিল; নিজের অবস্থার জন্য একজন নির্ভরযোগ্য আলেমের পরামর্শ নিন।", "en": "The detailed rulings of ''iddah, inheritance and divorce are complex; consult a reliable scholar for your situation."}}]', 'in_review', 90 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '5350984c-399a-54eb-8606-c0bd43ee27a7', id, 'janazah-customs-to-avoid', '{"bn": "মৃত্যু ও জানাযাকেন্দ্রিক প্রচলিত রীতি: সতর্কতা", "en": "Funeral Customs: What Scholars Caution Against"}', '{"bn": "মৃত্যুকে কেন্দ্র করে সমাজে প্রচলিত কিছু রীতি, যেগুলো কুরআন-সুন্নাহয় প্রমাণিত নয় বলে আলেমরা সতর্ক করেছেন; সংযত ও নিরপেক্ষভাবে।", "en": "Some common customs around death that scholars caution have no basis in the Quran and sunnah, stated carefully and neutrally."}', 'detail', '[{"type": "arabic", "ar": "مَنْ أَحْدَثَ فِي أَمْرِنَا هٰذَا مَا لَيْسَ فِيهِ فَهُوَ رَدٌّ", "pron": {"bn": "মান আহদাসা ফী আমরিনা হাযা মা লাইসা ফীহি ফাহুয়া রাদ্দ।", "en": "Man ahdatha fi amrina hadha ma laysa fihi fahuwa radd."}, "meaning": {"bn": "যে আমাদের এই দ্বীনে এমন কিছু নতুন সংযোজন করে যা এর অংশ নয়, তা প্রত্যাখ্যাত।", "en": "Whoever introduces into this matter of ours something that is not part of it, it is rejected."}, "ref": {"bn": "সহিহ বুখারি ২৬৯৭", "en": "Sahih al-Bukhari 2697"}}, {"type": "text", "text": {"bn": "নিচের বিষয়গুলো সমাজে প্রচলিত, কিন্তু কুরআন-সুন্নাহ বা সাহাবিদের আমলে এগুলোর প্রমাণ নেই বলে বিভিন্ন মাজহাবের বহু আলেম সতর্ক করেছেন। উদ্দেশ্য কাউকে দোষারোপ করা নয়; মৃতের জন্য যা সত্যিই উপকারী (দোয়া, সদকা, ঋণ পরিশোধ), সেদিকে মনোযোগ দেওয়া। কিছু বিষয়ে আলেমদের মতভেদ আছে, তা উল্লেখ করা হলো।", "en": "The following are common, but many scholars across the schools caution that they have no basis in the Quran, sunnah or practice of the Companions. The aim is not to blame anyone but to focus on what truly benefits the dead (du''a, charity, paying debts). Where scholars differ, this is noted."}}, {"type": "heading", "text": {"bn": "যেসব বিষয়ে আলেমরা সতর্ক করেছেন", "en": "What scholars caution against"}}, {"type": "list", "items": [{"bn": "নির্দিষ্ট দিনে আয়োজন: মৃত্যুর তৃতীয় দিন (কুলখানি), চল্লিশতম দিন (চল্লিশা/চেহলাম), বার্ষিকী ইত্যাদিতে ভোজ ও মাহফিলকে দ্বীনের অংশ বা জরুরি মনে করা। সদকা ও দোয়া যেকোনো দিন করা যায়; নির্দিষ্ট দিন বেঁধে দেওয়ার প্রমাণ নেই।", "en": "Fixed-day gatherings: the 3rd day (kulkhani), 40th day (chollisha/chehlam), anniversaries, treated as religious or required. Charity and du''a can be done any day; fixing days has no evidence."}, {"bn": "মৃতের পরিবারের খরচে, বিশেষ করে এতিমের সম্পদ থেকে, বড় ভোজের আয়োজন। উত্তরাধিকারীদের মধ্যে নাবালেগ থাকলে তাদের অংশ থেকে এ খরচ করা জায়েজ নয়।", "en": "Large feasts paid by the bereaved family, especially from orphans'' shares. Spending a minor heir''s share on this is not permissible."}, {"bn": "টাকার বিনিময়ে খতম বা কুরআন পড়িয়ে মৃতের কাছে সওয়াব পাঠানো। হানাফি পরবর্তী আলেমসহ অনেকে বলেছেন, পারিশ্রমিক নিয়ে তিলাওয়াতে সওয়াব হয় না, তাই সওয়াব পৌঁছানোরও প্রশ্ন থাকে না।", "en": "Paying people to recite the Quran for the dead. Many scholars, including later Hanafis, said recitation for payment earns no reward, so there is none to pass on."}, {"bn": "জানাযার নামাজের পরপর সম্মিলিতভাবে হাত তুলে নির্দিষ্ট দোয়ার প্রথা: অনেক আলেম (উপমহাদেশের অনেক হানাফি আলেমসহ) একে সুন্নাহবিরোধী বলেছেন, কারণ জানাযা নিজেই দোয়া এবং এর পরে সম্মিলিত দোয়া প্রমাণিত নয়; কিছু আলেম অনুমতি দেন। একে জরুরি মনে না করা ও বিবাদ না করাই নিরাপদ।", "en": "A fixed collective du''a with raised hands right after the funeral prayer: many scholars (including many subcontinent Hanafis) say it is contrary to the sunnah since the prayer itself is du''a; some permit it. Safest not to treat it as required or quarrel over it."}, {"bn": "লাশ বহনের সময় উচ্চস্বরে সমবেত জিকির বা কালিমা পাঠ; সুন্নত হলো চুপচাপ চলা।", "en": "Loud collective dhikr while carrying the body; the sunnah is to walk quietly."}, {"bn": "কাফনে কালিমা বা আয়াত লেখা; কবরে আহাদনামা বা দোয়া লেখা কাগজ রাখা।", "en": "Writing the kalimah or verses on the shroud; placing written covenants or du''as in the grave."}, {"bn": "কবর পাকা করা, কবরের ওপর ঘর বা গম্বুজ নির্মাণ, কবরে বাতি বা মোমবাতি জ্বালানো, চাদর চড়ানো (সহিহ মুসলিম ৯৭০)।", "en": "Plastering graves, building over them, lighting lamps or candles, draping sheets on them (Sahih Muslim 970)."}, {"bn": "মৃতের রুহ নির্দিষ্ট রাতে (যেমন বৃহস্পতিবার রাতে) ঘরে ফিরে আসে, এমন বিশ্বাস রাখা; এর কোনো প্রমাণ নেই।", "en": "Believing the soul returns home on certain nights (e.g. Thursday night); there is no evidence for this."}, {"bn": "শোকের নামে নির্দিষ্ট দিন পর্যন্ত বাড়িতে রান্না বন্ধ রাখা, বা তিন দিনের বেশি শোক পালন (স্ত্রীর ইদ্দত ছাড়া)।", "en": "Not cooking at home for fixed days, or mourning beyond three days (other than a widow''s ''iddah)."}, {"bn": "বিলাপ, বুক চাপড়ানো, কাপড় ছেঁড়া, ভাড়া করা কান্নাকারী (সহিহ বুখারি ১২৯৪)।", "en": "Wailing, chest-beating, tearing clothes, hired mourners (Sahih al-Bukhari 1294)."}]}, {"type": "note", "tone": "info", "text": {"bn": "কবরে খেজুরের ডাল বা গাছের ডাল পোঁতা নিয়ে আলেমদের মতভেদ আছে: নবীজি (সা.) দুটি কবরে ডাল পুঁতেছিলেন (সহিহ বুখারি); কেউ কেউ একে নবীজি (সা.)-এর বিশেষ ঘটনা বলেছেন, কেউ সাধারণভাবে জায়েজ বলেছেন। ফুল দেওয়ার প্রথাকে অনেক আলেম অমুসলিমদের রীতির অনুকরণ বলে নিরুৎসাহিত করেছেন।", "en": "Scholars differ on placing palm or tree branches on graves: the Prophet placed branches on two graves (Sahih al-Bukhari); some see it as specific to him, others allow it generally. Many scholars discourage laying flowers as imitating non-Muslim customs."}, "check": true}, {"type": "heading", "text": {"bn": "যা সত্যিই উপকারে আসে", "en": "What truly helps"}}, {"type": "list", "items": [{"bn": "মৃতের ঋণ দ্রুত পরিশোধ ও ওসিয়ত পূরণ", "en": "Paying the deceased''s debts promptly and fulfilling the will"}, {"bn": "যেকোনো দিন, নিজের সামর্থ্যমতো তাদের পক্ষ থেকে সদকা, বিশেষ করে চলমান সদকা (পানির ব্যবস্থা, মসজিদ, দ্বীনি শিক্ষা)", "en": "Charity on their behalf any day, especially ongoing charity (water, mosques, religious education)"}, {"bn": "নিয়মিত তাদের জন্য দোয়া ও ইস্তিগফার", "en": "Regular du''a and istighfar for them"}, {"bn": "তাদের আত্মীয় ও বন্ধুদের সাথে সম্পর্ক রক্ষা", "en": "Keeping ties with their relatives and friends"}]}, {"type": "note", "tone": "tip", "text": {"bn": "এসব বিষয়ে পরিবারে বা সমাজে বিবাদ না করে নম্রভাবে আলোচনা করুন এবং নির্ভরযোগ্য স্থানীয় আলেমের পরামর্শ নিন।", "en": "Discuss these matters gently without quarrels in the family or community, and consult a reliable local scholar."}}]', 'in_review', 100 FROM is_guide_topics WHERE slug = 'janazah' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'e8571845-b188-5ddc-8d9b-472420ac7530', id, 'fazilat-farz-salah', '{"bn": "ফরজ নামাজ: সময়মতো ও জামাতে পড়ার ফজিলত", "en": "Obligatory prayer: praying on time and in congregation"}', '{"bn": "সময়মতো নামাজ আল্লাহর কাছে সবচেয়ে প্রিয় আমলগুলোর একটি; জামাতে, বিশেষ করে ফজর ও এশা জামাতে পড়ার রয়েছে বিরাট সওয়াব।", "en": "Praying on time is among the deeds Allah loves most, and praying in congregation, especially Fajr and Isha, carries great reward."}', 'basic', '[{"type": "text", "text": {"bn": "নামাজ ইসলামের দ্বিতীয় স্তম্ভ। আল্লাহ বলেন: “নিশ্চয়ই নামাজ মুমিনদের ওপর নির্দিষ্ট সময়ে ফরজ করা হয়েছে।” আরও বলেন: “নিশ্চয়ই নামাজ অশ্লীল ও মন্দ কাজ থেকে বিরত রাখে।”", "en": "Prayer is the second pillar of Islam. Allah says: “Indeed, prayer has been decreed upon the believers at fixed times.” And: “Indeed, prayer prohibits immorality and wrongdoing.”"}}, {"type": "ref", "text": {"bn": "সূরা নিসা ৪:১০৩; সূরা আনকাবুত ২৯:৪৫", "en": "An-Nisa 4:103; Al-''Ankabut 29:45"}}, {"type": "heading", "text": {"bn": "সময়মতো নামাজ", "en": "Praying on time"}}, {"type": "text", "text": {"bn": "আবদুল্লাহ ইবনে মাসউদ (রা.) রাসুল ﷺ-কে জিজ্ঞেস করলেন, আল্লাহর কাছে সবচেয়ে প্রিয় আমল কোনটি? তিনি বললেন: “সময়মতো নামাজ পড়া।” তারপর মা-বাবার সঙ্গে সদ্ব্যবহার, তারপর আল্লাহর পথে জিহাদ।", "en": "Ibn Mas''ud (RA) asked which deed Allah loves most. The Prophet ﷺ said: “Prayer at its proper time,” then kindness to parents, then striving in Allah''s path."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫২৭; সহিহ মুসলিম ৮৫", "en": "Sahih al-Bukhari 527; Sahih Muslim 85"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: তোমাদের কারও দরজার সামনে যদি একটি নদী থাকে আর সে দিনে পাঁচবার তাতে গোসল করে, তার শরীরে কি কোনো ময়লা থাকবে? পাঁচ ওয়াক্ত নামাজের উদাহরণও এমন; এর মাধ্যমে আল্লাহ গুনাহ মুছে দেন।", "en": "The Prophet ﷺ said: if a river ran by your door and you bathed in it five times a day, would any dirt remain? So it is with the five prayers; through them Allah wipes away sins."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫২৮; সহিহ মুসলিম ৬৬৭", "en": "Sahih al-Bukhari 528; Sahih Muslim 667"}}, {"type": "text", "text": {"bn": "পাঁচ ওয়াক্ত নামাজ, এক জুমা থেকে আরেক জুমা এবং এক রমজান থেকে আরেক রমজান মাঝখানের গুনাহগুলোর কাফফারা, যদি কবিরা গুনাহ থেকে বেঁচে থাকা হয়।", "en": "The five prayers, Friday to Friday, and Ramadan to Ramadan expiate the sins between them, as long as major sins are avoided."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৩৩", "en": "Sahih Muslim 233"}}, {"type": "text", "text": {"bn": "কিয়ামতের দিন বান্দার আমলের মধ্যে সবার আগে নামাজের হিসাব নেওয়া হবে; নামাজ ঠিক থাকলে সে সফল হবে।", "en": "The first deed a servant will be asked about on the Day of Resurrection is prayer; if it is sound, he will succeed."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ৪১৩", "en": "Jami'' at-Tirmidhi 413"}}, {"type": "heading", "text": {"bn": "জামাতে নামাজ", "en": "Praying in congregation"}}, {"type": "text", "text": {"bn": "জামাতে নামাজ একা নামাজের চেয়ে সাতাশ গুণ বেশি মর্যাদাপূর্ণ।", "en": "Prayer in congregation is twenty-seven degrees better than praying alone."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৪৫; সহিহ মুসলিম ৬৫০", "en": "Sahih al-Bukhari 645; Sahih Muslim 650"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: ভালোভাবে ওযু করে শুধু নামাজের উদ্দেশ্যে মসজিদে গেলে প্রতিটি কদমে একটি মর্যাদা বাড়ে ও একটি গুনাহ মাফ হয়, আর নামাজের অপেক্ষায় থাকা পর্যন্ত ফেরেশতারা তার জন্য দোয়া করতে থাকে।", "en": "Whoever makes wudu well and walks to the mosque only for prayer, every step raises him a degree and erases a sin, and the angels pray for him while he waits for the prayer."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৪৭", "en": "Sahih al-Bukhari 647"}}, {"type": "heading", "text": {"bn": "ফজর ও এশা জামাতে", "en": "Fajr and Isha in congregation"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: যে এশা জামাতে পড়ল, সে যেন অর্ধেক রাত নামাজ পড়ল; আর যে ফজরও জামাতে পড়ল, সে যেন সারা রাত নামাজ পড়ল।", "en": "The Prophet ﷺ said: whoever prays Isha in congregation, it is as if he prayed half the night; and whoever prays Fajr in congregation, it is as if he prayed the whole night."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৬৫৬", "en": "Sahih Muslim 656"}}, {"type": "text", "text": {"bn": "যে ফজরের নামাজ পড়ে, সে সারা দিন আল্লাহর জিম্মায় (নিরাপত্তায়) থাকে।", "en": "Whoever prays Fajr is under the protection of Allah."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৬৫৭", "en": "Sahih Muslim 657"}}, {"type": "text", "text": {"bn": "যে দুই ঠান্ডা সময়ের নামাজ (ফজর ও আসর) পড়ে, সে জান্নাতে প্রবেশ করবে।", "en": "Whoever prays the two cool prayers (Fajr and Asr) will enter Paradise."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫৭৪; সহিহ মুসলিম ৬৩৫", "en": "Sahih al-Bukhari 574; Sahih Muslim 635"}}, {"type": "note", "tone": "warn", "text": {"bn": "মুনাফিকদের জন্য ফজর ও এশার চেয়ে ভারী কোনো নামাজ নেই; তারা যদি জানত এ দুটিতে কী আছে, হামাগুড়ি দিয়ে হলেও আসত (সহিহ বুখারি ৬৫৭)।", "en": "No prayer is heavier on the hypocrites than Fajr and Isha; if they knew what is in them, they would come even crawling (Sahih al-Bukhari 657)."}}, {"type": "differ", "title": {"bn": "পুরুষদের জন্য জামাতের হুকুম", "en": "Ruling of congregation for men"}, "views": [{"label": {"bn": "হানাফি ও মালিকি", "en": "Hanafi and Maliki"}, "text": {"bn": "সুন্নতে মুয়াক্কাদা; অনেক হানাফি আলেম বলেন এটি ওয়াজিবের কাছাকাছি, বিনা ওজরে নিয়মিত ছাড়া গুনাহ।", "en": "An emphasised sunnah; many Hanafi scholars say it is close to wajib and habitually leaving it without excuse is sinful."}, "evidence": {"bn": "সাতাশ গুণ বেশি সওয়াবের হাদিস দেখায় যে একা নামাজও সহিহ, তবে জামাত অনেক উত্তম (সহিহ বুখারি ৬৪৫)।", "en": "The twenty-seven-fold hadith shows that a lone prayer is valid but congregation is far better (Sahih al-Bukhari 645)."}}, {"label": {"bn": "শাফেয়ি", "en": "Shafi''i"}, "text": {"bn": "মাযহাবের প্রসিদ্ধ মত: ফরজে কিফায়া; এলাকায় কিছু লোক আদায় করলে বাকিরা দায়মুক্ত।", "en": "The well-known view: a communal obligation; if some in the area establish it, the rest are relieved."}, "evidence": {"bn": "জামাত কায়েম রাখার নির্দেশসংবলিত হাদিসগুলো সম্প্রদায়ের ওপর দায়িত্ব হিসেবে বোঝা হয়।", "en": "Hadiths ordering congregation to be established are understood as a duty on the community."}}, {"label": {"bn": "হাম্বলি", "en": "Hanbali"}, "text": {"bn": "সক্ষম প্রত্যেক পুরুষের ওপর ওয়াজিব, তবে একা পড়লেও নামাজ আদায় হয়ে যায়।", "en": "Obligatory on every able man, though a prayer prayed alone is still valid."}, "evidence": {"bn": "যারা জামাতে আসে না তাদের ঘর পুড়িয়ে দেওয়ার ইচ্ছা প্রকাশের হাদিস (সহিহ বুখারি ৬৪৪) এবং অন্ধ সাহাবিকেও আজান শুনলে আসতে বলা (সহিহ মুসলিম ৬৫৩)।", "en": "The hadith in which the Prophet ﷺ considered burning the houses of those who stayed away (Sahih al-Bukhari 644), and his telling a blind man who heard the call to come (Sahih Muslim 653)."}}]}]', 'in_review', 10 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'f3ad43d5-e127-5c7b-a72d-8d3c7191cb79', id, 'fazilat-sunnah-salah', '{"bn": "সুন্নত নামাজ: ফজরের দুই রাকাত ও দৈনিক ১২ রাকাত", "en": "Sunnah prayers: the two before Fajr and the daily twelve"}', '{"bn": "ফজরের আগের দুই রাকাত দুনিয়ার সবকিছুর চেয়ে উত্তম, আর দৈনিক ১২ রাকাত সুন্নতের বিনিময়ে জান্নাতে ঘর।", "en": "The two rak''ahs before Fajr are better than the world, and the daily twelve sunnah rak''ahs earn a house in Paradise."}', 'basic', '[{"type": "heading", "text": {"bn": "ফজরের আগের দুই রাকাত সুন্নত", "en": "The two rak''ahs before Fajr"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: “ফজরের দুই রাকাত (সুন্নত) দুনিয়া ও তার মধ্যে যা কিছু আছে তার চেয়ে উত্তম।”", "en": "The Prophet ﷺ said: “The two rak''ahs of Fajr are better than this world and all it contains.”"}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৭২৫", "en": "Sahih Muslim 725"}}, {"type": "text", "text": {"bn": "আয়েশা (রা.) বলেন: নফল নামাজগুলোর মধ্যে রাসুল ﷺ ফজরের দুই রাকাতের প্রতি যতটা যত্নশীল ছিলেন, অন্য কোনোটির প্রতি ততটা ছিলেন না।", "en": "Aishah (RA) said the Prophet ﷺ was not more regular about any voluntary prayer than the two rak''ahs of Fajr."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১১৬৯; সহিহ মুসলিম ৭২৪", "en": "Sahih al-Bukhari 1169; Sahih Muslim 724"}}, {"type": "heading", "text": {"bn": "দৈনিক ১২ রাকাত সুন্নতে মুয়াক্কাদা", "en": "The twelve emphasised sunnah rak''ahs"}}, {"type": "text", "text": {"bn": "উম্মে হাবিবা (রা.) থেকে বর্ণিত, রাসুল ﷺ বলেছেন: যে মুসলিম বান্দা প্রতিদিন ফরজ ছাড়া বারো রাকাত নফল নামাজ পড়ে, আল্লাহ তার জন্য জান্নাতে একটি ঘর বানিয়ে দেন।", "en": "Umm Habibah (RA) reported the Prophet ﷺ said: any Muslim who prays twelve voluntary rak''ahs each day besides the obligatory, Allah builds for him a house in Paradise."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৭২৮", "en": "Sahih Muslim 728"}}, {"type": "text", "text": {"bn": "তিরমিজির বর্ণনায় এর বিবরণ এসেছে:", "en": "Tirmidhi''s narration gives the breakdown:"}}, {"type": "table", "head": [{"bn": "ওয়াক্ত", "en": "Prayer"}, {"bn": "সুন্নত রাকাত", "en": "Sunnah rak''ahs"}], "rows": [[{"bn": "ফজরের আগে", "en": "Before Fajr"}, {"bn": "২", "en": "2"}], [{"bn": "যোহরের আগে", "en": "Before Zuhr"}, {"bn": "৪", "en": "4"}], [{"bn": "যোহরের পরে", "en": "After Zuhr"}, {"bn": "২", "en": "2"}], [{"bn": "মাগরিবের পরে", "en": "After Maghrib"}, {"bn": "২", "en": "2"}], [{"bn": "এশার পরে", "en": "After Isha"}, {"bn": "২", "en": "2"}]]}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি", "en": "Jami'' at-Tirmidhi"}, "check": true}, {"type": "differ", "title": {"bn": "যোহরের আগে দুই না চার রাকাত", "en": "Two or four before Zuhr"}, "views": [{"label": {"bn": "হানাফি", "en": "Hanafi"}, "text": {"bn": "যোহরের আগে চার রাকাত সুন্নতে মুয়াক্কাদা।", "en": "Four rak''ahs before Zuhr are the emphasised sunnah."}, "evidence": {"bn": "উম্মে হাবিবা (রা.)-এর ১২ রাকাতের বিস্তারিত বর্ণনা (সুনান তিরমিজি), এবং আয়েশা (রা.) বলেছেন রাসুল ﷺ যোহরের আগে চার রাকাত ছাড়তেন না (সহিহ বুখারি)।", "en": "Umm Habibah''s detailed narration of the twelve (Tirmidhi), and Aishah''s report that he ﷺ did not leave four before Zuhr (al-Bukhari)."}}, {"label": {"bn": "শাফেয়ি ও হাম্বলি", "en": "Shafi''i and Hanbali"}, "text": {"bn": "দুই রাকাত মুয়াক্কাদা; চার রাকাত পড়া আরও উত্তম।", "en": "Two rak''ahs are emphasised; four are even better."}, "evidence": {"bn": "ইবনে উমর (রা.)-এর বর্ণনা: রাসুল ﷺ-এর কাছ থেকে দশ রাকাত মুখস্থ করেছি, যার মধ্যে যোহরের আগে দুই রাকাত (সহিহ বুখারি)।", "en": "Ibn Umar''s narration: I memorised ten rak''ahs from the Prophet ﷺ, including two before Zuhr (al-Bukhari)."}}], "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "কোনো দিন সব না পারলেও অন্তত ফজরের দুই রাকাত সুন্নত কখনো ছাড়বেন না।", "en": "Even on a busy day, never leave the two sunnah rak''ahs of Fajr."}}]', 'in_review', 20 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '4daf878d-5b34-5cdf-99bc-2e31e60062ac', id, 'fazilat-wudu', '{"bn": "ওযুর ফজিলত", "en": "Virtues of wudu"}', '{"bn": "ওযুর পানির সঙ্গে গুনাহ ঝরে যায়, কিয়ামতের দিন ওযুর অঙ্গগুলো উজ্জ্বল হবে, আর ওযুর পরের দোয়ায় জান্নাতের আট দরজা খুলে যায়।", "en": "Sins fall away with the water of wudu, its traces will shine on the Last Day, and the dua after it opens all eight gates of Paradise."}', 'basic', '[{"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: মুসলিম বান্দা ওযু করার সময় মুখ ধুলে চোখ দিয়ে করা সব গুনাহ পানির সঙ্গে (বা পানির শেষ ফোঁটার সঙ্গে) বেরিয়ে যায়; হাত ধুলে হাত দিয়ে করা গুনাহ বেরিয়ে যায়; পা ধুলে পা দিয়ে করা গুনাহ বেরিয়ে যায়, শেষে সে গুনাহ থেকে পরিচ্ছন্ন হয়ে যায়।", "en": "The Prophet ﷺ said: when a Muslim washes his face in wudu, every sin his eyes committed leaves with the water; when he washes his hands, the sins of his hands leave; when he washes his feet, the sins his feet walked to leave, until he comes out cleansed of sin."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৪৪", "en": "Sahih Muslim 244"}}, {"type": "text", "text": {"bn": "উসমান (রা.) রাসুল ﷺ-এর মতো ওযু করে দেখালেন এবং বললেন, তিনি ﷺ বলেছেন: যে আমার এই ওযুর মতো ওযু করে মনোযোগ দিয়ে দুই রাকাত নামাজ পড়ে, তার আগের গুনাহ মাফ করে দেওয়া হয়।", "en": "Uthman (RA) demonstrated the Prophet''s ﷺ wudu and reported: whoever makes wudu like this and then prays two rak''ahs with focus, his previous sins are forgiven."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২২৬", "en": "Sahih Muslim 226"}}, {"type": "text", "text": {"bn": "কিয়ামতের দিন আমার উম্মতকে ডাকা হবে এমন অবস্থায় যে ওযুর প্রভাবে তাদের মুখ, হাত ও পা উজ্জ্বল থাকবে।", "en": "My ummah will be called on the Day of Resurrection with faces, hands and feet shining from the traces of wudu."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৩৬; সহিহ মুসলিম ২৪৬", "en": "Sahih al-Bukhari 136; Sahih Muslim 246"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: আমি কি তোমাদের এমন আমলের কথা বলব না যাতে আল্লাহ গুনাহ মুছে দেন ও মর্যাদা বাড়ান? কষ্টের সময়েও পূর্ণভাবে ওযু করা, মসজিদের দিকে বেশি কদম ফেলা এবং এক নামাজের পর আরেক নামাজের অপেক্ষা করা।", "en": "Shall I tell you what Allah wipes out sins with and raises ranks by? Completing wudu despite hardship, many steps to the mosque, and waiting for the next prayer after a prayer."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৫১", "en": "Sahih Muslim 251"}}, {"type": "heading", "text": {"bn": "ওযুর পরের দোয়া", "en": "Dua after wudu"}}, {"type": "arabic", "label": {"bn": "ওযুর পর কালেমা শাহাদাত", "en": "Testimony after wudu"}, "ar": "أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ", "pron": {"bn": "আশহাদু আল লা-ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহু, ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহু ওয়া রাসূলুহু", "en": "Ash-hadu al-la ilaha illallahu wahdahu la sharika lah, wa ash-hadu anna Muhammadan ''abduhu wa rasuluh"}, "meaning": {"bn": "আমি সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো সত্য ইলাহ নেই, তিনি এক, তাঁর কোনো শরিক নেই; আর আমি সাক্ষ্য দিচ্ছি, মুহাম্মাদ তাঁর বান্দা ও রাসুল।", "en": "I bear witness that there is no god but Allah alone, without partner, and I bear witness that Muhammad is His servant and Messenger."}, "ref": {"bn": "সহিহ মুসলিম ২৩৪", "en": "Sahih Muslim 234"}}, {"type": "text", "text": {"bn": "যে ভালোভাবে ওযু করে এই দোয়া পড়ে, তার জন্য জান্নাতের আটটি দরজা খুলে দেওয়া হয়; যেটি দিয়ে ইচ্ছা প্রবেশ করবে।", "en": "Whoever makes wudu well and says this, the eight gates of Paradise are opened for him to enter by whichever he wishes."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৩৪", "en": "Sahih Muslim 234"}}, {"type": "note", "tone": "info", "text": {"bn": "ওযুর নিয়ম ও ফরজ-সুন্নত জানতে “তাহারাত” বিভাগ দেখুন।", "en": "For how to make wudu and its obligations, see the Taharah section."}}]', 'in_review', 30 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '16666e3c-3aff-54fc-aa70-45664dcc5312', id, 'fazilat-adhan', '{"bn": "আজান দেওয়া ও আজানের জবাব দেওয়ার ফজিলত", "en": "Virtues of the adhan and answering it"}', '{"bn": "মুয়াজ্জিনের মর্যাদা, আজানের জবাব দেওয়ার নিয়ম এবং আজানের পরের দোয়ায় রাসুল ﷺ-এর শাফায়াত লাভ।", "en": "The rank of the muadhdhin, how to answer the adhan, and the dua after it that earns the Prophet''s ﷺ intercession."}', 'basic', '[{"type": "heading", "text": {"bn": "আজান দেওয়ার ফজিলত", "en": "Virtue of calling the adhan"}}, {"type": "text", "text": {"bn": "মানুষ যদি জানত আজান দেওয়া ও প্রথম কাতারে কী সওয়াব আছে, আর লটারি ছাড়া তা পাওয়ার উপায় না থাকত, তবে তারা লটারি করত।", "en": "If people knew the reward of the adhan and the first row, and could only get them by drawing lots, they would draw lots."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬১৫; সহিহ মুসলিম ৪৩৭", "en": "Sahih al-Bukhari 615; Sahih Muslim 437"}}, {"type": "text", "text": {"bn": "কিয়ামতের দিন মুয়াজ্জিনরা সবচেয়ে লম্বা গলাওয়ালা (সবচেয়ে সম্মানিত) হবে।", "en": "The muadhdhins will have the longest necks (the highest honour) on the Day of Resurrection."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৮৭", "en": "Sahih Muslim 387"}}, {"type": "text", "text": {"bn": "মুয়াজ্জিনের আওয়াজ যত দূর পৌঁছে, জিন, মানুষ ও যা কিছু তা শোনে, কিয়ামতের দিন তার পক্ষে সাক্ষ্য দেবে।", "en": "Every jinn, human or thing that hears the muadhdhin''s voice will testify for him on the Day of Resurrection."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬০৯", "en": "Sahih al-Bukhari 609"}}, {"type": "heading", "text": {"bn": "আজানের জবাব", "en": "Answering the adhan"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: মুয়াজ্জিনকে শুনলে সে যা বলে তোমরাও তা-ই বলো; তারপর আমার ওপর দরুদ পড়ো, তারপর আমার জন্য আল্লাহর কাছে “ওয়াসিলা” চাও। যে আমার জন্য ওয়াসিলা চাইবে, তার জন্য আমার শাফায়াত অবধারিত হবে।", "en": "When you hear the muadhdhin, say what he says, then send blessings on me, then ask Allah for al-Wasilah for me; whoever asks for it for me, my intercession becomes due for him."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৮৪", "en": "Sahih Muslim 384"}}, {"type": "text", "text": {"bn": "“হাইয়া আলাস সালাহ” ও “হাইয়া আলাল ফালাহ” শুনে বলতে হয়: “লা হাওলা ওয়ালা কুওয়াতা ইল্লা বিল্লাহ।” যে আন্তরিকভাবে এভাবে জবাব দেয়, সে জান্নাতে যাবে।", "en": "On hearing “Hayya ''alas-salah” and “Hayya ''alal-falah,” say “La hawla wa la quwwata illa billah.” Whoever answers sincerely like this will enter Paradise."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৮৫", "en": "Sahih Muslim 385"}}, {"type": "arabic", "label": {"bn": "মুয়াজ্জিনের শাহাদাত শুনে", "en": "On hearing the muadhdhin''s testimony"}, "ar": "وَأَنَا أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، رَضِيتُ بِاللّٰهِ رَبًّا، وَبِمُحَمَّدٍ رَسُولًا، وَبِالْإِسْلَامِ دِينًا", "pron": {"bn": "ওয়া আনা আশহাদু আল লা-ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহু, ওয়া আন্না মুহাম্মাদান আবদুহু ওয়া রাসূলুহু, রাদীতু বিল্লাহি রব্বান, ওয়া বিমুহাম্মাদিন রাসূলান, ওয়া বিল ইসলামি দীনা", "en": "Wa ana ash-hadu al-la ilaha illallahu wahdahu la sharika lah, wa anna Muhammadan ''abduhu wa rasuluh, raditu billahi rabban, wa bi-Muhammadin rasulan, wa bil-Islami dina"}, "meaning": {"bn": "আমিও সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো সত্য ইলাহ নেই, তিনি এক, তাঁর শরিক নেই, আর মুহাম্মাদ তাঁর বান্দা ও রাসুল। আমি আল্লাহকে রব, মুহাম্মাদকে রাসুল এবং ইসলামকে দ্বীন হিসেবে পেয়ে সন্তুষ্ট।", "en": "And I too bear witness that there is no god but Allah alone, without partner, and that Muhammad is His servant and Messenger. I am pleased with Allah as Lord, Muhammad as Messenger and Islam as religion."}, "ref": {"bn": "সহিহ মুসলিম ৩৮৬", "en": "Sahih Muslim 386"}}, {"type": "text", "text": {"bn": "যে মুয়াজ্জিনের শাহাদাত শুনে এটি বলে, তার গুনাহ মাফ করে দেওয়া হয়।", "en": "Whoever says this on hearing the muadhdhin, his sins are forgiven."}}, {"type": "heading", "text": {"bn": "আজানের পরের দোয়া", "en": "Dua after the adhan"}}, {"type": "arabic", "label": {"bn": "আজানের পরের দোয়া", "en": "Dua after the adhan"}, "ar": "اللّٰهُمَّ رَبَّ هٰذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ", "pron": {"bn": "আল্লাহুম্মা রব্বা হাযিহিদ দা''ওয়াতিত তাম্মাহ, ওয়াস সালাতিল কা-ইমাহ, আতি মুহাম্মাদানিল ওয়াসীলাতা ওয়াল ফাদীলাহ, ওয়াব''আসহু মাকামাম মাহমূদানিল্লাযী ওয়া''আদতাহ", "en": "Allahumma rabba hadhihid-da''watit-tammah, was-salatil-qa''imah, ati Muhammadanil-wasilata wal-fadilah, wab''ath-hu maqamam mahmudanil-ladhi wa''adtah"}, "meaning": {"bn": "হে আল্লাহ, এই পরিপূর্ণ আহ্বান ও প্রতিষ্ঠিত নামাজের রব, মুহাম্মাদ ﷺ-কে ওয়াসিলা ও শ্রেষ্ঠ মর্যাদা দান করুন এবং তাঁকে সেই প্রশংসিত স্থানে পৌঁছে দিন, যার ওয়াদা আপনি তাঁকে দিয়েছেন।", "en": "O Allah, Lord of this perfect call and the prayer about to be established, grant Muhammad al-Wasilah and excellence, and raise him to the praised station You promised him."}, "ref": {"bn": "সহিহ বুখারি ৬১৪", "en": "Sahih al-Bukhari 614"}}, {"type": "text", "text": {"bn": "যে আজান শুনে এই দোয়া পড়ে, কিয়ামতের দিন তার জন্য রাসুল ﷺ-এর শাফায়াত অবধারিত হয়ে যায়।", "en": "Whoever says this after hearing the adhan, the Prophet''s ﷺ intercession becomes due for him on the Day of Resurrection."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬১৪", "en": "Sahih al-Bukhari 614"}}, {"type": "note", "tone": "info", "text": {"bn": "প্রচলিত কিছু দোয়ার বইয়ে “ওয়াদ-দারাজাতার রাফিআহ” অংশ যোগ করা থাকে; সহিহ বুখারির বর্ণনায় এটি নেই। শেষে “ইন্নাকা লা তুখলিফুল মী''আদ” বায়হাকির একটি বর্ণনায় এসেছে, যার সনদ নিয়ে মুহাদ্দিসদের আপত্তি আছে। বুখারির শব্দগুলো পড়াই নিরাপদ।", "en": "Some dua books add “wad-darajatar-rafi''ah”; it is not in al-Bukhari''s narration. “Innaka la tukhliful-mi''ad” at the end comes in a narration of al-Bayhaqi whose chain scholars have questioned. Reciting al-Bukhari''s wording is safest."}}]', 'in_review', 40 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'e6d41a69-1d08-5baf-b6c6-77679bfc6c3a', id, 'fazilat-jumuah', '{"bn": "জুমার দিনের ফজিলত", "en": "Virtues of Friday (Jumu''ah)"}', '{"bn": "জুমা সপ্তাহের শ্রেষ্ঠ দিন: গোসল করে আগে আগে মসজিদে যাওয়া, চুপ করে খুতবা শোনা, দোয়া কবুলের মুহূর্ত ও বেশি বেশি দরুদ।", "en": "Friday is the best day of the week: ghusl, going early, listening silently to the khutbah, the hour of answered dua, and abundant salawat."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “হে মুমিনগণ, জুমার দিনে যখন নামাজের জন্য আহ্বান করা হয়, তখন আল্লাহর স্মরণের দিকে ছুটে যাও এবং বেচাকেনা ছেড়ে দাও।”", "en": "Allah says: “O you who believe, when the call is made for prayer on Friday, hasten to the remembrance of Allah and leave trade.”"}}, {"type": "ref", "text": {"bn": "সূরা জুমুআ ৬২:৯", "en": "Al-Jumu''ah 62:9"}}, {"type": "text", "text": {"bn": "সূর্য উদিত হয় এমন দিনগুলোর মধ্যে শ্রেষ্ঠ দিন জুমার দিন; এ দিনে আদম (আ.)-কে সৃষ্টি করা হয়েছে, এ দিনে তাঁকে জান্নাতে প্রবেশ করানো হয়েছে, এ দিনেই সেখান থেকে বের করা হয়েছে, আর কিয়ামতও জুমার দিনেই হবে।", "en": "The best day on which the sun rises is Friday: on it Adam was created, entered Paradise and was sent out of it, and the Hour will be on a Friday."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৮৫৪", "en": "Sahih Muslim 854"}}, {"type": "heading", "text": {"bn": "আগে আগে মসজিদে যাওয়া", "en": "Going early"}}, {"type": "text", "text": {"bn": "যে জুমার দিন জানাবাতের গোসলের মতো গোসল করে প্রথম সময়ে মসজিদে যায়, সে যেন একটি উট কুরবানি করল; দ্বিতীয় সময়ে গেলে গরু, তৃতীয় সময়ে শিংওয়ালা দুম্বা, চতুর্থ সময়ে মুরগি, পঞ্চম সময়ে ডিম। ইমাম খুতবার জন্য বের হলে ফেরেশতারা খাতা বন্ধ করে খুতবা শুনতে থাকেন।", "en": "Whoever takes a full ghusl on Friday and goes in the first hour, it is as if he sacrificed a camel; in the second a cow, the third a horned ram, the fourth a hen, the fifth an egg. When the imam comes out, the angels close their records and listen."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৮৮১; সহিহ মুসলিম ৮৫০", "en": "Sahih al-Bukhari 881; Sahih Muslim 850"}}, {"type": "text", "text": {"bn": "যে জুমার দিন গোসল করে, সাধ্যমতো পবিত্রতা অর্জন করে, তেল বা সুগন্ধি লাগায়, মসজিদে গিয়ে দুজনের মাঝে ফাঁক করে না, তার জন্য যা নির্ধারিত তা নামাজ পড়ে, তারপর ইমাম কথা বললে চুপ থাকে, তার এই জুমা থেকে আগের জুমা পর্যন্ত গুনাহ মাফ হয়।", "en": "Whoever bathes on Friday, purifies himself as he can, uses oil or perfume, goes out without separating two people, prays what is written for him and listens silently when the imam speaks, is forgiven what is between that Friday and the previous one."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৮৮৩", "en": "Sahih al-Bukhari 883"}}, {"type": "text", "text": {"bn": "মুসলিমের বর্ণনায় আছে: এর সঙ্গে আরও তিন দিনের গুনাহ মাফ হয়।", "en": "In Muslim''s narration: plus three more days."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৮৫৭", "en": "Sahih Muslim 857"}}, {"type": "heading", "text": {"bn": "দোয়া কবুলের মুহূর্ত", "en": "The hour of acceptance"}}, {"type": "text", "text": {"bn": "জুমার দিনে একটি মুহূর্ত আছে, কোনো মুসলিম বান্দা তখন নামাজে দাঁড়িয়ে আল্লাহর কাছে কোনো কল্যাণ চাইলে আল্লাহ তা দেন।", "en": "On Friday there is an hour in which no Muslim stands praying and asks Allah for good except that He gives it to him."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৯৩৫; সহিহ মুসলিম ৮৫২", "en": "Sahih al-Bukhari 935; Sahih Muslim 852"}}, {"type": "note", "tone": "info", "text": {"bn": "এই মুহূর্ত কখন, তা নিয়ে আলেমদের কয়েকটি মত আছে; প্রসিদ্ধ দুটি হলো: ইমাম মিম্বরে বসা থেকে নামাজ শেষ হওয়া পর্যন্ত (সহিহ মুসলিম ৮৫৩), এবং আসরের পর থেকে সূর্যাস্ত পর্যন্ত (সুনান আবু দাউদ)। দুটো সময়েই দোয়া করা ভালো।", "en": "Scholars hold several views on when this hour is; the best known are from when the imam sits on the minbar until the prayer ends (Sahih Muslim 853), and the last hour after Asr until sunset (Sunan Abi Dawud). It is good to make dua in both."}, "check": true}, {"type": "heading", "text": {"bn": "জুমার দিনে বেশি দরুদ", "en": "More salawat on Friday"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: তোমাদের দিনগুলোর মধ্যে জুমার দিন শ্রেষ্ঠ; এ দিনে আমার ওপর বেশি বেশি দরুদ পড়ো, কারণ তোমাদের দরুদ আমার কাছে পেশ করা হয়।", "en": "The best of your days is Friday, so send abundant blessings on me on it, for your blessings are presented to me."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ; সুনান নাসায়ি", "en": "Sunan Abi Dawud; Sunan an-Nasa''i"}, "check": true}, {"type": "note", "tone": "warn", "text": {"bn": "বিনা ওজরে অবহেলা করে পরপর তিন জুমা ছেড়ে দিলে আল্লাহ তার অন্তরে মোহর মেরে দেন (সুনান আবু দাউদ, সুনান তিরমিজি)।", "en": "Whoever leaves three Fridays in a row out of negligence, Allah seals his heart (Sunan Abi Dawud, Jami'' at-Tirmidhi)."}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "জুমার দিন সূরা কাহফ পড়ার ফজিলত আলাদা গাইডে দেখুন।", "en": "See the separate guide on reciting Surah Al-Kahf on Friday."}}]', 'in_review', 50 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'e529c1cb-54f5-5fc2-80bd-682804ed623a', id, 'fazilat-tahajjud', '{"bn": "তাহাজ্জুদ (রাতের নামাজ)-এর ফজিলত", "en": "Virtues of Tahajjud (night prayer)"}', '{"bn": "ফরজের পর শ্রেষ্ঠ নামাজ রাতের নামাজ; রাতের শেষ তৃতীয়াংশে আল্লাহ বান্দাদের ডাকেন।", "en": "After the obligatory prayers, the best prayer is the night prayer; in the last third of the night Allah calls out to His servants."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ রাসুল ﷺ-কে বলেন: “রাতের কিছু অংশে তাহাজ্জুদ পড়ো, এটি তোমার জন্য অতিরিক্ত; আশা করা যায় তোমার রব তোমাকে প্রশংসিত স্থানে পৌঁছাবেন।” আর মুমিনদের প্রশংসায় বলেন: “তাদের পার্শ্ব বিছানা থেকে আলাদা থাকে; তারা ভয় ও আশা নিয়ে তাদের রবকে ডাকে।”", "en": "Allah tells the Prophet ﷺ: “And from part of the night, pray with it as extra for you; it is expected your Lord will raise you to a praised station.” And He praises the believers: “Their sides forsake their beds; they call upon their Lord in fear and hope.”"}}, {"type": "ref", "text": {"bn": "সূরা বনি ইসরাঈল ১৭:৭৯; সূরা সাজদা ৩২:১৬", "en": "Al-Isra 17:79; As-Sajdah 32:16"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: রমজানের পর শ্রেষ্ঠ রোজা আল্লাহর মাস মহররমের রোজা, আর ফরজ নামাজের পর শ্রেষ্ঠ নামাজ রাতের নামাজ।", "en": "The best fasting after Ramadan is in Allah''s month of Muharram, and the best prayer after the obligatory is the night prayer."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ১১৬৩", "en": "Sahih Muslim 1163"}}, {"type": "text", "text": {"bn": "প্রতি রাতে শেষ তৃতীয়াংশে আমাদের রব দুনিয়ার আসমানে নেমে আসেন এবং বলেন: কে আমাকে ডাকবে, আমি সাড়া দেব? কে আমার কাছে চাইবে, আমি দেব? কে আমার কাছে ক্ষমা চাইবে, আমি ক্ষমা করব?", "en": "Every night, in its last third, our Lord descends to the lowest heaven and says: Who will call on Me that I may answer? Who will ask Me that I may give? Who will seek My forgiveness that I may forgive?"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১১৪৫; সহিহ মুসলিম ৭৫৮", "en": "Sahih al-Bukhari 1145; Sahih Muslim 758"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ রাতে এত দীর্ঘ নামাজ পড়তেন যে তাঁর পা ফুলে যেত; জিজ্ঞেস করা হলে বলতেন: “আমি কি কৃতজ্ঞ বান্দা হব না?”", "en": "The Prophet ﷺ prayed so long at night that his feet swelled; when asked, he said: “Should I not be a grateful servant?”"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি; সহিহ মুসলিম", "en": "Sahih al-Bukhari; Sahih Muslim"}, "check": true}, {"type": "heading", "text": {"bn": "কীভাবে শুরু করবেন", "en": "How to start"}}, {"type": "list", "items": [{"bn": "ঘুমানোর আগে নিয়ত করে রাখুন এবং এশার পর তাড়াতাড়ি ঘুমান।", "en": "Intend it before sleeping and sleep early after Isha."}, {"bn": "দুই রাকাত দিয়েও শুরু করা যায়; রাসুল ﷺ সাধারণত বিতরসহ এগারো রাকাতের বেশি পড়তেন না (সহিহ বুখারি ১১৪৭)।", "en": "You can start with just two rak''ahs; the Prophet ﷺ usually did not exceed eleven including witr (Sahih al-Bukhari 1147)."}, {"bn": "শেষ রাতে উঠতে না পারার আশঙ্কা থাকলে ঘুমানোর আগেই বিতর পড়ে নিন (সহিহ মুসলিম ৭৫৫)।", "en": "If you fear not waking, pray witr before sleeping (Sahih Muslim 755)."}, {"bn": "সিজদায় ও নামাজ শেষে নিজের ভাষায় মন খুলে দোয়া করুন।", "en": "Make heartfelt dua in sujood and after the prayer in your own words."}]}]', 'in_review', 60 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '484f1126-c853-5628-97f6-02b33779f68c', id, 'fazilat-quran-tilawat', '{"bn": "কুরআন তিলাওয়াতের ফজিলত", "en": "Virtues of reciting the Quran"}', '{"bn": "প্রতিটি হরফে নেকি, কিয়ামতের দিন সুপারিশ, আর আটকে আটকে পড়লেও দ্বিগুণ সওয়াব।", "en": "A reward for every letter, intercession on the Last Day, and a double reward even for one who struggles."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “যারা আল্লাহর কিতাব তিলাওয়াত করে, নামাজ কায়েম করে এবং আমার দেওয়া রিজিক থেকে গোপনে ও প্রকাশ্যে ব্যয় করে, তারা এমন ব্যবসার আশা করে যা কখনো লোকসান হবে না।”", "en": "Allah says: “Those who recite the Book of Allah, establish prayer and spend from what We provided them, secretly and openly, hope for a trade that will never perish.”"}}, {"type": "ref", "text": {"bn": "সূরা ফাতির ৩৫:২৯–৩০", "en": "Fatir 35:29–30"}}, {"type": "text", "text": {"bn": "যে আল্লাহর কিতাবের একটি হরফ পড়ে, সে একটি নেকি পায়, আর একটি নেকি দশ গুণ। আমি বলি না “আলিফ-লাম-মীম” একটি হরফ; বরং আলিফ একটি হরফ, লাম একটি হরফ, মীম একটি হরফ।", "en": "Whoever reads a letter of Allah''s Book gets a good deed, and a good deed is multiplied by ten. I do not say “Alif-Lam-Mim” is one letter; Alif is a letter, Lam is a letter and Mim is a letter."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ২৯১০", "en": "Jami'' at-Tirmidhi 2910"}}, {"type": "text", "text": {"bn": "তোমাদের মধ্যে সর্বোত্তম সে, যে কুরআন শেখে ও শেখায়।", "en": "The best of you are those who learn the Quran and teach it."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫০২৭", "en": "Sahih al-Bukhari 5027"}}, {"type": "text", "text": {"bn": "কুরআন পড়ো, কারণ কিয়ামতের দিন কুরআন তার পাঠকদের জন্য সুপারিশকারী হয়ে আসবে।", "en": "Recite the Quran, for it will come on the Day of Resurrection as an intercessor for its companions."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৮০৪", "en": "Sahih Muslim 804"}}, {"type": "text", "text": {"bn": "যে কুরআনে দক্ষ, সে সম্মানিত পুণ্যবান লেখক ফেরেশতাদের সঙ্গে থাকবে; আর যে কষ্ট করে আটকে আটকে পড়ে, সে দ্বিগুণ সওয়াব পাবে।", "en": "One skilled in the Quran will be with the noble, righteous scribes; and one who recites with difficulty, stumbling, gets a double reward."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৪৯৩৭; সহিহ মুসলিম ৭৯৮", "en": "Sahih al-Bukhari 4937; Sahih Muslim 798"}}, {"type": "text", "text": {"bn": "যখন কিছু মানুষ আল্লাহর কোনো ঘরে একত্র হয়ে কুরআন পড়ে ও পরস্পর আলোচনা করে, তাদের ওপর প্রশান্তি নাজিল হয়, রহমত তাদের ঢেকে নেয়, ফেরেশতারা তাদের ঘিরে রাখে এবং আল্লাহ তাঁর কাছে থাকা ফেরেশতাদের কাছে তাদের কথা উল্লেখ করেন।", "en": "Whenever people gather in a house of Allah reciting and studying the Quran together, tranquillity descends on them, mercy covers them, angels surround them and Allah mentions them to those with Him."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৬৯৯", "en": "Sahih Muslim 2699"}}, {"type": "text", "text": {"bn": "আল্লাহ এই কিতাব দিয়ে কিছু জাতিকে উঁচু করেন আর কিছু জাতিকে নিচু করেন।", "en": "Allah raises some people by this Book and lowers others by it."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৮১৭", "en": "Sahih Muslim 817"}}, {"type": "note", "tone": "tip", "text": {"bn": "অর্থ না বুঝে পড়লেও সওয়াব আছে, তবে প্রতিদিন অল্প হলেও অর্থসহ পড়ার চেষ্টা করুন, যাতে কুরআন জীবনে প্রভাব ফেলে।", "en": "There is reward even without understanding, but try to read a little with meaning each day so the Quran shapes your life."}}]', 'in_review', 70 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '28d707d4-63ce-5ee6-9f9e-c6db196051f8', id, 'fazilat-surah-fatihah', '{"bn": "সূরা ফাতিহার ফজিলত", "en": "Virtues of Surah Al-Fatihah"}', '{"bn": "কুরআনের সবচেয়ে মহান সূরা, যা প্রতি রাকাতে পড়া হয় এবং যার প্রতিটি আয়াতে আল্লাহ বান্দার জবাব দেন।", "en": "The greatest surah of the Quran, recited in every rak''ah, with Allah responding to each verse."}', 'basic', '[{"type": "text", "text": {"bn": "রাসুল ﷺ আবু সাঈদ ইবনুল মুআল্লা (রা.)-কে বললেন: আমি তোমাকে কুরআনের সবচেয়ে মহান সূরা শিখিয়ে দেব: “আলহামদু লিল্লাহি রব্বিল আলামীন”; এটিই “আস-সাবউল মাসানি” (বারবার পঠিত সাত আয়াত) এবং আমাকে দেওয়া মহান কুরআন।", "en": "The Prophet ﷺ told Abu Sa''id ibn al-Mu''alla (RA): I will teach you the greatest surah in the Quran: “Al-hamdu lillahi rabbil-''alamin”; it is the seven oft-repeated verses and the great Quran given to me."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৪৪৭৪", "en": "Sahih al-Bukhari 4474"}}, {"type": "text", "text": {"bn": "একজন ফেরেশতা রাসুল ﷺ-কে বললেন: আপনাকে এমন দুটি নূরের সুসংবাদ দিচ্ছি যা আপনার আগে কোনো নবীকে দেওয়া হয়নি: সূরা ফাতিহা এবং সূরা বাকারার শেষ আয়াতগুলো। এগুলোর যে অংশই আপনি পড়বেন, তা আপনাকে দেওয়া হবে।", "en": "An angel told the Prophet ﷺ: rejoice in two lights given to you that were given to no prophet before you: Al-Fatihah and the closing verses of Al-Baqarah. You will not recite a letter of them without being given it."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৮০৬", "en": "Sahih Muslim 806"}}, {"type": "heading", "text": {"bn": "বান্দা ও আল্লাহর কথোপকথন", "en": "A conversation between the servant and Allah"}}, {"type": "text", "text": {"bn": "হাদিসে কুদসিতে আল্লাহ বলেন: আমি নামাজকে (ফাতিহাকে) আমার ও আমার বান্দার মাঝে ভাগ করেছি, আর আমার বান্দা যা চায় তা পাবে।", "en": "In a hadith qudsi Allah says: I have divided the prayer (Al-Fatihah) between Myself and My servant, and My servant shall have what he asks."}}, {"type": "list", "items": [{"bn": "বান্দা বলে “আলহামদু লিল্লাহি রব্বিল আলামীন”, আল্লাহ বলেন: আমার বান্দা আমার প্রশংসা করেছে।", "en": "The servant says “All praise is for Allah, Lord of the worlds”; Allah says: My servant has praised Me."}, {"bn": "বান্দা বলে “আর-রহমানির রহীম”, আল্লাহ বলেন: আমার বান্দা আমার গুণগান করেছে।", "en": "He says “the Most Gracious, the Most Merciful”; Allah says: My servant has extolled Me."}, {"bn": "বান্দা বলে “মালিকি ইয়াওমিদ্দীন”, আল্লাহ বলেন: আমার বান্দা আমার মহিমা ঘোষণা করেছে।", "en": "He says “Master of the Day of Judgement”; Allah says: My servant has glorified Me."}, {"bn": "বান্দা বলে “ইয়্যাকা না''বুদু ওয়া ইয়্যাকা নাসতাঈন”, আল্লাহ বলেন: এটি আমার ও আমার বান্দার মাঝে, আর বান্দা যা চায় তা পাবে।", "en": "He says “You alone we worship and You alone we ask for help”; Allah says: This is between Me and My servant, and he shall have what he asks."}, {"bn": "বান্দা শেষ আয়াতগুলোতে হেদায়াত চায়, আল্লাহ বলেন: এগুলো আমার বান্দার জন্য, আর সে যা চায় তা পাবে।", "en": "He asks for guidance in the last verses; Allah says: This is for My servant, and he shall have what he asks."}]}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৯৫", "en": "Sahih Muslim 395"}}, {"type": "arabic", "ar": "إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ", "pron": {"bn": "ইয়্যাকা না''বুদু ওয়া ইয়্যাকা নাসতাঈন", "en": "Iyyaka na''budu wa iyyaka nasta''in"}, "meaning": {"bn": "আমরা কেবল আপনারই ইবাদত করি এবং কেবল আপনারই সাহায্য চাই।", "en": "You alone we worship, and You alone we ask for help."}, "ref": {"bn": "সূরা ফাতিহা ১:৫", "en": "Al-Fatihah 1:5"}}, {"type": "text", "text": {"bn": "এক সাহাবি সাপে কাটা এক গোত্রপ্রধানের ওপর সূরা ফাতিহা পড়ে ফুঁ দিলে তিনি সুস্থ হন, আর রাসুল ﷺ তা সমর্থন করেন; তাই ফাতিহা রুকইয়া (ঝাড়ফুঁক) হিসেবেও পড়া যায়।", "en": "A Companion recited Al-Fatihah over a tribal chief stung by a scorpion and he recovered, and the Prophet ﷺ approved; so it may be recited as ruqyah."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি", "en": "Sahih al-Bukhari"}, "check": true}]', 'in_review', 80 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '2104f8ee-7334-50fb-8368-8c8216d71c76', id, 'fazilat-surah-ikhlas', '{"bn": "সূরা ইখলাসের ফজিলত", "en": "Virtues of Surah Al-Ikhlas"}', '{"bn": "সূরা ইখলাস কুরআনের এক-তৃতীয়াংশের সমান, আর এর প্রতি ভালোবাসা আল্লাহর ভালোবাসা এনে দেয়।", "en": "Surah Al-Ikhlas equals a third of the Quran, and loving it brings Allah''s love."}', 'basic', '[{"type": "arabic", "label": {"bn": "সূরা ইখলাস", "en": "Surah Al-Ikhlas"}, "ar": "قُلْ هُوَ اللّٰهُ أَحَدٌ ۝ اللّٰهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ", "pron": {"bn": "কুল হুওয়াল্লাহু আহাদ। আল্লাহুস সামাদ। লাম ইয়ালিদ ওয়া লাম ইউলাদ। ওয়া লাম ইয়াকুল লাহু কুফুওয়ান আহাদ।", "en": "Qul huwallahu ahad. Allahus-samad. Lam yalid wa lam yulad. Wa lam yakun lahu kufuwan ahad."}, "meaning": {"bn": "বলো, তিনি আল্লাহ, এক ও অদ্বিতীয়। আল্লাহ অমুখাপেক্ষী। তিনি কাউকে জন্ম দেননি, তাঁকেও কেউ জন্ম দেয়নি। আর তাঁর সমকক্ষ কেউ নেই।", "en": "Say: He is Allah, the One. Allah, the Eternal Refuge. He neither begets nor is born. And there is none comparable to Him."}, "ref": {"bn": "সূরা ইখলাস ১১২:১–৪", "en": "Al-Ikhlas 112:1–4"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: যাঁর হাতে আমার প্রাণ, তাঁর কসম, এই সূরা কুরআনের এক-তৃতীয়াংশের সমান।", "en": "By Him in whose hand is my soul, it is equal to a third of the Quran."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫০১৩; সহিহ মুসলিম ৮১১", "en": "Sahih al-Bukhari 5013; Sahih Muslim 811"}}, {"type": "text", "text": {"bn": "এক সাহাবি প্রতি রাকাতে কিরাত শেষে সূরা ইখলাস পড়তেন। কারণ জিজ্ঞেস করলে বললেন, এতে দয়াময় আল্লাহর গুণাবলি আছে, তাই আমি এটি পড়তে ভালোবাসি। রাসুল ﷺ বললেন: “তাকে জানিয়ে দাও, আল্লাহ তাকে ভালোবাসেন।”", "en": "A Companion ended his recitation in every rak''ah with Al-Ikhlas because it describes the Most Merciful and he loved to recite it. The Prophet ﷺ said: “Tell him that Allah loves him.”"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৭৩৭৫; সহিহ মুসলিম ৮১৩", "en": "Sahih al-Bukhari 7375; Sahih Muslim 813"}}, {"type": "heading", "text": {"bn": "ঘুমানোর আগে ও সকাল-সন্ধ্যায়", "en": "Before sleep and morning and evening"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ প্রতি রাতে বিছানায় গিয়ে দুই হাত একত্র করে সূরা ইখলাস, ফালাক ও নাস পড়ে তাতে ফুঁ দিতেন, তারপর মাথা ও মুখ থেকে শুরু করে যতটুকু সম্ভব শরীরে হাত বুলাতেন; এভাবে তিনবার করতেন।", "en": "Each night in bed the Prophet ﷺ would cup his hands, recite Al-Ikhlas, Al-Falaq and An-Nas, blow into them and wipe over as much of his body as he could, starting with his head and face, three times."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫০১৭", "en": "Sahih al-Bukhari 5017"}}, {"type": "text", "text": {"bn": "সকাল ও সন্ধ্যায় তিনবার করে সূরা ইখলাস, ফালাক ও নাস পড়লে তা সব কিছু থেকে রক্ষার জন্য যথেষ্ট হবে।", "en": "Reciting Al-Ikhlas, Al-Falaq and An-Nas three times each morning and evening will suffice you against everything."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ; সুনান তিরমিজি", "en": "Sunan Abi Dawud; Jami'' at-Tirmidhi"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "এক-তৃতীয়াংশের সমান হওয়া মানে সওয়াব ও অর্থের দিক থেকে মর্যাদা; এর মানে এই নয় যে তিনবার ইখলাস পড়লে পুরো কুরআন পড়ার প্রয়োজন শেষ।", "en": "Equalling a third of the Quran refers to its rank and reward; it does not mean reading it three times replaces reading the whole Quran."}}]', 'in_review', 90 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '955ab243-2993-5ed5-866c-dc910ac4c77b', id, 'fazilat-ayatul-kursi-baqarah', '{"bn": "আয়াতুল কুরসি ও সূরা বাকারার শেষ দুই আয়াতের ফজিলত", "en": "Virtues of Ayat al-Kursi and the last two verses of Al-Baqarah"}', '{"bn": "কুরআনের সবচেয়ে মহান আয়াত ঘুমের আগে সুরক্ষা দেয়, আর রাতে বাকারার শেষ দুই আয়াত পড়া যথেষ্ট হয়ে যায়।", "en": "The greatest verse of the Quran protects before sleep, and the last two verses of Al-Baqarah suffice whoever recites them at night."}', 'basic', '[{"type": "text", "text": {"bn": "যে ঘরে সূরা বাকারা পড়া হয়, শয়তান সেখান থেকে পালিয়ে যায়; তাই ঘরকে কবরস্থান বানিয়ো না।", "en": "Do not make your houses graveyards; Shaytan flees from a house in which Surah Al-Baqarah is recited."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৭৮০", "en": "Sahih Muslim 780"}}, {"type": "heading", "text": {"bn": "আয়াতুল কুরসি", "en": "Ayat al-Kursi"}}, {"type": "arabic", "label": {"bn": "আয়াতুল কুরসি", "en": "Ayat al-Kursi"}, "ar": "اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمٰوٰتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمٰوٰتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ", "pron": {"bn": "আল্লাহু লা ইলাহা ইল্লা হুওয়াল হাইয়্যুল কাইয়ুম। লা তা''খুযুহু সিনাতুঁ ওয়ালা নাওম। লাহু মা ফিস সামাওয়াতি ওয়ামা ফিল আরদ। মান যাল্লাযী ইয়াশফাউ ইনদাহু ইল্লা বিইযনিহ। ইয়া''লামু মা বাইনা আইদীহিম ওয়ামা খালফাহুম। ওয়ালা ইউহীতূনা বিশাইয়িম মিন ইলমিহী ইল্লা বিমা শা-আ। ওয়াসিআ কুরসিয়্যুহুস সামাওয়াতি ওয়াল আরদ। ওয়ালা ইয়াউদুহু হিফযুহুমা, ওয়া হুওয়াল আলিয়্যুল আযীম।", "en": "Allahu la ilaha illa huwal-hayyul-qayyum. La ta''khudhuhu sinatun wa la nawm. Lahu ma fis-samawati wa ma fil-ard. Man dhal-ladhi yashfa''u ''indahu illa bi-idhnih. Ya''lamu ma bayna aydihim wa ma khalfahum. Wa la yuhituna bi-shay''im-min ''ilmihi illa bima sha''. Wasi''a kursiyyuhus-samawati wal-ard. Wa la ya''uduhu hifzuhuma, wa huwal-''aliyyul-''azim."}, "meaning": {"bn": "আল্লাহ, তিনি ছাড়া কোনো সত্য ইলাহ নেই; তিনি চিরঞ্জীব, সবকিছুর ধারক। তন্দ্রা ও নিদ্রা তাঁকে স্পর্শ করে না। আসমান ও জমিনে যা কিছু আছে সব তাঁরই। কে আছে যে তাঁর অনুমতি ছাড়া তাঁর কাছে সুপারিশ করবে? তাদের সামনে ও পেছনে যা আছে সব তিনি জানেন; তিনি যতটুকু চান তার বাইরে তাঁর জ্ঞানের কিছুই তারা আয়ত্ত করতে পারে না। তাঁর কুরসি আসমান ও জমিন পরিব্যাপ্ত; এ দুটির রক্ষণাবেক্ষণ তাঁকে ক্লান্ত করে না। তিনি সমুচ্চ, মহান।", "en": "Allah: there is no god but He, the Ever-Living, the Sustainer of all. Neither drowsiness nor sleep overtakes Him. His is whatever is in the heavens and the earth. Who can intercede with Him except by His permission? He knows what is before them and behind them, and they encompass nothing of His knowledge except what He wills. His Kursi extends over the heavens and the earth, and guarding them does not tire Him. He is the Most High, the Magnificent."}, "ref": {"bn": "সূরা বাকারা ২:২৫৫", "en": "Al-Baqarah 2:255"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ উবাই ইবনে কা''ব (রা.)-কে জিজ্ঞেস করলেন, আল্লাহর কিতাবের কোন আয়াত সবচেয়ে মহান? তিনি বললেন: আয়াতুল কুরসি। রাসুল ﷺ তাঁর বুকে হাত দিয়ে বললেন: “আবুল মুনযির, এই জ্ঞান তোমার জন্য মোবারক হোক।”", "en": "The Prophet ﷺ asked Ubayy ibn Ka''b (RA) which verse of Allah''s Book is greatest. He said: Ayat al-Kursi. The Prophet ﷺ struck his chest and said: “May knowledge be pleasant for you, Abul-Mundhir.”"}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৮১০", "en": "Sahih Muslim 810"}}, {"type": "text", "text": {"bn": "আবু হুরাইরা (রা.)-এর ঘটনায় এসেছে: ঘুমানোর সময় আয়াতুল কুরসি পড়লে সকাল পর্যন্ত আল্লাহর পক্ষ থেকে একজন রক্ষক থাকবে, আর শয়তান কাছে আসতে পারবে না। রাসুল ﷺ বললেন: “সে (শয়তান) মিথ্যুক হলেও এ কথাটি সত্য বলেছে।”", "en": "In the story of Abu Hurairah (RA): whoever recites Ayat al-Kursi when going to bed will have a guardian from Allah and no devil will come near him until morning. The Prophet ﷺ said: “He told you the truth though he is a liar.”"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২৩১১", "en": "Sahih al-Bukhari 2311"}}, {"type": "text", "text": {"bn": "প্রত্যেক ফরজ নামাজের পর আয়াতুল কুরসি পড়লে মৃত্যু ছাড়া আর কিছু তাকে জান্নাতে প্রবেশে বাধা দেবে না।", "en": "Whoever recites Ayat al-Kursi after every obligatory prayer, nothing prevents him from entering Paradise except death."}}, {"type": "ref", "text": {"bn": "সুনানুল কুবরা, নাসায়ি", "en": "As-Sunan al-Kubra, an-Nasa''i"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "এই শেষ হাদিসটি নাসায়ির “আমালুল ইয়াওমি ওয়াল লাইলা” / “সুনানুল কুবরা”-তে আছে; অনেক মুহাদ্দিস (যেমন আলবানি) একে সহিহ বলেছেন, কেউ কেউ সনদে আপত্তি করেছেন।", "en": "This last hadith is in an-Nasa''i''s ''Amal al-Yawm wal-Laylah / As-Sunan al-Kubra; many hadith scholars (e.g. al-Albani) graded it sahih, while some questioned its chain."}, "check": true}, {"type": "heading", "text": {"bn": "সূরা বাকারার শেষ দুই আয়াত", "en": "The last two verses of Al-Baqarah"}}, {"type": "text", "text": {"bn": "যে রাতে সূরা বাকারার শেষ দুই আয়াত (২৮৫–২৮৬) পড়ে, তার জন্য এ দুটিই যথেষ্ট।", "en": "Whoever recites the last two verses of Surah Al-Baqarah (285–286) at night, they will suffice him."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৫০০৯; সহিহ মুসলিম ৮০৭", "en": "Sahih al-Bukhari 5009; Sahih Muslim 807"}}, {"type": "text", "text": {"bn": "এ দুটি আয়াত সেই দুই নূরের একটি, যা রাসুল ﷺ-এর আগে কোনো নবীকে দেওয়া হয়নি (অন্যটি সূরা ফাতিহা)।", "en": "These verses are one of the two lights given to no prophet before him ﷺ (the other being Al-Fatihah)."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৮০৬", "en": "Sahih Muslim 806"}}, {"type": "text", "text": {"bn": "শেষ আয়াতের প্রতিটি দোয়ার পর আল্লাহ বলেছেন: “আমি তা কবুল করলাম।”", "en": "After each supplication in the final verse, Allah said: “I have done so.”"}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম", "en": "Sahih Muslim"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "“যথেষ্ট” শব্দের ব্যাখ্যায় আলেমরা বলেছেন: রাতের নফল নামাজের জন্য যথেষ্ট, অথবা সব অনিষ্ট থেকে রক্ষার জন্য যথেষ্ট; দুটো অর্থই হতে পারে।", "en": "Scholars explain “suffice” as sufficing for night prayer, or protecting from all harm; both meanings are possible."}}]', 'in_review', 100 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '864720a8-ae13-5381-b0ff-7df25921cbfd', id, 'fazilat-surah-mulk', '{"bn": "সূরা মুলকের ফজিলত", "en": "Virtues of Surah Al-Mulk"}', '{"bn": "ত্রিশ আয়াতের এই সূরা তার পাঠকের জন্য সুপারিশ করে, এবং রাসুল ﷺ রাতে এটি না পড়ে ঘুমাতেন না।", "en": "This thirty-verse surah intercedes for its reciter, and the Prophet ﷺ would not sleep without reciting it."}', 'basic', '[{"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: কুরআনে ত্রিশ আয়াতের একটি সূরা আছে, যা এক ব্যক্তির জন্য সুপারিশ করেছিল, শেষে তাকে ক্ষমা করে দেওয়া হয়েছে। সেটি হলো “তাবারাকাল্লাযী বিয়াদিহিল মুলক”।", "en": "There is a surah in the Quran of thirty verses that interceded for a man until he was forgiven: “Tabarakal-ladhi biyadihil-mulk.”"}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ২৮৯১; সুনান আবু দাউদ ১৪০০", "en": "Jami'' at-Tirmidhi 2891; Sunan Abi Dawud 1400"}}, {"type": "note", "tone": "info", "text": {"bn": "ইমাম তিরমিজি এই হাদিসকে হাসান বলেছেন।", "en": "Imam at-Tirmidhi graded this hadith hasan."}}, {"type": "text", "text": {"bn": "জাবির (রা.) বলেন: রাসুল ﷺ সূরা আলিফ-লাম-মীম সাজদা ও সূরা মুলক না পড়ে ঘুমাতেন না।", "en": "Jabir (RA) said: the Prophet ﷺ would not sleep until he had recited Alif-Lam-Mim As-Sajdah and Al-Mulk."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি", "en": "Jami'' at-Tirmidhi"}, "check": true}, {"type": "text", "text": {"bn": "আবদুল্লাহ ইবনে মাসউদ (রা.) থেকে বর্ণিত: সূরা মুলক কবরের আজাব থেকে রক্ষাকারী।", "en": "From Abdullah ibn Mas''ud (RA): Surah Al-Mulk is the protector from the punishment of the grave."}}, {"type": "ref", "text": {"bn": "সুনানুল কুবরা, নাসায়ি; মুস্তাদরাক হাকিম", "en": "As-Sunan al-Kubra, an-Nasa''i; Al-Mustadrak, al-Hakim"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "শেষ বর্ণনাটি অনেক মুহাদ্দিস হাসান বলেছেন; এটি ইবনে মাসউদ (রা.)-এর কথা হিসেবে এসেছে, কোনো কোনো সূত্রে রাসুল ﷺ-এর কথা হিসেবে।", "en": "Many scholars graded the last report hasan; it comes as the words of Ibn Mas''ud (RA), and in some routes from the Prophet ﷺ."}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "প্রতি রাতে এশার পর বা ঘুমানোর আগে সূরা মুলক পড়ার অভ্যাস করুন; মুখস্থ না থাকলে দেখে পড়ুন।", "en": "Make a habit of reciting Al-Mulk after Isha or before sleep; read from the mushaf if you have not memorised it."}}]', 'in_review', 110 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '6373ee4d-21ba-5de5-9986-c58bfec6a270', id, 'fazilat-surah-kahf', '{"bn": "সূরা কাহফ ও জুমার দিনে পড়ার ফজিলত", "en": "Surah Al-Kahf and reciting it on Friday"}', '{"bn": "সূরা কাহফের প্রথম দশ আয়াত দাজ্জাল থেকে রক্ষা করে, আর জুমার দিনে পড়লে দুই জুমার মাঝে নূর পাওয়া যায়।", "en": "The first ten verses of Al-Kahf protect from the Dajjal, and reciting it on Friday brings light between two Fridays."}', 'basic', '[{"type": "text", "text": {"bn": "যে সূরা কাহফের প্রথম দশ আয়াত মুখস্থ করবে, সে দাজ্জালের ফিতনা থেকে রক্ষা পাবে।", "en": "Whoever memorises the first ten verses of Surah Al-Kahf will be protected from the Dajjal."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৮০৯", "en": "Sahih Muslim 809"}}, {"type": "note", "tone": "info", "text": {"bn": "একই হাদিসের এক বর্ণনায় “শেষ দশ আয়াত” এসেছে; তাই আলেমরা প্রথম ও শেষ দুই দশ আয়াতই মুখস্থ করার পরামর্শ দেন।", "en": "One narration of the same hadith says “the last ten verses,” so scholars advise memorising both the first and last ten."}}, {"type": "heading", "text": {"bn": "জুমার দিনে সূরা কাহফ", "en": "Al-Kahf on Friday"}}, {"type": "text", "text": {"bn": "আবু সাঈদ খুদরি (রা.) থেকে বর্ণিত: যে জুমার দিন সূরা কাহফ পড়ে, তার জন্য দুই জুমার মাঝখানের সময় নূর দিয়ে আলোকিত করে দেওয়া হয়।", "en": "From Abu Sa''id al-Khudri (RA): whoever recites Surah Al-Kahf on Friday, light will shine for him between the two Fridays."}}, {"type": "ref", "text": {"bn": "মুস্তাদরাক হাকিম; শুআবুল ঈমান / সুনানুল কুবরা, বায়হাকি", "en": "Al-Mustadrak, al-Hakim; Shu''ab al-Iman / As-Sunan al-Kubra, al-Bayhaqi"}, "check": true}, {"type": "note", "tone": "info", "text": {"bn": "এই বর্ণনাকে আলবানিসহ অনেক মুহাদ্দিস সহিহ বলেছেন। কেউ কেউ বলেন এটি মূলত আবু সাঈদ (রা.)-এর কথা (মাওকুফ); তবে এমন বিষয় সাহাবি নিজে থেকে বলেন না, তাই এর হুকুম রাসুল ﷺ-এর কথার মতো বলে তাঁরা মনে করেন।", "en": "Many hadith scholars, including al-Albani, graded this sahih. Some say it is the words of Abu Sa''id (mawquf), but since a Companion would not say this from opinion, it carries the ruling of the Prophet''s ﷺ words."}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "জুমার দিন শুরু হয় বৃহস্পতিবার সূর্যাস্তের পর থেকে এবং শেষ হয় শুক্রবার সূর্যাস্তে; এর মধ্যে যেকোনো সময় পড়া যায়।", "en": "Friday runs from sunset on Thursday to sunset on Friday; you may recite it any time in between."}}]', 'in_review', 120 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'da43853e-499e-52df-816c-5f55bf6fb100', id, 'fazilat-tasbih', '{"bn": "সুবহানাল্লাহ ও অন্যান্য তাসবিহের ফজিলত", "en": "Virtues of SubhanAllah and other tasbih"}', '{"bn": "জিহ্বায় হালকা কিন্তু মিজানে ভারী দুটি বাক্য, দিনে একশ বার তাসবিহ এবং নামাজের পরের তাসবিহের ফজিলত।", "en": "Two phrases light on the tongue but heavy on the scale, a hundred tasbih a day, and the dhikr after prayer."}', 'basic', '[{"type": "arabic", "label": {"bn": "দিনে ১০০ বার", "en": "100 times a day"}, "ar": "سُبْحَانَ اللّٰهِ وَبِحَمْدِهِ", "pron": {"bn": "সুবহানাল্লাহি ওয়া বিহামদিহী", "en": "Subhanallahi wa bihamdihi"}, "meaning": {"bn": "আল্লাহ পবিত্র, আর সব প্রশংসা তাঁরই।", "en": "Glory be to Allah and praise be to Him."}, "ref": {"bn": "সহিহ বুখারি ৬৪০৫", "en": "Sahih al-Bukhari 6405"}}, {"type": "text", "text": {"bn": "যে দিনে একশ বার “সুবহানাল্লাহি ওয়া বিহামদিহী” বলে, তার গুনাহ সমুদ্রের ফেনার সমান হলেও মাফ করে দেওয়া হয়।", "en": "Whoever says “Subhanallahi wa bihamdihi” a hundred times a day, his sins are forgiven even if they are like the foam of the sea."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৪০৫; সহিহ মুসলিম ২৬৯১", "en": "Sahih al-Bukhari 6405; Sahih Muslim 2691"}}, {"type": "arabic", "ar": "سُبْحَانَ اللّٰهِ وَبِحَمْدِهِ، سُبْحَانَ اللّٰهِ الْعَظِيمِ", "pron": {"bn": "সুবহানাল্লাহি ওয়া বিহামদিহী, সুবহানাল্লাহিল আযীম", "en": "Subhanallahi wa bihamdihi, subhanallahil-''azim"}, "meaning": {"bn": "আল্লাহ পবিত্র ও সব প্রশংসা তাঁর; মহান আল্লাহ পবিত্র।", "en": "Glory be to Allah and praise be to Him; glory be to Allah the Magnificent."}, "ref": {"bn": "সহিহ বুখারি ৭৫৬৩", "en": "Sahih al-Bukhari 7563"}}, {"type": "text", "text": {"bn": "দুটি বাক্য জিহ্বায় হালকা, মিজানে ভারী এবং দয়াময় আল্লাহর কাছে প্রিয়: “সুবহানাল্লাহি ওয়া বিহামদিহী, সুবহানাল্লাহিল আযীম।” (এটি সহিহ বুখারির সর্বশেষ হাদিস।)", "en": "Two phrases are light on the tongue, heavy on the scale and beloved to the Most Merciful: “Subhanallahi wa bihamdihi, subhanallahil-''azim.” (It is the last hadith in Sahih al-Bukhari.)"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৭৫৬৩; সহিহ মুসলিম ২৬৯৪", "en": "Sahih al-Bukhari 7563; Sahih Muslim 2694"}}, {"type": "heading", "text": {"bn": "চারটি প্রিয় বাক্য", "en": "Four beloved phrases"}}, {"type": "arabic", "ar": "سُبْحَانَ اللّٰهِ، وَالْحَمْدُ لِلّٰهِ، وَلَا إِلٰهَ إِلَّا اللّٰهُ، وَاللّٰهُ أَكْبَرُ", "pron": {"bn": "সুবহানাল্লাহ, ওয়াল হামদুলিল্লাহ, ওয়া লা ইলাহা ইল্লাল্লাহু, ওয়াল্লাহু আকবার", "en": "Subhanallah, wal-hamdu lillah, wa la ilaha illallah, wallahu akbar"}, "meaning": {"bn": "আল্লাহ পবিত্র, সব প্রশংসা আল্লাহর, আল্লাহ ছাড়া কোনো সত্য ইলাহ নেই, আল্লাহ সর্বশ্রেষ্ঠ।", "en": "Glory be to Allah, praise be to Allah, there is no god but Allah, Allah is the Greatest."}, "ref": {"bn": "সহিহ মুসলিম ২১৩৭", "en": "Sahih Muslim 2137"}}, {"type": "text", "text": {"bn": "আল্লাহর কাছে সবচেয়ে প্রিয় বাক্য এই চারটি; যেটি দিয়েই শুরু করো, কোনো ক্ষতি নেই। রাসুল ﷺ বলেছেন, এগুলো বলা আমার কাছে সূর্য যা কিছুর ওপর উদিত হয় তার চেয়েও প্রিয়।", "en": "These four are the most beloved words to Allah, in any order. The Prophet ﷺ said saying them is dearer to him than all the sun rises upon."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২১৩৭; সহিহ মুসলিম ২৬৯৫", "en": "Sahih Muslim 2137; Sahih Muslim 2695"}}, {"type": "text", "text": {"bn": "“আলহামদুলিল্লাহ” মিজান পূর্ণ করে দেয়, আর “সুবহানাল্লাহ ওয়াল হামদুলিল্লাহ” আসমান-জমিনের মাঝখান পূর্ণ করে দেয়।", "en": "“Al-hamdu lillah” fills the scale, and “Subhanallah wal-hamdu lillah” fill what is between the heavens and the earth."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২২৩", "en": "Sahih Muslim 223"}}, {"type": "arabic", "label": {"bn": "জান্নাতের গুপ্তধন", "en": "A treasure of Paradise"}, "ar": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ", "pron": {"bn": "লা হাওলা ওয়ালা কুওয়াতা ইল্লা বিল্লাহ", "en": "La hawla wa la quwwata illa billah"}, "meaning": {"bn": "আল্লাহর সাহায্য ছাড়া কোনো উপায় ও শক্তি নেই।", "en": "There is no might nor power except with Allah."}, "ref": {"bn": "সহিহ বুখারি ৪২০৫; সহিহ মুসলিম ২৭০৪", "en": "Sahih al-Bukhari 4205; Sahih Muslim 2704"}}, {"type": "heading", "text": {"bn": "নামাজের পর তাসবিহ", "en": "Tasbih after prayer"}}, {"type": "text", "text": {"bn": "যে প্রত্যেক নামাজের পর ৩৩ বার সুবহানাল্লাহ, ৩৩ বার আলহামদুলিল্লাহ, ৩৩ বার আল্লাহু আকবার বলে, আর একশ পূর্ণ করতে বলে “লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহু, লাহুল মুলকু ওয়া লাহুল হামদু ওয়া হুওয়া আলা কুল্লি শাইয়িন কাদীর”, তার গুনাহ সমুদ্রের ফেনার সমান হলেও মাফ হয়ে যায়।", "en": "Whoever after every prayer says SubhanAllah 33 times, Alhamdulillah 33 times, Allahu Akbar 33 times, and completes the hundred with “La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa ''ala kulli shay''in qadir,” his sins are forgiven even if like the foam of the sea."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৫৯৭", "en": "Sahih Muslim 597"}}]', 'in_review', 130 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '1e79f9f5-ca00-526b-8c5b-d781d29aa233', id, 'fazilat-la-ilaha-illallah', '{"bn": "লা ইলাহা ইল্লাল্লাহর ফজিলত", "en": "Virtues of La ilaha illallah"}', '{"bn": "সর্বোত্তম জিকির “লা ইলাহা ইল্লাল্লাহ”; দিনে একশ বার তাহলিলের বিরাট সওয়াব এবং শেষ কথা হিসেবে এর মর্যাদা।", "en": "The best dhikr is “La ilaha illallah”; the great reward of saying the tahlil a hundred times a day, and its worth as one''s last words."}', 'basic', '[{"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: সর্বোত্তম জিকির “লা ইলাহা ইল্লাল্লাহ”, আর সর্বোত্তম দোয়া “আলহামদুলিল্লাহ”।", "en": "The best remembrance is “La ilaha illallah,” and the best supplication is “Al-hamdu lillah.”"}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ৩৩৮৩", "en": "Jami'' at-Tirmidhi 3383"}}, {"type": "text", "text": {"bn": "ঈমানের সত্তরের বেশি শাখা আছে; এর সর্বোচ্চটি “লা ইলাহা ইল্লাল্লাহ” বলা।", "en": "Faith has seventy-odd branches; the highest is saying “La ilaha illallah.”"}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৩৫", "en": "Sahih Muslim 35"}}, {"type": "arabic", "label": {"bn": "দিনে ১০০ বার", "en": "100 times a day"}, "ar": "لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلٰى كُلِّ شَيْءٍ قَدِيرٌ", "pron": {"bn": "লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারীকা লাহু, লাহুল মুলকু ওয়া লাহুল হামদু, ওয়া হুওয়া আলা কুল্লি শাইয়িন কাদীর", "en": "La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamd, wa huwa ''ala kulli shay''in qadir"}, "meaning": {"bn": "আল্লাহ ছাড়া কোনো সত্য ইলাহ নেই, তিনি এক, তাঁর কোনো শরিক নেই; রাজত্ব তাঁরই, প্রশংসাও তাঁর, আর তিনি সবকিছুর ওপর ক্ষমতাবান।", "en": "There is no god but Allah alone, without partner; His is the dominion and His is the praise, and He has power over all things."}, "ref": {"bn": "সহিহ বুখারি ৩২৯৩; সহিহ মুসলিম ২৬৯১", "en": "Sahih al-Bukhari 3293; Sahih Muslim 2691"}}, {"type": "text", "text": {"bn": "যে দিনে একশ বার এটি বলে, সে দশটি গোলাম আজাদ করার সমান সওয়াব পায়, তার জন্য একশ নেকি লেখা হয়, একশ গুনাহ মুছে দেওয়া হয়, আর সেদিন সন্ধ্যা পর্যন্ত সে শয়তান থেকে সুরক্ষিত থাকে। এর চেয়ে বেশি আমলকারী ছাড়া কেউ তার চেয়ে উত্তম আমল নিয়ে আসবে না।", "en": "Whoever says it a hundred times a day gets the reward of freeing ten slaves, a hundred good deeds are written for him, a hundred sins erased, and he is protected from Shaytan that day until evening; no one brings better except one who did more."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৩২৯৩; সহিহ মুসলিম ২৬৯১", "en": "Sahih al-Bukhari 3293; Sahih Muslim 2691"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: কিয়ামতের দিন আমার শাফায়াতের সবচেয়ে সৌভাগ্যবান সে, যে অন্তর থেকে একনিষ্ঠভাবে “লা ইলাহা ইল্লাল্লাহ” বলেছে।", "en": "The happiest of people with my intercession on the Day of Resurrection is the one who said “La ilaha illallah” sincerely from his heart."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৯৯", "en": "Sahih al-Bukhari 99"}}, {"type": "text", "text": {"bn": "যার শেষ কথা “লা ইলাহা ইল্লাল্লাহ” হবে, সে জান্নাতে প্রবেশ করবে।", "en": "Whoever''s last words are “La ilaha illallah” will enter Paradise."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ৩১১৬", "en": "Sunan Abi Dawud 3116"}}, {"type": "note", "tone": "tip", "text": {"bn": "মুমূর্ষু ব্যক্তির পাশে নরমভাবে কালিমা পড়ুন যাতে তিনি শুনে বলতে পারেন; তাঁকে জোর করে বারবার বলতে বলবেন না।", "en": "Beside a dying person, gently say the kalimah so they can hear and repeat it; do not press them repeatedly."}}]', 'in_review', 140 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '19e3d083-2e81-5164-b14a-22e6b810042a', id, 'fazilat-istighfar', '{"bn": "ইস্তিগফার ও সাইয়িদুল ইস্তিগফারের ফজিলত", "en": "Virtues of istighfar and Sayyid al-Istighfar"}', '{"bn": "রাসুল ﷺ নিজে দিনে সত্তর-একশ বার ইস্তিগফার করতেন; সাইয়িদুল ইস্তিগফার দৃঢ় বিশ্বাসে পড়ে মারা গেলে জান্নাত।", "en": "The Prophet ﷺ himself sought forgiveness seventy to a hundred times a day; whoever says Sayyid al-Istighfar with certainty and dies that day enters Paradise."}', 'basic', '[{"type": "text", "text": {"bn": "নূহ (আ.) তাঁর জাতিকে বলেছিলেন: “তোমাদের রবের কাছে ক্ষমা চাও, নিশ্চয়ই তিনি মহাক্ষমাশীল। তিনি তোমাদের ওপর প্রচুর বৃষ্টি পাঠাবেন, ধন-সম্পদ ও সন্তান দিয়ে সাহায্য করবেন, তোমাদের জন্য বাগান ও নদী দেবেন।”", "en": "Nuh (AS) told his people: “Ask forgiveness of your Lord; He is ever Forgiving. He will send rain upon you in abundance, give you wealth and children, and provide for you gardens and rivers.”"}}, {"type": "ref", "text": {"bn": "সূরা নূহ ৭১:১০–১২", "en": "Nuh 71:10–12"}}, {"type": "arabic", "ar": "أَسْتَغْفِرُ اللّٰهَ وَأَتُوبُ إِلَيْهِ", "pron": {"bn": "আস্তাগফিরুল্লাহা ওয়া আতূবু ইলাইহি", "en": "Astaghfirullaha wa atubu ilayh"}, "meaning": {"bn": "আমি আল্লাহর কাছে ক্ষমা চাই এবং তাঁর কাছে তওবা করি।", "en": "I seek Allah''s forgiveness and turn to Him in repentance."}, "ref": {"bn": "সহিহ বুখারি ৬৩০৭", "en": "Sahih al-Bukhari 6307"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: আল্লাহর কসম, আমি দিনে সত্তর বারের বেশি আল্লাহর কাছে ক্ষমা চাই ও তওবা করি। অন্য বর্ণনায়: হে লোকসকল, আল্লাহর কাছে তওবা করো; আমি দিনে একশ বার তওবা করি।", "en": "By Allah, I seek Allah''s forgiveness and repent to Him more than seventy times a day. In another narration: O people, repent to Allah, for I repent a hundred times a day."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৩০৭; সহিহ মুসলিম ২৭০২", "en": "Sahih al-Bukhari 6307; Sahih Muslim 2702"}}, {"type": "text", "text": {"bn": "যাঁর হাতে আমার প্রাণ, তাঁর কসম, তোমরা যদি গুনাহ না করতে, আল্লাহ তোমাদের সরিয়ে এমন জাতি আনতেন যারা গুনাহ করে আল্লাহর কাছে ক্ষমা চাইত, আর তিনি তাদের ক্ষমা করতেন।", "en": "By Him in whose hand is my soul, if you did not sin, Allah would replace you with people who sin and then seek His forgiveness, and He would forgive them."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৭৪৯", "en": "Sahih Muslim 2749"}}, {"type": "heading", "text": {"bn": "সাইয়িদুল ইস্তিগফার", "en": "Sayyid al-Istighfar"}}, {"type": "arabic", "label": {"bn": "সাইয়িদুল ইস্তিগফার", "en": "Sayyid al-Istighfar"}, "ar": "اللّٰهُمَّ أَنْتَ رَبِّي لَا إِلٰهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلٰى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ لَكَ بِذَنْبِي، فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ", "pron": {"bn": "আল্লাহুম্মা আনতা রব্বী, লা ইলাহা ইল্লা আনতা, খালাকতানী ওয়া আনা আবদুকা, ওয়া আনা আলা আহদিকা ওয়া ওয়া''দিকা মাসতাতা''তু, আউযু বিকা মিন শাররি মা সানা''তু, আবূউ লাকা বিনি''মাতিকা আলাইয়্যা, ওয়া আবূউ লাকা বিযামবী, ফাগফির লী, ফাইন্নাহু লা ইয়াগফিরুয যুনূবা ইল্লা আনতা", "en": "Allahumma anta rabbi, la ilaha illa ant, khalaqtani wa ana ''abduk, wa ana ''ala ''ahdika wa wa''dika mastata''t, a''udhu bika min sharri ma sana''t, abu''u laka bi-ni''matika ''alayy, wa abu''u laka bi-dhanbi, faghfir li, fa-innahu la yaghfirudh-dhunuba illa ant"}, "meaning": {"bn": "হে আল্লাহ, আপনি আমার রব, আপনি ছাড়া কোনো সত্য ইলাহ নেই। আপনি আমাকে সৃষ্টি করেছেন, আমি আপনার বান্দা। আমি সাধ্যমতো আপনার সঙ্গে করা অঙ্গীকার ও ওয়াদার ওপর আছি। আমার কৃতকর্মের অনিষ্ট থেকে আপনার আশ্রয় চাই। আমার ওপর আপনার নিয়ামত স্বীকার করছি এবং আমার গুনাহও স্বীকার করছি। আমাকে ক্ষমা করুন, কারণ আপনি ছাড়া কেউ গুনাহ ক্ষমা করতে পারে না।", "en": "O Allah, You are my Lord; there is no god but You. You created me and I am Your servant, and I keep Your covenant and promise as best I can. I seek refuge in You from the evil of what I have done. I acknowledge Your favour upon me and I acknowledge my sin, so forgive me, for none forgives sins but You."}, "ref": {"bn": "সহিহ বুখারি ৬৩০৬", "en": "Sahih al-Bukhari 6306"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: যে দৃঢ় বিশ্বাসের সঙ্গে দিনের বেলা এটি পড়ে সন্ধ্যার আগে মারা যায়, সে জান্নাতি; আর যে রাতে দৃঢ় বিশ্বাসের সঙ্গে পড়ে সকালের আগে মারা যায়, সেও জান্নাতি।", "en": "Whoever says it during the day with firm faith and dies before evening is among the people of Paradise; and whoever says it at night with firm faith and dies before morning is among the people of Paradise."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৩০৬", "en": "Sahih al-Bukhari 6306"}}, {"type": "note", "tone": "warn", "text": {"bn": "“যে নিয়মিত ইস্তিগফার করে, আল্লাহ তাকে সব সংকট থেকে মুক্তির পথ ও অপ্রত্যাশিত রিজিক দেন” — এই প্রসিদ্ধ হাদিসটি সুনান আবু দাউদে আছে, তবে বর্ণনাকারী অজ্ঞাত হওয়ায় অনেক মুহাদ্দিস একে দুর্বল বলেছেন। ইস্তিগফারের বরকতের জন্য সূরা নূহের আয়াতগুলোই যথেষ্ট প্রমাণ।", "en": "The popular hadith “whoever holds to istighfar, Allah gives him a way out of every distress and provision from where he does not expect” is in Sunan Abi Dawud, but many scholars graded it weak due to an unknown narrator. The verses of Surah Nuh are sufficient evidence for the blessings of istighfar."}, "check": true}]', 'in_review', 150 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'bc8af39e-1d50-5c5b-9303-e4539ae3f690', id, 'fazilat-durood', '{"bn": "রাসুল ﷺ-এর ওপর দরুদ পড়ার ফজিলত", "en": "Virtues of sending salawat on the Prophet ﷺ"}', '{"bn": "একবার দরুদ পড়লে আল্লাহ দশটি রহমত পাঠান; সহিহ হাদিসে শেখানো দরুদ এবং ভিত্তিহীন দরুদ সম্পর্কে সতর্কতা।", "en": "One salawat brings ten blessings from Allah; the salawat taught in sahih hadith, and a caution about baseless ones."}', 'basic', '[{"type": "arabic", "ar": "إِنَّ اللّٰهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ ۚ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا", "pron": {"bn": "ইন্নাল্লাহা ওয়া মালাইকাতাহু ইউসাল্লূনা আলান নাবিয়্যি, ইয়া আইয়্যুহাল্লাযীনা আমানূ সাল্লূ আলাইহি ওয়া সাল্লিমূ তাসলীমা", "en": "Innallaha wa mala''ikatahu yusalluna ''alan-nabiyy, ya ayyuhal-ladhina amanu sallu ''alayhi wa sallimu taslima"}, "meaning": {"bn": "নিশ্চয়ই আল্লাহ ও তাঁর ফেরেশতারা নবীর ওপর রহমত পাঠান। হে মুমিনগণ, তোমরাও তাঁর ওপর দরুদ পাঠাও এবং যথাযথভাবে সালাম পাঠাও।", "en": "Indeed, Allah and His angels send blessings upon the Prophet. O you who believe, send blessings upon him and greet him with peace."}, "ref": {"bn": "সূরা আহযাব ৩৩:৫৬", "en": "Al-Ahzab 33:56"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: যে আমার ওপর একবার দরুদ পড়ে, আল্লাহ তার ওপর দশবার রহমত নাজিল করেন।", "en": "Whoever sends blessings on me once, Allah sends blessings on him ten times."}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ৪০৮", "en": "Sahih Muslim 408"}}, {"type": "text", "text": {"bn": "অন্য বর্ণনায় আছে: তার দশটি গুনাহ মাফ হয় এবং দশটি মর্যাদা বাড়ানো হয়।", "en": "Another narration adds: ten sins are erased from him and he is raised ten degrees."}}, {"type": "ref", "text": {"bn": "সুনান নাসায়ি", "en": "Sunan an-Nasa''i"}, "check": true}, {"type": "text", "text": {"bn": "প্রকৃত কৃপণ সেই ব্যক্তি, যার সামনে আমার নাম উল্লেখ করা হলো অথচ সে আমার ওপর দরুদ পড়ল না।", "en": "The true miser is the one in whose presence I am mentioned and he does not send blessings on me."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি", "en": "Jami'' at-Tirmidhi"}, "check": true}, {"type": "heading", "text": {"bn": "দরুদে ইবরাহিমি", "en": "The Ibrahimi salawat"}}, {"type": "arabic", "label": {"bn": "সাহাবিদের শেখানো দরুদ", "en": "The salawat taught to the Companions"}, "ar": "اللّٰهُمَّ صَلِّ عَلٰى مُحَمَّدٍ وَعَلٰى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلٰى إِبْرَاهِيمَ وَعَلٰى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللّٰهُمَّ بَارِكْ عَلٰى مُحَمَّدٍ وَعَلٰى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلٰى إِبْرَاهِيمَ وَعَلٰى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ", "pron": {"bn": "আল্লাহুম্মা সাল্লি আলা মুহাম্মাদিওঁ ওয়া আলা আলি মুহাম্মাদ, কামা সাল্লাইতা আলা ইবরাহীমা ওয়া আলা আলি ইবরাহীম, ইন্নাকা হামীদুম মাজীদ। আল্লাহুম্মা বারিক আলা মুহাম্মাদিওঁ ওয়া আলা আলি মুহাম্মাদ, কামা বারাকতা আলা ইবরাহীমা ওয়া আলা আলি ইবরাহীম, ইন্নাকা হামীদুম মাজীদ।", "en": "Allahumma salli ''ala Muhammadin wa ''ala ali Muhammad, kama sallayta ''ala Ibrahima wa ''ala ali Ibrahim, innaka Hamidun Majid. Allahumma barik ''ala Muhammadin wa ''ala ali Muhammad, kama barakta ''ala Ibrahima wa ''ala ali Ibrahim, innaka Hamidun Majid."}, "meaning": {"bn": "হে আল্লাহ, মুহাম্মাদ ও তাঁর পরিবারের ওপর রহমত পাঠান, যেমন আপনি ইবরাহিম ও তাঁর পরিবারের ওপর রহমত পাঠিয়েছেন; নিশ্চয়ই আপনি প্রশংসিত, মহিমান্বিত। হে আল্লাহ, মুহাম্মাদ ও তাঁর পরিবারের ওপর বরকত দিন, যেমন আপনি ইবরাহিম ও তাঁর পরিবারের ওপর বরকত দিয়েছেন; নিশ্চয়ই আপনি প্রশংসিত, মহিমান্বিত।", "en": "O Allah, send blessings on Muhammad and the family of Muhammad as You sent blessings on Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious. O Allah, bless Muhammad and the family of Muhammad as You blessed Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious."}, "ref": {"bn": "সহিহ বুখারি ৩৩৭০", "en": "Sahih al-Bukhari 3370"}}, {"type": "text", "text": {"bn": "সাহাবিরা জিজ্ঞেস করেছিলেন, আমরা আপনার ওপর কীভাবে দরুদ পড়ব? তখন রাসুল ﷺ এই দরুদ শিখিয়ে দেন। তাই এটিই সর্বোত্তম দরুদ; ছোট করে “সাল্লাল্লাহু আলাইহি ওয়া সাল্লাম” বলাও দরুদ।", "en": "The Companions asked how to send blessings on him, and he ﷺ taught them this; so it is the best form. Saying “sallallahu ''alayhi wa sallam” briefly is also salawat."}}, {"type": "note", "tone": "warn", "text": {"bn": "বিভিন্ন পুস্তিকায় নির্দিষ্ট নামের দরুদের জন্য অস্বাভাবিক ফজিলত লেখা থাকে (যেমন: একবার পড়লে লাখ দরুদের সওয়াব)। এ ধরনের বেশিরভাগ ফজিলতের কোনো নির্ভরযোগ্য সনদ নেই। সহিহ হাদিসে শেখানো দরুদই যথেষ্ট ও উত্তম।", "en": "Some booklets attach extraordinary rewards to specially named salawat (e.g. “one recitation equals a hundred thousand”). Most of these have no reliable chain. The salawat taught in sahih hadith is sufficient and best."}}, {"type": "note", "tone": "tip", "text": {"bn": "জুমার দিনে বেশি বেশি দরুদ পড়ার বিশেষ নির্দেশ আছে; জুমার গাইড দেখুন।", "en": "There is a special instruction to increase salawat on Friday; see the Friday guide."}}]', 'in_review', 160 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'cfce21f4-237e-53c6-85f3-295d51ab4f22', id, 'fazilat-dua', '{"bn": "দোয়ার ফজিলত ও কবুলের সময়", "en": "Virtues of dua and times of acceptance"}', '{"bn": "দোয়াই ইবাদত; আল্লাহ নিকটে আছেন এবং সাড়া দেন। কোন কোন সময় দোয়া কবুলের বেশি আশা করা যায়।", "en": "Dua is worship; Allah is near and answers. The times when dua is most hoped to be accepted."}', 'basic', '[{"type": "arabic", "ar": "وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ", "pron": {"bn": "ওয়া কালা রব্বুকুমুদ''ঊনী আসতাজিব লাকুম", "en": "Wa qala rabbukumud''uni astajib lakum"}, "meaning": {"bn": "তোমাদের রব বলেছেন: তোমরা আমাকে ডাকো, আমি তোমাদের ডাকে সাড়া দেব।", "en": "Your Lord has said: Call upon Me; I will respond to you."}, "ref": {"bn": "সূরা গাফির ৪০:৬০", "en": "Ghafir 40:60"}}, {"type": "text", "text": {"bn": "আল্লাহ বলেন: “আমার বান্দারা যখন তোমাকে আমার সম্পর্কে জিজ্ঞেস করে, (বলো) আমি নিকটেই আছি; আহ্বানকারী যখন আমাকে ডাকে, আমি তার ডাকে সাড়া দিই।”", "en": "Allah says: “When My servants ask you about Me, I am near; I respond to the call of the caller when he calls on Me.”"}}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:১৮৬", "en": "Al-Baqarah 2:186"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: “দোয়াই ইবাদত।” তারপর তিনি উপরের আয়াতটি (৪০:৬০) পড়লেন।", "en": "The Prophet ﷺ said: “Supplication is worship,” then recited the verse above (40:60)."}}, {"type": "ref", "text": {"bn": "সুনান আবু দাউদ ১৪৭৯; সুনান তিরমিজি ২৯৬৯", "en": "Sunan Abi Dawud 1479; Jami'' at-Tirmidhi 2969"}}, {"type": "note", "tone": "info", "text": {"bn": "প্রচলিত বাক্য “দোয়া ইবাদতের মগজ (সার)” তিরমিজিতে এসেছে, কিন্তু এর সনদ দুর্বল; সহিহ শব্দ হলো “দোয়াই ইবাদত”।", "en": "The popular wording “dua is the marrow of worship” is in Tirmidhi but its chain is weak; the sahih wording is “dua is worship.”"}, "check": true}, {"type": "text", "text": {"bn": "কোনো মুসলিম যখন গুনাহ বা আত্মীয়তা ছিন্ন করার দোয়া ছাড়া অন্য কোনো দোয়া করে, আল্লাহ তাকে তিনটির একটি দেন: দ্রুত দোয়া কবুল করেন, অথবা আখিরাতের জন্য জমা রাখেন, অথবা সমপরিমাণ কোনো বিপদ দূর করে দেন।", "en": "Whenever a Muslim makes a dua that involves no sin or cutting of kinship, Allah gives him one of three: an answer soon, a reward stored for the Hereafter, or an equal harm turned away from him."}}, {"type": "ref", "text": {"bn": "মুসনাদ আহমাদ", "en": "Musnad Ahmad"}, "check": true}, {"type": "text", "text": {"bn": "তোমাদের দোয়া কবুল হয়, যতক্ষণ না কেউ তাড়াহুড়া করে বলে: “আমি দোয়া করলাম, কিন্তু কবুল হলো না।”", "en": "Your dua is answered as long as you are not hasty, saying: “I prayed but was not answered.”"}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৬৩৪০; সহিহ মুসলিম ২৭৩৫", "en": "Sahih al-Bukhari 6340; Sahih Muslim 2735"}}, {"type": "text", "text": {"bn": "কোনো মুসলিম তার ভাইয়ের অনুপস্থিতিতে তার জন্য দোয়া করলে একজন ফেরেশতা বলেন: “আমিন, আর তোমার জন্যও তেমনই হোক।”", "en": "When a Muslim prays for his brother in his absence, an angel says: “Amin, and for you the same.”"}}, {"type": "ref", "text": {"bn": "সহিহ মুসলিম ২৭৩৩", "en": "Sahih Muslim 2733"}}, {"type": "heading", "text": {"bn": "দোয়া কবুলের বিশেষ সময়", "en": "Special times of acceptance"}}, {"type": "list", "items": [{"bn": "রাতের শেষ তৃতীয়াংশ (সহিহ বুখারি ১১৪৫)", "en": "The last third of the night (Sahih al-Bukhari 1145)"}, {"bn": "সিজদারত অবস্থায়; বান্দা সিজদায় রবের সবচেয়ে নিকটে থাকে (সহিহ মুসলিম ৪৮২)", "en": "In sujood; the servant is closest to his Lord in prostration (Sahih Muslim 482)"}, {"bn": "জুমার দিনের বিশেষ মুহূর্ত (সহিহ বুখারি ৯৩৫)", "en": "The special hour on Friday (Sahih al-Bukhari 935)"}, {"bn": "আরাফার দিন (সুনান তিরমিজি)", "en": "The Day of Arafah (Jami'' at-Tirmidhi)"}, {"bn": "আজান ও ইকামতের মাঝখানে (সুনান আবু দাউদ, সুনান তিরমিজি)", "en": "Between the adhan and the iqamah (Sunan Abi Dawud, Jami'' at-Tirmidhi)"}]}, {"type": "note", "tone": "info", "text": {"bn": "শেষ দুটি সময়ের হাদিস সুনান গ্রন্থে আছে এবং বেশিরভাগ মুহাদ্দিস এগুলোকে সহিহ বা হাসান বলেছেন।", "en": "The hadiths for the last two times are in the Sunan collections and most hadith scholars graded them sahih or hasan."}, "check": true}, {"type": "note", "tone": "tip", "text": {"bn": "দোয়ার আগে আল্লাহর প্রশংসা ও দরুদ পড়ুন, মন দিয়ে ও দৃঢ় আশা নিয়ে চান, আর হালাল উপার্জনের খেয়াল রাখুন।", "en": "Begin with praise of Allah and salawat, ask with presence of heart and firm hope, and keep your earnings halal."}}]', 'in_review', 170 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT '52f9d37d-82c9-52e8-8c1c-4f6693d76fcf', id, 'fazilat-asmaul-husna', '{"bn": "আল্লাহর নামসমূহ মুখস্থ করার ফজিলত", "en": "Virtue of learning the names of Allah"}', '{"bn": "আল্লাহর নিরানব্বইটি নাম আছে, যে এগুলো আয়ত্ত করবে সে জান্নাতে যাবে; প্রচলিত তালিকাটি কোথা থেকে এসেছে তাও জানুন।", "en": "Allah has ninety-nine names, and whoever comprehends them will enter Paradise; also learn where the popular list comes from."}', 'basic', '[{"type": "arabic", "ar": "وَلِلّٰهِ الْأَسْمَاءُ الْحُسْنٰى فَادْعُوهُ بِهَا", "pron": {"bn": "ওয়া লিল্লাহিল আসমাউল হুসনা ফাদ''ঊহু বিহা", "en": "Wa lillahil-asma''ul-husna fad''uhu biha"}, "meaning": {"bn": "আর আল্লাহর রয়েছে সুন্দরতম নামসমূহ; সুতরাং সেগুলো দিয়ে তাঁকে ডাকো।", "en": "And to Allah belong the best names, so call upon Him by them."}, "ref": {"bn": "সূরা আ''রাফ ৭:১৮০", "en": "Al-A''raf 7:180"}}, {"type": "text", "text": {"bn": "রাসুল ﷺ বলেছেন: আল্লাহর নিরানব্বইটি নাম আছে, একশ থেকে এক কম। যে এগুলো আয়ত্ত করবে (আহসাহা), সে জান্নাতে প্রবেশ করবে।", "en": "The Prophet ﷺ said: Allah has ninety-nine names, one hundred less one. Whoever comprehends them (ahsaha) will enter Paradise."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ২৭৩৬; সহিহ মুসলিম ২৬৭৭", "en": "Sahih al-Bukhari 2736; Sahih Muslim 2677"}}, {"type": "heading", "text": {"bn": "“আয়ত্ত করা” মানে কী", "en": "What “comprehending” means"}}, {"type": "text", "text": {"bn": "আলেমরা “আহসাহা” শব্দের ব্যাখ্যায় কয়েকটি স্তর বলেছেন; সব মিলিয়েই পূর্ণ ফজিলত আশা করা যায়:", "en": "Scholars explain “ahsaha” in several levels; together they bring the full virtue:"}}, {"type": "list", "items": [{"bn": "নামগুলো মুখস্থ ও গুনে রাখা।", "en": "Memorising and counting the names."}, {"bn": "প্রতিটি নামের অর্থ বোঝা ও তা বিশ্বাস করা।", "en": "Understanding each name''s meaning and believing in it."}, {"bn": "নামগুলো দিয়ে আল্লাহকে ডাকা, যেমন ক্ষমা চাইতে “ইয়া গাফুর”, রিজিক চাইতে “ইয়া রায্যাক”।", "en": "Calling on Allah by them, e.g. “Ya Ghafur” when seeking forgiveness, “Ya Razzaq” when asking for provision."}, {"bn": "নামগুলোর দাবি অনুযায়ী জীবন চালানো, যেমন “আস-সামী” জেনে মুখ সংযত রাখা।", "en": "Living by what they imply, e.g. guarding the tongue knowing He is As-Sami''."}]}, {"type": "heading", "text": {"bn": "৯৯ নামের তালিকা কোথা থেকে", "en": "Where the list of 99 comes from"}}, {"type": "text", "text": {"bn": "“আল্লাহর নিরানব্বইটি নাম আছে” — এই হাদিস সহিহ বুখারি ও সহিহ মুসলিমে আছে, এবং এটি সম্পূর্ণ সহিহ। তবে বুখারি-মুসলিমের বর্ণনায় নামগুলোর তালিকা নেই।", "en": "The hadith “Allah has ninety-nine names” is in Sahih al-Bukhari and Sahih Muslim and is fully sahih. But their narrations do not list the names."}}, {"type": "text", "text": {"bn": "প্রচলিত ৯৯ নামের তালিকাটি এসেছে সুনান তিরমিজির (৩৫০৭) বর্ণনা থেকে। ইমাম তিরমিজি নিজেই একে “গরিব” বলেছেন, আর অনেক মুহাদ্দিসের মতে তালিকাটি রাসুল ﷺ-এর কথা নয়, বরং কোনো বর্ণনাকারী নামগুলো কুরআন-হাদিস থেকে সংকলন করে যুক্ত করেছেন। তাই তালিকাটির সনদ অনেকের মতে দুর্বল।", "en": "The popular list of 99 comes from the narration in Jami'' at-Tirmidhi (3507). At-Tirmidhi himself called it gharib, and many hadith scholars hold that the list is not the Prophet''s ﷺ words but was compiled from the Quran and Sunnah and inserted by a narrator. So many consider the list itself weak."}}, {"type": "ref", "text": {"bn": "সুনান তিরমিজি ৩৫০৭", "en": "Jami'' at-Tirmidhi 3507"}}, {"type": "note", "tone": "info", "text": {"bn": "তালিকার প্রায় সব নামই কুরআন বা সহিহ হাদিসে নাম বা গুণ হিসেবে এসেছে, তাই এগুলো মুখস্থ করা ও এগুলো দিয়ে দোয়া করা ভালো আমল। তিরমিজির বিভিন্ন সংস্করণে সামান্য পার্থক্যও আছে (যেমন কোথাও “আল-আহাদ” নেই)। এই অ্যাপে প্রচলিত ক্রম অনুসরণ করা হয়েছে।", "en": "Almost every name in the list occurs in the Quran or sahih hadith as a name or attribute, so learning them and calling on Allah by them is a good deed. Editions of Tirmidhi differ slightly (e.g. some lack “Al-Ahad”). This app follows the common order."}}, {"type": "text", "text": {"bn": "আল্লাহর নাম শুধু ৯৯-এ সীমাবদ্ধ নয়। রাসুল ﷺ-এর একটি দোয়ায় আছে: “আপনার প্রতিটি নামের উসিলায় চাই, যা আপনি নিজের জন্য রেখেছেন... অথবা আপনার কাছে গায়েবের জ্ঞানে গোপন রেখেছেন।” অর্থাৎ ৯৯টি নাম হলো এমন নাম যা আয়ত্ত করলে জান্নাতের প্রতিশ্রুতি আছে।", "en": "Allah''s names are not limited to 99. A dua of the Prophet ﷺ says: “I ask You by every name that is Yours… or that You kept in the knowledge of the unseen with You.” The 99 are those whose comprehension carries the promise of Paradise."}}, {"type": "ref", "text": {"bn": "মুসনাদ আহমাদ", "en": "Musnad Ahmad"}, "check": true}]', 'in_review', 180 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
INSERT INTO is_guides (id, topic_id, slug, title, summary, level, blocks, review_status, sort_order) SELECT 'd36d4838-89eb-5d29-962b-15ceabfd8615', id, 'fazilat-ramadan', '{"bn": "রমজান মাস ও রোজার ফজিলত", "en": "Virtues of Ramadan and fasting"}', '{"bn": "রমজানে জান্নাতের দরজা খোলা থাকে, ঈমান ও সওয়াবের আশায় রোজা রাখলে আগের গুনাহ মাফ, আর রোজাদারের জন্য রাইয়ান দরজা।", "en": "In Ramadan the gates of Paradise open, fasting it with faith and hope of reward forgives past sins, and the gate of Rayyan awaits the fasting."}', 'basic', '[{"type": "text", "text": {"bn": "আল্লাহ বলেন: “রমজান মাস, যাতে কুরআন নাজিল হয়েছে মানুষের জন্য হেদায়াত হিসেবে... সুতরাং তোমাদের মধ্যে যে এই মাস পাবে, সে যেন রোজা রাখে।”", "en": "Allah says: “The month of Ramadan in which the Quran was revealed as guidance for mankind… So whoever of you witnesses the month, let him fast it.”"}}, {"type": "ref", "text": {"bn": "সূরা বাকারা ২:১৮৩–১৮৫", "en": "Al-Baqarah 2:183–185"}}, {"type": "text", "text": {"bn": "রমজান এলে জান্নাতের দরজাগুলো খুলে দেওয়া হয়, জাহান্নামের দরজাগুলো বন্ধ করা হয় এবং শয়তানদের শিকলবন্দি করা হয়।", "en": "When Ramadan comes, the gates of Paradise are opened, the gates of Hell are closed and the devils are chained."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৮৯৯; সহিহ মুসলিম ১০৭৯", "en": "Sahih al-Bukhari 1899; Sahih Muslim 1079"}}, {"type": "heading", "text": {"bn": "রোজার ফজিলত", "en": "Virtues of fasting"}}, {"type": "text", "text": {"bn": "যে ঈমানের সঙ্গে ও সওয়াবের আশায় রমজানের রোজা রাখে, তার আগের গুনাহ মাফ করে দেওয়া হয়।", "en": "Whoever fasts Ramadan out of faith and hoping for reward, his previous sins are forgiven."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ৩৮; সহিহ মুসলিম ৭৬০", "en": "Sahih al-Bukhari 38; Sahih Muslim 760"}}, {"type": "text", "text": {"bn": "হাদিসে কুদসিতে আল্লাহ বলেন: আদম সন্তানের প্রতিটি আমল তার নিজের জন্য, রোজা ছাড়া; রোজা আমার জন্য, আর আমিই এর প্রতিদান দেব। রোজাদারের দুটি আনন্দ: ইফতারের সময় এবং রবের সঙ্গে সাক্ষাতের সময়। রোজাদারের মুখের গন্ধ আল্লাহর কাছে মিশকের চেয়েও সুগন্ধময়।", "en": "In a hadith qudsi Allah says: every deed of the son of Adam is for himself except fasting; it is for Me and I will reward it. The fasting person has two joys: at breaking the fast and when meeting his Lord. The smell of his mouth is better to Allah than musk."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৯০৪; সহিহ মুসলিম ১১৫১", "en": "Sahih al-Bukhari 1904; Sahih Muslim 1151"}}, {"type": "text", "text": {"bn": "জান্নাতে “রাইয়ান” নামে একটি দরজা আছে; কিয়ামতের দিন শুধু রোজাদাররাই সেখান দিয়ে প্রবেশ করবে।", "en": "In Paradise there is a gate called ar-Rayyan; only those who fasted will enter through it on the Day of Resurrection."}}, {"type": "ref", "text": {"bn": "সহিহ বুখারি ১৮৯৬; সহিহ মুসলিম ১১৫২", "en": "Sahih al-Bukhari 1896; Sahih Muslim 1152"}}, {"type": "heading", "text": {"bn": "রমজানের অন্যান্য আমল", "en": "Other deeds of Ramadan"}}, {"type": "list", "items": [{"bn": "ঈমান ও সওয়াবের আশায় রমজানের রাতে নামাজ (তারাবিহ) পড়লে আগের গুনাহ মাফ হয় (সহিহ বুখারি ৩৭)।", "en": "Praying the nights of Ramadan (tarawih) with faith and hope forgives past sins (Sahih al-Bukhari 37)."}, {"bn": "সাহরি খাও, কারণ সাহরিতে বরকত আছে (সহিহ বুখারি ১৯২৩)।", "en": "Eat suhur, for in suhur there is blessing (Sahih al-Bukhari 1923)."}, {"bn": "যে রোজাদারকে ইফতার করায়, সে রোজাদারের সমান সওয়াব পায়, রোজাদারের সওয়াব একটুও কমে না (সুনান তিরমিজি ৮০৭)।", "en": "Whoever gives iftar to a fasting person gets his reward without it decreasing his (Jami'' at-Tirmidhi 807)."}, {"bn": "রমজানে জিবরিল (আ.) প্রতি রাতে রাসুল ﷺ-এর সঙ্গে কুরআন পুনরাবৃত্তি করতেন, আর তখন তিনি প্রবাহিত বাতাসের চেয়েও বেশি দানশীল হতেন (সহিহ বুখারি ৬)।", "en": "In Ramadan Jibril reviewed the Quran with the Prophet ﷺ every night, and he was more generous than the blowing wind (Sahih al-Bukhari 6)."}, {"bn": "রমজানে উমরাহ করা হজের সমান সওয়াব (সহিহ মুসলিম ১২৫৬)।", "en": "Umrah in Ramadan equals a hajj in reward (Sahih Muslim 1256)."}, {"bn": "রাসুল ﷺ ইন্তেকাল পর্যন্ত রমজানের শেষ দশ দিন ইতিকাফ করতেন (সহিহ বুখারি ২০২৬)।", "en": "The Prophet ﷺ observed i''tikaf in the last ten days of Ramadan until he passed away (Sahih al-Bukhari 2026)."}]}, {"type": "note", "tone": "warn", "text": {"bn": "যে মিথ্যা কথা ও মিথ্যা অনুযায়ী কাজ ছাড়ে না, তার খাবার-পানীয় ছেড়ে দেওয়ায় আল্লাহর কোনো প্রয়োজন নেই (সহিহ বুখারি ১৯০৩)।", "en": "Whoever does not give up false speech and acting upon it, Allah has no need of his leaving food and drink (Sahih al-Bukhari 1903)."}}, {"type": "note", "tone": "info", "text": {"bn": "“রমজানের প্রথম দশ দিন রহমত, মাঝের দশ দিন মাগফিরাত, শেষ দশ দিন জাহান্নাম থেকে মুক্তি” — এই প্রসিদ্ধ বর্ণনাটি সহিহ ইবনে খুযাইমা ও বায়হাকিতে এসেছে, কিন্তু এর সনদ দুর্বল। পুরো রমজানই রহমত, মাগফিরাত ও মুক্তির মাস।", "en": "The popular report “the first ten days of Ramadan are mercy, the middle forgiveness, the last freedom from Hell” is in Sahih Ibn Khuzaymah and al-Bayhaqi but its chain is weak. The whole of Ramadan is a month of mercy, forgiveness and release."}}]', 'in_review', 190 FROM is_guide_topics WHERE slug = 'fazilat' ON CONFLICT (slug) DO NOTHING;
